local _, addonTable = ...
addonTable.gossip_hashed = addonTable.gossip_hashed or { version = 1, rows = {} }
local rows = {
    [1005874980] = {
        ["english"] = { [1] = "Looking to take a ride on a gryphon, now are ye?  Gryth Thurden is the one ye'll want to be seeing about that.  \010\010Ye can find him on the eastern side of The Great Forge in the middle of Ironforge." },
        ["text"] = "Хочеш прокататися на грифоні, еге?  Тоді тобі потрібен Ґрит Турден.  \010\010Знайдеш його на східному боці Великого Горна в самому серці Залізогарта.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3637054510] = {
        ["english"] = { [1] = "Many have come to this sanctuary, few have left. " },
        ["text"] = "Багато хто прийшов до цього святилища, але мало хто пішов звідси. ",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [3095318723] = {
        ["english"] = { [1] = "Legion? Demons? They hunt you? My people have also been hunted by Legion: Targeted by their dark masters for damnation.$B$B<Cowlen wipes the tears away.>$B$BIt is the reason that I moved my family here oh-so-many years ago." },
        ["text"] = "Легіон? Демони? Вони полюють на тебе? Мій народ теж переслідував Легіон: їхні темні володарі прирекли нас на погибель.$B$B<Коулен витирає сльози.>$B$BСаме тому багато-багато років тому я перевіз сюди свою родину.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2880226836] = {
        ["english"] = { [1] = "Show me your wares, Wilhelm." },
        ["text"] = "Покажи свої товари, Вільгельме.",
        ["npcs"] = { [1] = 16376 },
        ["roles"] = { ["reply"] = true },
    },
    [2682779653] = {
        ["english"] = { [1] = "Keep it down!  I don't want them to see me over here.$B$BOoh, this really burns me up!  Who do these ethereals think they are?$B$BThis is MY claim!" },
        ["text"] = "Тихіше!  Не хочу, щоб вони мене тут побачили.$B$BОх, це мене просто розлютило!  Ким ці ефіріали себе вважають?$B$BЦе МОЯ ділянка!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2373431616] = {
        ["english"] = { [1] = "Oh dear.  Things aren't looking good for Felix." },
        ["text"] = "Ой лишенько.  Справи Фелікса кепські.",
        ["npcs"] = { [1] = 8416 },
        ["roles"] = { ["greeting"] = true },
    },
    [2382389006] = {
        ["english"] = { [1] = "Look to this ravaged field and know the power that the elements hold, $r." },
        ["text"] = "Поглянь на це спустошене поле й пізнай силу стихій, $r.",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [1609013284] = {
        ["english"] = { [1] = "Of course I can help you with training. I'm just a journeyman myself, but I'm sure there's something I can show you." },
        ["text"] = "Звісно, допоможу з навчанням. Я й сам лише підмайстер, але точно знайдеться щось, чого я можу тебе навчити.",
        ["npcs"] = { [1] = 514 },
        ["roles"] = { ["greeting"] = true },
    },
    [769441277] = {
        ["english"] = { [1] = "Our way is sacred.  We will choose death before we abandon Thorim and join the likes of the Lich King." },
        ["text"] = "Наш шлях священний.  Ми радше оберемо смерть, ніж покинемо Торіма й приєднаємося до подібних Королю-лічу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [964546817] = {
        ["english"] = { [1] = "Lok'tar. Don't try anything suspicious around here. If these undead are going to be part of the Horde, they're going to mind themselves under our watch." },
        ["text"] = "Лок’тар. Не роби тут нічого підозрілого. Якщо ці невмерлі хочуть бути частиною Орди, то під нашим наглядом поводитимуться як слід.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2781666938] = {
        ["english"] = { [1] = "Please, leave an old spirit in peace." },
        ["text"] = "Будь ласка, залиш старого духа в спокої.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4841879] = {
        ["english"] = { [1] = "Och... a paladin?  Well $glad : lass;, ye're in luck!  Azar Stronghammer is back from training and is currently staying at the Thunderbrew Distillery in Kharanos." },
        ["text"] = "Ох... паладин?  Ну, $gхлопче : дівчино;, тобі пощастило!  Азар Міцномолот повернувся з тренувань і зараз зупинився в Ґуральні Громоварів у Караносі.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1306151077] = {
        ["english"] = { [1] = "Ok, so where the hell is he? Wait a minute! Are you drunk?" },
        ["text"] = "Гаразд, то де він, до біса? Секунду! Ти п’яний?",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [3647337731] = {
        ["english"] = { [1] = "May the Sun's light protect you, $c." },
        ["text"] = "Нехай сонячне світло захищає тебе, $c.",
        ["npcs"] = { [1] = 8664 },
        ["roles"] = { ["greeting"] = true },
    },
    [4003155546] = {
        ["english"] = { [1] = "Not enough, you need to tell me more." },
        ["text"] = "Недостатньо. Розкажи мені більше.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [528494105] = {
        ["english"] = { [1] = "Seek out Miao'zan in Sen'jin Village to the south." },
        ["text"] = "Шукай Мяо’зана в селищі Сен’джин на півдні.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [369645735] = {
        ["english"] = { [1] = "Polar Tunic." },
        ["text"] = "Полярна туніка.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2964448409] = {
        ["english"] = { [1] = "Let me think about it, Zamael." },
        ["text"] = "Дай мені подумати, Замаелю.",
        ["npcs"] = { [1] = 8436 },
        ["roles"] = { ["reply"] = true },
    },
    [1051975486] = {
        ["english"] = { [1] = "Soon we shall rid Azeroth of the silithids' abominable presence.  Their potential for destruction is much greater than what you've seen firsthand, $N.  Greater, darker powers are behind their activities." },
        ["text"] = "Скоро ми очистимо Азерот від огидної присутності силітидів.  Їхній руйнівний потенціал значно більший за те, що ти бачив на власні очі, $N.  За їхніми діями стоять могутніші й темніші сили.",
        ["npcs"] = { [1] = 15609 },
        ["roles"] = { ["greeting"] = true },
    },
    [3022584479] = {
        ["english"] = { [1] = "Shadowfang Keep" },
        ["text"] = "Фортеця Тіньового Ікла",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2890647149] = {
        ["english"] = { [1] = "My family worked  the Northridge Lumber Mill in what's now Western Plaguelands. They were dedicated to the Dumah family, and now the Scarlet Crusade have taken it over along with all of Hearthglen!$B$BI will not rest until those zealots are wiped from Azeroth." },
        ["text"] = "Моя родина працювала на Нортріджській лісопильні, що нині в Західному Чумозем’ї. Вони віддано служили родині Дума, а тепер Багряний Похід захопив лісопильню разом з усім Долинним Вогнищем!$B$BЯ не спочину, доки цих фанатиків не зітруть з Азероту.",
        ["npcs"] = { [1] = 11615 },
        ["roles"] = { ["greeting"] = true },
    },
    [1035579870] = {
        ["english"] = { [1] = "Of course, of course.  Please speak with Deze Snowbane at the Hall of the Brave in the Valley of Honor of this city, $c." },
        ["text"] = "Звісно, звісно.  Поговори з Дезе Снігогубом у Залі Хоробрих у Долині Честі цього міста, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2165610223] = {
        ["english"] = { [1] = "No, $N, you did not. I do not fault you, however, as yours is a mind much like mine was as a youth: Impetuous, rebellious, and often without a single coherent thought! Traits I can no longer afford to express.$B$BEnough lamenting. $R, I have a task for you; one that you may not survive. " },
        ["text"] = "Ні, $N, не зробив. Та я тебе не звинувачую: твій розум дуже схожий на мій у юності — запальний, бунтівний і часто без жодної зв’язної думки! Тепер я вже не можу дозволити собі таких рис.$B$BДосить жалітися. $R, у мене є для тебе завдання — і ти можеш його не пережити. ",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["greeting"] = true },
    },
    [1471885280] = {
        ["english"] = { [1] = "Pele'keiki know, it seem impossible even to him, but we be havin' all that firebloom the Horde be wantin' for the war. If you not be feelin' too lazy, Pele'keiki think you be helpin' out the others here. They sure to have many things they be wantin' you to get for them." },
        ["text"] = "Пеле’кейкі знати, це навіть йому здаватися неможливим, але ми мати весь вогнецвіт, що Орда хотіти для війни. Якщо ти не надто ледачий, Пеле’кейкі думати, ти допомогти іншим тут. Вони точно мати багато речей, які хотіти, щоб ти їм принести.",
        ["npcs"] = { [1] = 15508 },
        ["roles"] = { ["greeting"] = true },
    },
    [1946205370] = {
        ["english"] = { [1] = "Let's taste more!" },
        ["text"] = "Скуштуймо ще!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3827803134] = {
        ["english"] = { [1] = "Proper sustenance will keep a soldier alive long after the wounds of the battlefield should have finished $g him : her; off, $c. If we're to persevere in the Ahn'Qiraj War to come, we'll need all of the provisions that we can carry. I'm gathering up spotted yellowtail fish at this location before it is to be shipped out.$B$BAs of now we have $2101w, but we need to collect a total of $2103w if we're going to be able to feed everyone." },
        ["text"] = "Добра пожива збереже солдатові життя навіть тоді, коли рани з поля бою мали б уже добити $g його : її;, $c. Якщо хочемо вистояти в майбутній війні в Ан’Кіражі, нам знадобляться всі припаси, які зможемо нести. Я збираю тут плямистого жовтохвоста перед відправленням.$B$BЗараз маємо $2101w, але потрібно зібрати загалом $2103w, щоб нагодувати всіх.",
        ["npcs"] = { [1] = 15457 },
        ["roles"] = { ["greeting"] = true },
    },
    [1824875527] = {
        ["english"] = { [1] = "One set of trolls dealt with, one yet to go. You have no idea how much I appreciate what you're doing, $N! Before you came along I didn't think we'd ever get the Shadowpine problem under control." },
        ["text"] = "З одними тролями покінчено, залишилися ще одні. Ти й не уявляєш, як я ціную твою допомогу, $N! До твого приходу я вже не вірив, що ми колись владнаємо проблему Тіньової Сосни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2207528678] = {
        ["english"] = { [1] = "Lok'tar, $c, I have important information! There's a war coming at Ahn'Qiraj and we need to get ready for it. I'm here collecting all of the thick leather that I can get my hands on. Right now we have $2070w, but the Warchief has tasked me with the gathering of $2071w. As you can see, I'm a little short." },
        ["text"] = "Лок’тар, $c, маю важливі новини! Наближається війна в Ан’Кіражі, і нам треба готуватися. Я тут збираю всю щільну шкіру, яку тільки можу дістати. Зараз маємо $2070w, але Вождь наказав мені зібрати $2071w. Як бачиш, трохи не вистачає.",
        ["npcs"] = { [1] = 15522 },
        ["roles"] = { ["greeting"] = true },
    },
    [2950597009] = {
        ["english"] = { [1] = "So you suspect that someone on the inside was involved? They were tipped off?" },
        ["text"] = "То ти підозрюєш, що хтось зсередини був причетний? Їх попередили?",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [1166571066] = {
        ["english"] = { [1] = "Split in two to form the one. The twin blades are bound to Zul'Farrak.$B$BSul'thraze reborn when the twins are found." },
        ["text"] = "Розділені надвоє, щоб стати одним. Парні клинки пов’язані із Зул’Фарраком.$B$BСул’тразе відродиться, коли близнюків буде знайдено.",
        ["npcs"] = { [1] = 7804, [2] = 8115 },
        ["roles"] = { ["greeting"] = true },
    },
    [3172306686] = {
        ["english"] = { [1] = "Loken?! That's downright bothersome... We might've neutralized the iron dwarves, but I'd lay odds there's another machine somewhere else churnin' out a whole mess o' these iron vrykul!" },
        ["text"] = "Локен?! Оце вже справді кепсько... Може, ми й знешкодили залізних дворфів, але закладаюся, десь іще є машина, що штампує цілу купу залізних врайкулів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2577993702] = {
        ["english"] = { [1] = "Sir, I need another flying machine..." },
        ["text"] = "Пане, мені потрібна ще одна літальна машина...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3314042315] = {
        ["english"] = { [1] = "Oh yeah, I got muffins!" },
        ["text"] = "О так, у мене є кекси!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4019088739] = {
        ["english"] = { [1] = "Spinebreaker Post is a great place to be stationed!  The Bleeding Hollow aberrations are so close you can smell their foul blood!  What better place to gather vengeance from a clan that has forsaken its brethren and made a pact with demons?" },
        ["text"] = "Застава Хребтолома — чудове місце для служби!  Потвори Кривавої Очниці так близько, що можна відчути сморід їхньої крові!  Де ще краще мститися клану, який зрікся своїх братів і уклав угоду з демонами?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1069119967] = {
        ["english"] = { [1] = "Like a cat dragged in from the rain, you scratch and claw, then do it all over again... I'll be back for more...$B$BOh, I didn't see you enter, $n! What can I do for you?" },
        ["text"] = "Наче кіт, якого витягли з-під дощу: дряпаєшся, пручаєшся — і все спочатку... Я ще повернуся по своє...$B$BОй, я й не помітив, як ти зайшов, $n! Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1268525174] = {
        ["english"] = { [1] = "My brothers in Stormwind told me not to join the military... I'm glad I didn't listen to them!" },
        ["text"] = "Мої брати в Штормовії казали мені не йти до війська... Добре, що я їх не послухав!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [297705336] = {
        ["english"] = { [1] = "Mark my words, these forsaken fools will be the death of us all!" },
        ["text"] = "Запам’ятай мої слова: ці дурні Відречені всіх нас погублять!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [144232866] = {
        ["english"] = { [1] = "Spend less time rattling and more time listening." },
        ["text"] = "Менше брязкай, більше слухай.",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [1696138588] = {
        ["english"] = { [1] = "Sometimes it feels like I'll never go back to being a simple functionary in service to Dame Auriferous. I'm not cut out for war.$B$BThankfully there are those like you who burn to see Quel'Thalas restored to its former beauty. Crush the Scourge, $c! Crush them wherever you can!" },
        ["text"] = "Іноді здається, що я вже ніколи не повернуся до простої служби в пані Ауріферос. Я не створений для війни.$B$BНа щастя, є такі, як ти, хто палає бажанням побачити Квел’Талас знову прекрасним. Трощи Батіг, $c! Трощи їх усюди, де зможеш!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3016896372] = {
        ["english"] = { [1] = "Speak with Regthar.  He is wise and can help you find what you seek." },
        ["text"] = "Поговори з Реґтаром.  Він мудрий і допоможе знайти те, що шукаєш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [846698310] = {
        ["english"] = { [1] = "Speak with Lawrence Shneider at Duncan's Textiles around the corner to the left. He is adept at dealing with beginners." },
        ["text"] = "Поговори з Лоуренсом Шнайдером у «Тканинах Дункана» за рогом ліворуч. Він добре вміє працювати з новачками.",
        ["npcs"] = { [1] = 5567 },
        ["roles"] = { ["greeting"] = true },
    },
    [3065783753] = {
        ["english"] = { [1] = "It's my passion, you know. In life and in death, armorcrafting is what I love. Please, treat me as if I were a living draenei, stranger. Let me know what it is to feel again... Allow me the honor of repairing your items." },
        ["text"] = "Це моя пристрасть, знаєш. За життя й після смерті я понад усе люблю ковальство обладунків. Будь ласка, стався до мене так, наче я живий дреней, незнайомцю. Дай мені знову відчути, що це таке... Дозволь мені мати честь полагодити твої речі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3027254505] = {
        ["english"] = { [1] = "Skinning?  The only thing ye look like ye could skin is yer own knee!  Ha!  Now why don't you go see Balthus Stoneflayer so he can teach you how to properly skin some animals.  You'll find him in Finespindle's Leather Goods on the northern side of The Great Forge." },
        ["text"] = "Зняття шкур?  Та з таким виглядом ти хіба власне коліно обдереш!  Ха!  Іди краще до Балтуса Каменешкура, хай навчить правильно знімати шкури з тварин.  Знайдеш його в «Шкіряних товарах Файнспіндла» на північному боці Великого Горна.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [4119054325] = {
        ["english"] = { [1] = "Just a few more and our stables will be overflowing with mounts. Release it into my custody, soldier. I'll take it from here." },
        ["text"] = "Ще трохи — і наші стайні будуть переповнені їздовими тваринами. Передай її мені, солдате. Далі я сам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2244260224] = {
        ["english"] = { [1] = "Speak with Hydraxis." },
        ["text"] = "Поговори з Гідраксісом.",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [3803369826] = {
        ["english"] = { [1] = "Looking for a tabard?" },
        ["text"] = "Шукаєш гербову накидку?",
        ["npcs"] = { [1] = 5188, [2] = 5189, [3] = 5190, [4] = 5191 },
        ["roles"] = { ["greeting"] = true },
    },
    [3156524881] = {
        ["english"] = { [1] = "No, Ulathek.  He knows your secret.  He knows you plot with Lord Hel'nurath of Xoroth." },
        ["text"] = "Ні, Улатеку.  Він знає твою таємницю.  Він знає, що ти змовляєшся з лордом Гел’нуратом із Ксорота.",
        ["npcs"] = { [1] = 14523 },
        ["roles"] = { ["reply"] = true },
    },
    [2643787052] = {
        ["english"] = { [1] = "My father has gifted me with his battle armor and axe. Soon I put it to good use." },
        ["text"] = "Батько подарував мені свій бойовий обладунок і сокиру. Скоро я знайду їм добре застосування.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4192246500] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to warlocks." },
        ["text"] = "Вибач, але мої послуги корисні лише чорнокнижникам.",
        ["npcs"] = { [1] = 5520, [2] = 5749, [3] = 5750, [4] = 5753, [5] = 5815, [6] = 6027, [7] = 6328, [8] = 6373, [9] = 6374, [10] = 6382, [11] = 12776 },
        ["roles"] = { ["greeting"] = true },
    },
    [2039098915] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to warriors." },
        ["text"] = "Вибач, але мої послуги корисні лише воїнам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [472372239] = {
        ["english"] = { [1] = "Situated along the Zoram Strand of Ashenvale, Blackfathom Deeps was once a glorious temple dedicated to the night elves' moon-goddess Elune. However, the great Sundering shattered the temple - sinking it beneath the waves of the Veiled Sea. There it remained untouched - until, drawn by its ancient power - the naga and satyr emerged to plumb its secrets. Legends hold that the ancient beast, Aku'mai, has taken up residence within the temple's ruins. \010" },
        ["text"] = "Розташовані вздовж Зорамського узбережжя Ясенедолу, Чорноводні глибини колись були величним храмом, присвяченим місячній богині нічних ельфів Елуні. Та Великий Розкол розтрощив храм і затопив його під хвилями Завуальованого моря. Там він стояв недоторканим, доки його давня сила не привабила наґів і сатирів, які почали вивідувати його таємниці. Легенди кажуть, що в руїнах храму оселився древній звір Аку’май. ",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [520087137] = {
        ["english"] = { [1] = "My apologies, but you have already learned everything I know. The night elf Faldron could offer you further training, however. Look for him in the Craftsmen's Terrace of Darnassus." },
        ["text"] = "Перепрошую, але ти вже знаєш усе, чого я можу навчити. Проте нічний ельф Фалдрон може продовжити твоє навчання. Шукай його на Терасі Ремісників у Дарнасі.",
        ["npcs"] = { [1] = 3605 },
        ["roles"] = { ["greeting"] = true },
    },
    [3682263001] = {
        ["english"] = { [1] = "Just because it's not my heart doesn't mean it can't be broken." },
        ["text"] = "Те, що це не моє серце, ще не означає, що його не можна розбити.",
        ["npcs"] = { [1] = 1498, [2] = 2050, [3] = 2055, [4] = 2227, [5] = 2308, [6] = 2799, [7] = 2802, [8] = 2934, [9] = 4486, [10] = 4553, [11] = 4554, [12] = 4555, [13] = 4557, [14] = 4558, [15] = 4559, [16] = 4560, [17] = 4561, [18] = 4562, [19] = 4569, [20] = 4570, [21] = 4572, [22] = 4574, [23] = 4575, [24] = 4577, [25] = 4580, [26] = 4581, [27] = 4585, [28] = 4587, [29] = 4589, [30] = 4590, [31] = 4592, [32] = 4597, [33] = 4599, [34] = 4600, [35] = 4601, [36] = 4602, [37] = 4603, [38] = 4604, [39] = 4610, [40] = 4612, [41] = 4615, [42] = 4617, [43] = 4775, [44] = 5543, [45] = 5624, [46] = 5651, [47] = 5655, [48] = 5656, [49] = 5657, [50] = 5658, [51] = 5659, [52] = 5660, [53] = 5668, [54] = 5669, [55] = 5670, [56] = 5693, [57] = 5701, [58] = 5703, [59] = 5704, [60] = 5705, [61] = 5706, [62] = 5707, [63] = 5731, [64] = 5732, [65] = 5733, [66] = 5744, [67] = 5747, [68] = 5754, [69] = 5819, [70] = 5820, [71] = 5821, [72] = 6293, [73] = 6411, [74] = 6467, [75] = 6522, [76] = 7297, [77] = 7825, [78] = 8390, [79] = 8403, [80] = 10136, [81] = 11750, [82] = 14402, [83] = 14403, [84] = 14404, [85] = 16004, [86] = 16108 },
        ["roles"] = { ["greeting"] = true },
    },
    [2858312051] = {
        ["english"] = { [1] = "Speak to Grezz Ragefist in the Hall of the Brave, which is in the Valley of Honor.  Put in a good word for me!" },
        ["text"] = "Поговори з Ґреззом Лютокулаком у Залі Хоробрих у Долині Честі.  Замов за мене добре слово!",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2959898151] = {
        ["english"] = { [1] = "Last I knew, Elder Stonespire was at Everlook in Winterspring." },
        ["text"] = "Наскільки мені відомо, старійшина Кам’яний Шпиль був у Завшегляді в Зимоключі.",
        ["npcs"] = { [1] = 15603, [2] = 15605, [3] = 15606 },
        ["roles"] = { ["greeting"] = true },
    },
    [2290217800] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to rogues." },
        ["text"] = "Вибач, але мої послуги корисні лише розбійникам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [474052142] = {
        ["english"] = { [1] = "Now that I've been beaten to within an inch of my life what do you want?" },
        ["text"] = "Тепер, коли мене відлупцювали майже до смерті, чого тобі треба?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1375854264] = {
        ["english"] = { [1] = "Look for the Zeppelin Landing Tower outside of the city to the southeast." },
        ["text"] = "Шукай вежу причалу дирижаблів за містом, на південний схід.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3339092542] = {
        ["english"] = { [1] = "Oh... I'm feeling groggy..." },
        ["text"] = "О... у мене голова паморочиться...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2417159828] = {
        ["english"] = { [1] = "Show me the drinks!" },
        ["text"] = "Покажи напої!",
        ["npcs"] = { [1] = 14844 },
        ["roles"] = { ["reply"] = true },
    },
    [2602381140] = {
        ["english"] = { [1] = "Messengers from Ravenholdt delivered this letter to me this morning. It is addressed to you, $N." },
        ["text"] = "Посланці з Рейвенгольдта принесли мені цього листа сьогодні вранці. Він адресований тобі, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2561602315] = {
        ["english"] = { [1] = "Never look the Commander directly in the eyes." },
        ["text"] = "Ніколи не дивися Командирові просто в очі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2917750559] = {
        ["english"] = { [1] = "Now that the deserters have taken over Lost Point, North Point Tower is the most distant of Theramore's outposts." },
        ["text"] = "Тепер, коли дезертири захопили Загублену Точку, Вежа Північної Точки стала найдальшою заставою Терамора.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1888345396] = {
        ["english"] = { [1] = "Speak slowly, child, I am new to your strange tongue." },
        ["text"] = "Говори повільніше, дитино, я ще не звик до вашої дивної мови.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3964718428] = {
        ["english"] = { [1] = "My brother Krixx thinks he has it bad working in Orgrimmar. Nothing compares to the stench of this place. At least the boss had the decency to give me hazard pay!$B$BWhat? Do you want to see where the zeppelin is? Good thing I've got my zeppelin tracker right here!" },
        ["text"] = "Мій брат Крікс думає, що йому погано працюється в Орґріммарі. Ніщо не зрівняється зі смородом цього місця. Добре хоч бос доплачує за шкідливі умови!$B$BЩо? Хочеш побачити, де дирижабль? Добре, що в мене тут є його відстежувач!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3543322223] = {
        ["english"] = { [1] = "Master craftsman Omarion just vanished one night. Like a toot in the wind... Poof! Gone! Bah, now I'm the only one left to craft the goods for the boys on the front lines. " },
        ["text"] = "Майстер-ремісник Омаріон просто зник однієї ночі. Наче пук у вітрі... Пуф! І нема! Тьху, тепер я один лишився виготовляти спорядження для хлопців на передовій. ",
        ["npcs"] = { [1] = 16376 },
        ["roles"] = { ["greeting"] = true },
    },
    [1517130923] = {
        ["english"] = { [1] = "Speak quietly and with great care, the wrong word in these parts could get your throat cut. Now, what is it you need from me?" },
        ["text"] = "Говори тихо й дуже обережно — одне невдале слово в цих краях може коштувати тобі горла. Ну, що тобі від мене потрібно?",
        ["npcs"] = { [1] = 1325, [2] = 1326 },
        ["roles"] = { ["greeting"] = true },
    },
    [2131604731] = {
        ["english"] = { [1] = "One bright light appears accross the room, then disppears. Then you notice another beam... and then another.$B$BThey seem to be showing you a pattern." },
        ["text"] = "На іншому боці кімнати з’являється яскравий промінь і зникає. Потім ти помічаєш ще один... і ще один.$B$BСхоже, вони показують певну послідовність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4191040814] = {
        ["english"] = { [1] = "Kodohide Leatherworkers is what you want.  Find it in the middle of The Drag." },
        ["text"] = "Тобі потрібні шкіряники «Шкура кодо».  Знайдеш їх посеред Хитрого провулка.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [4244076204] = {
        ["english"] = { [1] = "Move along, citizen. There is nothing to see here." },
        ["text"] = "Проходьте, громадянине. Тут немає на що дивитися.",
        ["npcs"] = { [1] = 14721 },
        ["roles"] = { ["greeting"] = true },
    },
    [3332183212] = {
        ["english"] = { [1] = "Missing US text." },
        ["text"] = "Відсутній текст US.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3487706834] = {
        ["english"] = { [1] = "Our gunnery instructor, he Ansekhwa, da tauren weapon master on da lower central rise of Thunder Bluff." },
        ["text"] = "Наш наставник зі стрілецької зброї — Ансеква, таурен-майстер зброї на нижньому центральному виступі Громового Бескиду.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [722140911] = {
        ["english"] = { [1] = "Make this inn your home." },
        ["text"] = "Зроби цей заїзд своїм домом.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2832932608] = {
        ["english"] = { [1] = "None are as skilled in the use of weapons as Ansekhwa.  It is said that he is guided by the spirits of the finest warriors of our honored ancestors.  Seek him out on the lower rise and he will teach you what you want to know." },
        ["text"] = "Ніхто не володіє зброєю так майстерно, як Ансеква.  Кажуть, ним керують духи найвеличніших воїнів наших шанованих предків.  Знайди його на нижньому виступі, і він навчить тебе всього, що потрібно.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2262459737] = {
        ["english"] = { [1] = "No luck with the Twilight's Hammer deserter?  Check the mountains to the southeast thoroughly.  There are numerous rumors of a mysterious hermit living there." },
        ["text"] = "Не пощастило з дезертиром Сутінкового Молота?  Ретельно обшукай гори на південному сході.  Ходить чимало чуток про таємничого самітника, що живе там.",
        ["npcs"] = { [1] = 15183 },
        ["roles"] = { ["greeting"] = true },
    },
    [495665082] = {
        ["english"] = { [1] = "Kneel beside me, friend. I caught a bullet during that last raid.$B$B<Gann grunts in pain as he tries to shift position. His left hand clutches a wound, blood welling between his quivering fingers.>$B$BWhen the dwarves first invaded the Barrens, I contented myself with harassing their diggers and sabotaging their equipment. I should've struck a killing blow when I had the chance." },
        ["text"] = "Стань навколішки біля мене, друже. Під час останнього нальоту я спіймав кулю.$B$B<Ґанн стогне від болю, намагаючись змінити положення. Лівою рукою він стискає рану, а між тремтячими пальцями проступає кров.>$B$BКоли дворфи вперше вторглися в Степи, я задовольнявся тим, що дошкуляв їхнім землекопам і псував спорядження. Треба було завдати смертельного удару, коли мав нагоду.",
        ["npcs"] = { [1] = 3341 },
        ["roles"] = { ["greeting"] = true },
    },
    [95127860] = {
        ["english"] = { [1] = "Speak not your vulgar language to me!  Only Hydraxis can stand it." },
        ["text"] = "Не говори зі мною своєю вульгарною мовою!  Лише Гідраксіс її витримує.",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [2462105351] = {
        ["english"] = { [1] = "Keeping your ram in a canter or gallop for too long will exhaust him. If you want your ram to recover a bit, let him walk or trot. If there are apple bushels around, take him there to recover.$B$B" },
        ["text"] = "Якщо занадто довго тримати барана на легкому чи швидкому галопі, він виснажиться. Щоб дати йому трохи відпочити, переведи його на крок або рись. Якщо поблизу є кошики з яблуками, підведи його до них, щоб він відновив сили.$B$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2266287807] = {
        ["english"] = { [1] = "Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault." },
        ["text"] = "Жаль. Це все, що в мене лишилося. Одне погане рішення призвело до кількох жахливих наслідків. Якби ж я дочекався тих наказів. Може, вони попереджали про жахи, що чекали нас у тих проклятих землях! Може, мали перенаправити нас на інше завдання? Зрештою, це була моя провина. Усе було моєю провиною.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [2452050286] = {
        ["english"] = { [1] = "So... what's inside Uldum?" },
        ["text"] = "Отже... що всередині Ульдуму?",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["reply"] = true },
    },
    [2961896096] = {
        ["english"] = { [1] = "Listen, you tell Schweitzer and Roitau that we've got everything under control here. They don't gotta... what?$B$BThey didn't send you? Then what are you wasting my time for?$B$BI've got work to do!" },
        ["text"] = "Слухай, передай Швейцеру й Ройтау, що тут у нас усе під контролем. Їм не треба... що?$B$BВони тебе не посилали? Тоді чого ти марнуєш мій час?$B$BУ мене роботи по горло!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [543900561] = {
        ["english"] = { [1] = "Nice day for flying, isn't it?" },
        ["text"] = "Чудовий день для польоту, правда?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1689520411] = {
        ["english"] = { [1] = "Michael Garrett on upper ring in Trade Quarter." },
        ["text"] = "Майкл Ґарретт на верхньому кільці Торгового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1306819016] = {
        ["english"] = { [1] = "Sounds like you want to talk to Maginor Dumas! You can usually find him in the Wizard's Sanctum in the Mage Quarter. Course, you never know when or where those magi will portal off to." },
        ["text"] = "Схоже, тобі треба поговорити з Маґінором Дюма! Зазвичай він у Святилищі чарівників у Кварталі Магів. Хоча з цими магами ніколи не знаєш, коли й куди вони телепортуються.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1269646431] = {
        ["english"] = { [1] = "Little goblin on top of building north of Ruins of Lordaeron.  Leave Undercity and you go there." },
        ["text"] = "Малий гоблін на даху будівлі північніше руїн Лордерону.  Вийди з Підміста й іди туди.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2062732297] = {
        ["english"] = { [1] = "Lord-Commander, I would hear your tale." },
        ["text"] = "Лорде-командувачу, я хочу почути вашу історію.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2671829567] = {
        ["english"] = { [1] = "So, $N, which item are you interested in?" },
        ["text"] = "Отже, $N, який предмет тебе цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [731606001] = {
        ["english"] = { [1] = "Oh, hi, $c. I guess the Alliance asked me to come here and keep track of all of this cooked meat that people are gathering because of the impending doom at Ahn'Qiraj. Doesn't that sound like fun?$B$BAnyway, I suppose you'd like to know how much we have. Last time I counted it we were at $2098w out of a total $2099w roast raptor needed." },
        ["text"] = "О, привіт, $c. Схоже, Альянс попросив мене прийти сюди й вести облік усього приготованого м’яса, яке люди збирають через близьку погибель в Ан’Кіражі. Весело звучить, правда?$B$BТак чи інакше, мабуть, хочеш знати, скільки в нас є. Востаннє я нарахував $2098w із загалом потрібних $2099w порцій смаженого раптора.",
        ["npcs"] = { [1] = 15456 },
        ["roles"] = { ["greeting"] = true },
    },
    [3683446648] = {
        ["english"] = { [1] = "Laurna Morninglight offers healing to those that live around Dolanaar.  Perhaps she would be able to teach you in the ways of a priest." },
        ["text"] = "Лорна Ранкове Світло зцілює мешканців околиць Доланаара.  Можливо, вона зможе навчити тебе шляху жерця.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2247273317] = {
        ["english"] = { [1] = "Oh, me a cook?  I suppose that's true.  A barmaid's got to work in the kitchens from time to time, and I've learned a few recipes over the years.  Nothing too special, but they're hearty enough to fill Grok's substantial belly." },
        ["text"] = "О, я кухарка?  Мабуть, так.  Буфетниці час від часу доводиться працювати на кухні, і за роки я вивчила кілька рецептів.  Нічого особливого, але вони досить ситні, щоб набити чималий живіт Ґрока.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2838099051] = {
        ["english"] = { [1] = "Sorry, I don't speak with the help." },
        ["text"] = "Вибач, я не розмовляю з прислугою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1340842123] = {
        ["english"] = { [1] = "Let me see the wyverns, Dama." },
        ["text"] = "Покажи мені віверн, Дамо.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3087344431] = {
        ["english"] = { [1] = "Sorry, friend. Only certified officers of the Horde can authorize the purchase of a vehicle." },
        ["text"] = "Вибач, друже. Лише сертифіковані офіцери Орди можуть дозволити купівлю транспортного засобу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1202678814] = {
        ["english"] = { [1] = "Rogue" },
        ["text"] = "Розбійник",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3296, [18] = 3571, [19] = 4262, [20] = 5595, [21] = 5624, [22] = 5725, [23] = 5953, [24] = 6272, [25] = 6740, [26] = 8931, [27] = 12996, [28] = 13076, [29] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [1045263667] = {
        ["english"] = { [1] = "Some were spared the anguish that memories provide." },
        ["text"] = "Декого оминули муки, які приносять спогади.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [918972272] = {
        ["english"] = { [1] = "Many of the supplies the tailors need come by way of Darnassus.  It is not surprising that they all moved there to work.  If you wish to be a tailor then you best head to Darnassus." },
        ["text"] = "Багато припасів, потрібних кравцям, надходить через Дарнас.  Не дивно, що всі вони перебралися працювати туди.  Якщо хочеш стати кравцем, тобі краще вирушити до Дарнаса.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [576165996] = {
        ["english"] = { [1] = "Registrants are required to speak with Warden Bullrok before posting any task.$B$BThose found making unapproved postings will be prosecuted.$B$BPost no bills." },
        ["text"] = "Перед розміщенням будь-якого завдання заявники зобов’язані поговорити з наглядачем Буллроком.$B$BОсіб, які розміщують несанкціоновані оголошення, буде притягнуто до відповідальності.$B$BОголошень не клеїти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3688190829] = {
        ["english"] = { [1] = "Sorry, friend. Only certified officers of the Alliance can authorize the purchase of a vehicle." },
        ["text"] = "Вибач, друже. Лише сертифіковані офіцери Альянсу можуть дозволити купівлю транспортного засобу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2642958473] = {
        ["english"] = { [1] = "Many an advantage can be gained from getting to know your enemy.  Take that lesson to heart, $N.$B$BThe more we learn about the Scourge the better prepared we are to defeat them." },
        ["text"] = "Знання ворога дає чимало переваг.  Добре засвой цей урок, $N.$B$BЩо більше ми дізнаємося про Батіг, то краще підготуємося до перемоги над ним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3929971245] = {
        ["english"] = { [1] = "Let me browse your goods." },
        ["text"] = "Дозволь поглянути на твої товари.",
        ["npcs"] = { [1] = 1247, [2] = 1464, [3] = 2388, [4] = 2808, [5] = 3934, [6] = 4241, [7] = 4556, [8] = 5111, [9] = 5188, [10] = 5189, [11] = 5190, [12] = 5191, [13] = 5688, [14] = 6091, [15] = 6272, [16] = 6734, [17] = 6739, [18] = 6740, [19] = 6741, [20] = 6746, [21] = 7714, [22] = 7737, [23] = 7744, [24] = 8931, [25] = 9501, [26] = 9676, [27] = 10618, [28] = 11106, [29] = 11116, [30] = 11557, [31] = 14637, [32] = 14731, [33] = 14847, [34] = 15175, [35] = 15176, [36] = 15179, [37] = 16256 },
        ["roles"] = { ["reply"] = true },
    },
    [1657237618] = {
        ["english"] = { [1] = "Let me browse your selection of fireworks." },
        ["text"] = "Дозволь поглянути на твій вибір феєрверків.",
        ["npcs"] = { [1] = 15011, [2] = 15012 },
        ["roles"] = { ["reply"] = true },
    },
    [3815149476] = {
        ["english"] = { [1] = "Sorry, but you've reached the limit of what I can teach. If you want to learn more, go see Telonis in the Craftsmen's Terrace of Darnassus. He's pretty talented, so I hear." },
        ["text"] = "Вибач, але ти вже досяг межі того, чого я можу навчити. Якщо хочеш знати більше, знайди Телоніса на Терасі Ремісників у Дарнасі. Кажуть, він дуже талановитий.",
        ["npcs"] = { [1] = 5564 },
        ["roles"] = { ["greeting"] = true },
    },
    [870633391] = {
        ["english"] = { [1] = "Sorry, but we'll have to speak some other time. Farewell." },
        ["text"] = "Вибач, але поговоримо іншим разом. Прощавай.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3907980841] = {
        ["english"] = { [1] = "Speak with Alchemist Finklestein, $c. He can set you on the path.$b$bDemonstrate your loyalty and their methods shall be made known to you." },
        ["text"] = "Поговори з алхіміком Фінкельштейном, $c. Він покаже тобі шлях.$b$bДоведи свою відданість — і їхні методи тобі відкриються.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2400097256] = {
        ["english"] = { [1] = "So $g lad : lass;, you think you have what it takes to defend the Alliance against the Horde in Alterac Valley?  Very well then, you will want to speak with our very own Glordrum Steelbeard here in Ironforge.  You'll find him strategizing over the war table in the Hall of Arms." },
        ["text"] = "То що, $g хлопче : дівчино;, гадаєш, у тебе є все потрібне, щоб захищати Альянс від Орди в Альтерацькій долині?  Гаразд, тоді поговори з нашим Ґлордумом Сталебородом тут, у Залізогарті.  Знайдеш його за воєнним столом у Залі зброї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3134173801] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to shamans." },
        ["text"] = "Вибач, але мої послуги корисні лише шаманам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [771371541] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to priests." },
        ["text"] = "Вибач, але мої послуги корисні лише жерцям.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1235639416] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to paladins." },
        ["text"] = "Вибач, але мої послуги корисні лише паладинам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1582266854] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to mages." },
        ["text"] = "Вибач, але мої послуги корисні лише магам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2005676542] = {
        ["english"] = { [1] = "So, off to see Myolor, eh? He's right o'er there... behind ye! Er, maybe in front of ye! Near the Great Anvil!" },
        ["text"] = "То ти до Майолора, еге? Він он там... позаду тебе! Е-е, може, попереду! Біля Великого Ковадла!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1558493576] = {
        ["english"] = { [1] = "Now why would ye be needing the services of one of those types?  We get enough trouble out of that rogue, Hulfdan Blackbeard, over in The Forlorn Cavern, do I need to be turning my eye to you as well?" },
        ["text"] = "І навіщо тобі послуги таких типів?  Нам і того розбійника Гульфдана Чорноборода в Закинутій печері вистачає. Чи мені ще й за тобою наглядати?",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1956972695] = {
        ["english"] = { [1] = "Restraints? There are things in this world far more restraining than bars and shackles, young $g master:mistress;. The undead surrounded us, constantly tormenting us with horrifying acts of depravity.$B$BFinally, he came. He introduced himself as Doctor Theolen Krastinov. We came to know him as 'The Butcher.'\010" },
        ["text"] = "Пута? У цьому світі є речі, що сковують значно сильніше за ґрати й кайдани, $g юний пане : юна пані;. Невмерлі оточили нас і без упину мучили жахливими проявами збоченої жорстокості.$B$BА потім прийшов він. Назвався доктором Теоленом Крастіновим. Ми ж знали його як «М’ясника».\010",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [2527410637] = {
        ["english"] = { [1] = "Mortals, you have saved me from a fate worse than death. Left to their devices, the sorcerers of the Lich King would have broken my will eventually, and condemned me to a tortured eternity of unlife. Ahead of you lies one who was not so fortunate: the once-proud consort of Malygos, Sindragosa.$B$BMortally wounded after Neltharion's betrayal and left to die alone in the snows of Icecrown, she exists now as a being of pure hatred. And yet, beneath those layers of malevolence still remains the noble spirit of a dragon queen. I believe there is yet hope that Sindragosa's soul may find peaceful respite." },
        ["text"] = "Смертні, ви врятували мене від долі, гіршої за смерть. Якби чародії Короля-ліча продовжили свою справу, вони зрештою зламали б мою волю й прирекли мене на вічні муки нежиття. Попереду на вас чекає та, кому пощастило менше: колись горда супруга Маліґоса, Сіндраґоса.$B$BСмертельно поранена після зради Нелтаріона й покинута помирати на самоті в снігах Крижаної Корони, тепер вона існує як утілення чистої ненависті. Та під шарами злоби все ще живе благородний дух королеви драконів. Я вірю, що душа Сіндраґоси ще може знайти спокій.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1457155888] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to druids." },
        ["text"] = "Вибач, але мої послуги корисні лише друїдам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [790859955] = {
        ["english"] = { [1] = "Razorfen Kraul" },
        ["text"] = "Лабіринти Бритвоскалих",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2037486733] = {
        ["english"] = { [1] = "Listen here, now. When you're looking for answers nothing beats a good explosion - the bigger, the better!$b$bBut that's probably enough with the questions for now, $r.$b$bMy warheads are classified material, and the element 115 that I created to power them is even more classified!$b$bIn fact, it's best that you just return to your everyday life and pretend we never met." },
        ["text"] = "Слухай сюди. Коли шукаєш відповіді, ніщо не зрівняється з добрим вибухом — що більший, то краще!$b$bАле, гадаю, досить питань на сьогодні, $r.$b$bМої боєголовки — засекречений матеріал, а створений мною для їх живлення елемент 115 — ще більш засекречений!$b$bТож найкраще тобі повернутися до звичного життя й удавати, що ми ніколи не зустрічалися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4026984398] = {
        ["english"] = { [1] = "Please port me to Darnassus." },
        ["text"] = "Будь ласка, телепортуй мене до Дарнаса.",
        ["npcs"] = { [1] = 6729 },
        ["roles"] = { ["reply"] = true },
    },
    [360053175] = {
        ["english"] = { [1] = "Nope, don't think there are any Enchanters here in Elwynn Forest.  There's a guy named Lucan who runs a shop up in Stormwind though.  You could check with him and see if he will train you." },
        ["text"] = "Ні, не думаю, що в Ельвинському лісі є заклинателі.  Але в Штормовії є чоловік на ім’я Лукан, у нього там крамниця.  Зайди до нього й спитай, чи навчить тебе.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2564751937] = {
        ["english"] = { [1] = "Sergeant, loan me your spyglass." },
        ["text"] = "Сержанте, позичте мені підзорну трубу.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [238791810] = {
        ["english"] = { [1] = "Sorry, but I am not disposed to sell horses to any individual who is not considered to be at least exalted to the Kingdom of Stormwind.  These steeds are the finest you'll find anywhere, and we certainly wouldn't want them in the hands of our enemies.$B$BNot saying you're an enemy, of course... just earn the trust of Stormwind and then we can do business." },
        ["text"] = "Вибач, але я не продаю коней нікому, хто не має щонайменше піднесеної репутації з королівством Штормовій.  Ці скакуни — найкращі з усіх, і ми точно не хочемо, щоб вони потрапили до рук ворогів.$B$BНе кажу, що ти ворог, звісно... просто заслужи довіру Штормовію, і тоді поговоримо про справи.",
        ["npcs"] = { [1] = 384, [2] = 1460, [3] = 2357, [4] = 4885 },
        ["roles"] = { ["greeting"] = true },
    },
    [3477940368] = {
        ["english"] = { [1] = "Sorry to have bothered you, friend. Carry on!" },
        ["text"] = "Вибач, що потурбував, друже. Продовжуй свої справи!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [875224270] = {
        ["english"] = { [1] = "Sorry friend, we don't have one of those here in Brill.  You'll have to head to the Undercity for that.  The Undercity is underneath the Ruins of Lordaeron to the south of Brill.  From the back of the ruins take the elevator down and then speak to one of the Undercity Guardians to find your way further." },
        ["text"] = "Вибач, друже, такого в Бріллі немає.  Доведеться вирушити до Підміста.  Воно розташоване під руїнами Лордерону на південь від Брілля.  У задній частині руїн спустися ліфтом, а тоді спитай одного з вартових Підміста, куди йти далі.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1131970573] = {
        ["english"] = { [1] = "My chest is one of ingenious design, and requires two keys to unlock, one gold and one silver.  The first key, the silver key, I gave to my first mate, and I kept the gold.$B$BBut we were doomed to lose them.  My key was lost during the next naga attack, and my first mate's was lost a day later when drysnap makrura assailed us and pulled him into the deep.$B$BI am sure the naga and makrura have the keys.  I am glad the two are enemies and will not share them." },
        ["text"] = "Моя скриня має хитромудру конструкцію й потребує двох ключів: золотого та срібного.  Перший, срібний, я віддав старшому помічникові, а золотий залишив собі.$B$BТа нам судилося їх втратити.  Мій ключ зник під час наступного нападу наґів, а ключ помічника — днем пізніше, коли нас атакували макрури Сухого Клешня й затягли його в глибини.$B$BЯ певен, що ключі в наґів і макрур.  Добре, що вони вороги й не стануть ними ділитися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4055203860] = {
        ["english"] = { [1] = "Pay me and I'll talk...$B$BOh hey, it's you, $N! Nevermind about that..." },
        ["text"] = "Заплати — і я поговорю...$B$BО, це ти, $N! Забудь...",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true },
    },
    [883098760] = {
        ["english"] = { [1] = "Laurena is the High Priestess of Stormwind. You can find her in the Catheral of Light in Cathedral Square." },
        ["text"] = "Лорена — верховна жриця Штормовію. Знайдеш її в Соборі Світла на Соборній площі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1200174542] = {
        ["english"] = { [1] = "Please continue, Hero..." },
        ["text"] = "Продовжуй, герою...",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [2393799690] = {
        ["english"] = { [1] = "Mark my words, I will catch you, imp. And when I do!" },
        ["text"] = "Запам’ятай мої слова, я тебе спіймаю, бісе. І коли спіймаю!..",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["reply"] = true },
    },
    [4024757036] = {
        ["english"] = { [1] = "Once you start loosening the reins on the ram, you'll see his speed change. He starts off walking. Ease up on the reins a bit more and he'll start to trot. Give him more slack on the reins while he's trotting and he'll go into a canter. Give him even more slack while he's in a canter and you will send him into a gallop." },
        ["text"] = "Коли почнеш послаблювати поводи барана, побачиш, як змінюється його швидкість. Спочатку він іде кроком. Трохи відпусти поводи — перейде на рись. Ще послаб — і з рисі перейде на легкий галоп. Відпусти ще більше під час легкого галопу — і він помчить повним галопом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2918662118] = {
        ["english"] = { [1] = "Shelby Stoneflint houses a good deal of pets for the local hunters.  She can be found over by the Thunderbrew Distillery if ye need her to look after a pet." },
        ["text"] = "Шелбі Кам’янокрес зберігає чимало вихованців місцевих мисливців.  Знайдеш її біля Ґуральні Громоварів, якщо треба залишити вихованця під наглядом.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1391386299] = {
        ["english"] = { [1] = "Please tell me more about Maraudon." },
        ["text"] = "Розкажи мені більше про Мародон.",
        ["npcs"] = { [1] = 13716 },
        ["roles"] = { ["reply"] = true },
    },
    [1261202635] = {
        ["english"] = { [1] = "Lord-Commander, would you repeat what you said before?" },
        ["text"] = "Лорде-командувачу, повторіть, будь ласка, те, що казали раніше.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [934103501] = {
        ["english"] = { [1] = "Och! Ye seek training in the way of the warrior, do ye?  Kelstrum Stonebreaker will put ye through yer paces!  Just march yerself over to the Hall of Arms east of the gates of Ironforge. " },
        ["text"] = "Ох! Шукаєш навчання воїнського ремесла, га?  Келструм Каменелом добряче тебе проганятиме!  Маршируй до Зали зброї на схід від брам Залізогарта. ",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1643929960] = {
        ["english"] = { [1] = "Soon I will plant roots and sleep.   Before I rest there are things that must yet be done." },
        ["text"] = "Скоро я пущу коріння й засну.   Та перед відпочинком ще треба дещо зробити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [699065161] = {
        ["english"] = { [1] = "Something stinks, and for once it's not my socks." },
        ["text"] = "Щось смердить, і цього разу це не мої шкарпетки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3183698263] = {
        ["english"] = { [1] = "Somewhere to fly to?  You'll need to go to the Undercity for that!  Go south on the road out of town, then southwest to the Ruins of Lordaeron.  You can catch the elevator down to the Undercity from the back of the ruins and once there ask an Undercity Guardian for more specific directions." },
        ["text"] = "Хочеш кудись полетіти?  Для цього треба в Підмісто!  Іди дорогою на південь із міста, потім на південний захід до руїн Лордерону.  У задній частині руїн є ліфт до Підміста, а вже там спитай вартового Підміста про точніший шлях.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1869334197] = {
        ["english"] = { [1] = "Lookin' mighty cris, me bucko!  Ye pillage a fat sutler?  Best ye spread da wealth... don't be a craven choke puppy, mon!" },
        ["text"] = "Виглядаєш багатенько, друже!  Пограбував жирного маркітанта?  Краще поділися добром... не будь боягузливим скнарою, еге!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1602067264] = {
        ["english"] = { [1] = "Our food and drink are in short supply.  I'm afraid I do not have anything to offer you." },
        ["text"] = "Наші запаси їжі й напоїв майже вичерпалися.  Боюся, мені нічого тобі запропонувати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2022420011] = {
        ["english"] = { [1] = "Missing US text" },
        ["text"] = "Відсутній текст US",
        ["npcs"] = { [1] = 3467, [2] = 3936, [3] = 6766, [4] = 6771 },
        ["roles"] = { ["greeting"] = true },
    },
    [1516872849] = {
        ["english"] = { [1] = "Life is like a carefully woven tapestry." },
        ["text"] = "Життя схоже на майстерно витканий гобелен.",
        ["npcs"] = { [1] = 1300 },
        ["roles"] = { ["greeting"] = true },
    },
    [2819107861] = {
        ["english"] = { [1] = "Lady Sylvanas has ordered the investigation of some of the natural phenomena of Azeroth. She feels there is something great to be learned from its secretive past.$B$BI know not how she learned such things, but I trust her completely, so I will do my best.$B$BI am currently investigating slimes, oozes and such. The creatures all seem to be similar in make up, but greatly affected by their environment.$B$BI could use your help in gathering samples of the creatures.." },
        ["text"] = "Леді Сильвана наказала дослідити деякі природні явища Азероту. Вона вважає, що з його таємничого минулого можна дізнатися щось надзвичайно важливе.$B$BНе знаю, звідки вона це дізналася, але я цілковито їй довіряю, тож зроблю все, що зможу.$B$BНаразі я досліджую слизів, слизовиків та подібних істот. Усі вони начебто мають схожу будову, але дуже сильно змінюються під впливом довкілля.$B$BМені знадобиться твоя допомога зі збиранням зразків цих істот..",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3802585280] = {
        ["english"] = { [1] = "Nope, can't help you, I'm afraid. Your skills have mine beat! If you want to learn more, talk to the night elf Telonis in the Craftsmen's Terrace of Darnassus. He's amazing!" },
        ["text"] = "Ні, боюся, я вже нічим не допоможу. Твої навички перевершили мої! Якщо хочеш вчитися далі, поговори з нічним ельфом Телонісом на Терасі Ремісників у Дарнасі. Він неймовірний!",
        ["npcs"] = { [1] = 5127 },
        ["roles"] = { ["greeting"] = true },
    },
    [847394371] = {
        ["english"] = { [1] = "Sometimes the straightforward approach to a problem is the best." },
        ["text"] = "Іноді найкращий підхід до проблеми — найпряміший.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [179562241] = {
        ["english"] = { [1] = "Right then... You have to build an arcanite buoy and place it in the ocean. My minnow will be attracted to the magical emanations. When he gets near the buoy - BLAMO! It will explode in a glorious pulse of arcane energy, revealing the minnow's true form. Also, you may or may not incur the wrath of Neptulon. A 50/50 chance I would say." },
        ["text"] = "Отже... Треба збудувати арканітовий буй і поставити його в океані. Мого малька приваблять магічні випромінювання. Коли він наблизиться до буя — БАБАХ! Той вибухне величним імпульсом арканічної енергії й розкриє справжню форму малька. А ще ти можеш накликати на себе гнів Нептулона. Я б сказав, шанси п’ятдесят на п’ятдесят.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [2195448191] = {
        ["english"] = { [1] = "Join the fight against evil!  Accept a commission within the Argent Dawn today!" },
        ["text"] = "Долучайся до боротьби зі злом!  Прийми доручення Сріблястого Світанку вже сьогодні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3896392338] = {
        ["english"] = { [1] = "Speak with Un'Thuwa to the south in Sen'jin Village." },
        ["text"] = "Поговори з Ун’Тувою на півдні в селищі Сен’джин.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [682034269] = {
        ["english"] = { [1] = "It... It's foggy, $N. I can't see anything! Wait... Wait a minute. I see... I see Doctor Weavil's hideout. It... YES! I believe he is holding a chapter of the book!$B$BLet me see if I can zoom this thing out to get a better vantage point.$B$B<Narain appears to be going cross-eyed.>$B$BAlcaz Island! That devious bastard is on Alcaz Island!" },
        ["text"] = "Тут... усе в тумані, $N. Я нічого не бачу! Зачекай... Хвилинку. Бачу... бачу схованку доктора Вевіла. Це... ТАК! Здається, у нього є розділ із книги!$B$BДай-но спробую віддалити зображення, щоб краще все роздивитися.$B$B<Нарайн напружено косить очі.>$B$BОстрів Альказ! Цей підступний покидьок на острові Альказ!",
        ["npcs"] = { [1] = 11811 },
        ["roles"] = { ["greeting"] = true },
    },
    [1448195798] = {
        ["english"] = { [1] = "One of the humans has the key to this infernal contraption. Eston I think they said his name was." },
        ["text"] = "Ключ від цього пекельного пристрою в одного з людей. Здається, його звати Естон.",
        ["npcs"] = { [1] = 2239 },
        ["roles"] = { ["greeting"] = true },
    },
    [557321364] = {
        ["english"] = { [1] = "Our Aether-tech and his escort are heading to Bash'ir Landing.  Meet them there and help with their mission!" },
        ["text"] = "Наш ефіротехнік із супроводом прямує до табору Баш’іра.  Зустрінь їх там і допоможи з місією!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1214081227] = {
        ["english"] = { [1] = "Lysheana can offer you the proper documents, she resides in the Craftsmen's Terrace in northeasten Darnassus.  May your fellowship bring glory to the Night Elves!" },
        ["text"] = "Лішеана видасть тобі потрібні документи. Вона мешкає на Терасі Ремісників у північно-східній частині Дарнаса.  Нехай твоє братство прославить нічних ельфів!",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [4006374027] = {
        ["english"] = { [1] = "Sometimes I surprise even myself!" },
        ["text"] = "Іноді я навіть сам себе дивую!",
        ["npcs"] = { [1] = 11017 },
        ["roles"] = { ["greeting"] = true },
    },
    [2769064758] = {
        ["english"] = { [1] = "No rest for wicked, but us guess you ok.  You find Innkeeper Norman on upper ring of Trade Quarter." },
        ["text"] = "Злим нема спочинку, але ти, здається, нормальний.  Господар заїзду Норман на верхньому кільці Торгового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2319344752] = {
        ["english"] = { [1] = "May your skills in smelting dark iron serve you well, $N.  But do not let your knowledge corrupt you... as it corrupted us." },
        ["text"] = "Нехай уміння виплавляти темне залізо добре тобі послужить, $N.  Але не дозволь знанню осквернити тебе... як воно осквернило нас.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3578608649] = {
        ["english"] = { [1] = "Nice form $N, I bet a full mug at Bruuk's Corner that the function is just as solid. Ye know, ye might want to talk to Myolor Sunderfury. He'll set ya straight." },
        ["text"] = "Гарна форма, $N. Ставлю повний кухоль у «Кутку Бруука», що й функція така ж надійна. Знаєш, поговори з Майолором Розлютоломом. Він поставить тебе на правильний шлях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1967573928] = {
        ["english"] = { [1] = "It's not my fault... IT'S NOT MY FAULT!!!$B$BIf they'd just done what I told them to do everything would have been fine. But no! They wouldn't listen.$B$BNow they're all dead.$B$BI just want to go home. Home to Silvermoon. I'm so tired." },
        ["text"] = "Це не моя провина... ЦЕ НЕ МОЯ ПРОВИНА!!!$B$BЯкби вони просто зробили те, що я їм казав, усе було б гаразд. Але ж ні! Вони не слухали.$B$BТепер вони всі мертві.$B$BЯ просто хочу додому. Додому, в Срібномісяць. Я так втомився.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2219782303] = {
        ["english"] = { [1] = "Our blessed great sea turtle, Green Island, travels from here to Moa'ki Harbor in Dragonblight." },
        ["text"] = "Наша благословенна велика морська черепаха, Зелений Острів, плаває звідси до гавані Моа’кі на Драконовому кладовищі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2726033341] = {
        ["english"] = { [1] = "Perhaps you should speak into these sound enhancing devices attached to my FISTS OF FURY." },
        ["text"] = "Може, варто говорити в ці пристрої для підсилення звуку, прикріплені до моїх КУЛАКІВ ЛЮТІ.",
        ["npcs"] = { [1] = 11316 },
        ["roles"] = { ["greeting"] = true },
    },
    [531859926] = {
        ["english"] = { [1] = "Notices of reward for the naga leaders of the Darkcrest and Bloodscale tribes are listed here." },
        ["text"] = "Тут розміщені оголошення про нагороду за ватажків наґів племен Темного Гребеня й Кроволуских.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1140304522] = {
        ["english"] = { [1] = "Like anything that you see, $c?" },
        ["text"] = "Щось сподобалося, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2268753317] = {
        ["english"] = { [1] = "Oh brother, not this again... Have a seat $g sonny:missy;.$B$BI'm sure Rutgar has told you some of this story already so I'll spare you the boring details and get right down to the nitty gritty." },
        ["text"] = "Ох, тільки не це знову... Сідай, $g синку:панно;.$B$BУпевнений, Рутґар уже розповів тобі частину цієї історії, тож я пропущу нудні подробиці й одразу перейду до суті.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [3091826745] = {
        ["english"] = { [1] = "So how about you deliver a message for me?" },
        ["text"] = "То як щодо того, щоб доставити для мене повідомлення?",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["greeting"] = true },
    },
    [3535217089] = {
        ["english"] = { [1] = "Return me to life." },
        ["text"] = "Поверни мене до життя.",
        ["npcs"] = { [1] = 6491, [2] = 13056, [3] = 18153 },
        ["roles"] = { ["reply"] = true },
    },
    [2865134699] = {
        ["english"] = { [1] = "Let's get out of here!" },
        ["text"] = "Забираймося звідси!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2993626569] = {
        ["english"] = { [1] = "Not so fast, $g guy : lady;... I'll not be handing out the reigns of a mighty ram steed to someone that's not a proven ally of the dwarves of Ironforge.  Once you've been recognized as exalted to Ironforge, I'll gladly show you what varieties of rams I have for sale." },
        ["text"] = "Не так швидко, $g хлопче : пані;... Я не віддам поводи могутнього барана тому, хто ще не довів свою відданість дворфам Залізогарта.  Коли твоя репутація зі Залізогартом стане піднесеною, я охоче покажу тобі баранів, яких маю на продаж.",
        ["npcs"] = { [1] = 1261 },
        ["roles"] = { ["greeting"] = true },
    },
    [2343416977] = {
        ["english"] = { [1] = "May the Light purge your infection, brave $N." },
        ["text"] = "Нехай Світло очистить тебе від зарази, хоробрий $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1242295583] = {
        ["english"] = { [1] = "Orcs. It seems I've been fighting them all my life.$B$BTwenty years ago we shattered the Horde and tore down the walls of their Hellfire Citadel. We drove the vile greenskins to the very brink! After that, other than a few skirmishes the broken orcs never again posed a threat to us.$B$BUntil now. $B" },
        ["text"] = "Орки. Здається, я воюю з ними все життя.$B$BДвадцять років тому ми розгромили Орду й зруйнували мури їхньої Цитаделі Пекельного Вогню. Ми загнали мерзенних зеленошкірих на край загибелі! Після цього, крім кількох сутичок, розбиті орки більше не становили для нас загрози.$B$BДо сьогодні. $B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4123814945] = {
        ["english"] = { [1] = "May Cenarius guide you, $c.$B$BI am here in this corrupt land with my sisters on a mission of great importance to the Cenarian Circle. But only those who are powerful enough I ask speak to me about such matters--to send a lesser being would be folly." },
        ["text"] = "Нехай Кенарій веде тебе, $c.$B$BЯ прийшла в цю осквернену землю із сестрами з надзвичайно важливим дорученням Кенарієвого Кола. Але про такі справи я говоритиму лише з достатньо могутніми — посилати слабшу істоту було б безглуздям.",
        ["npcs"] = { [1] = 13698 },
        ["roles"] = { ["greeting"] = true },
    },
    [3245877913] = {
        ["english"] = { [1] = "Lookin' to take a gryphon ride, eh? Dungar keeps his birds up on the rampart in the Trade District. Just remember to hold on tight! " },
        ["text"] = "Хочеш політати на грифоні, га? Дунґар тримає своїх птахів на мурі в Торговому районі. Тільки тримайся міцно! ",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [4078004833] = {
        ["english"] = { [1] = "Something I can do for you, Boss?" },
        ["text"] = "Щось треба, босе?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4073321235] = {
        ["english"] = { [1] = "So what has led you to Naxxramas?" },
        ["text"] = "Що привело тебе до Наксрамаса?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3585180418] = {
        ["english"] = { [1] = "Magar's Cloth Goods is in The Drag.  Find him south of the huge tree next to the Kodohide Leatherworks." },
        ["text"] = "«Тканини Маґара» в Хитрому провулку.  Шукай на південь від величезного дерева, поруч зі шкіряниками «Шкура кодо».",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3748707907] = {
        ["english"] = { [1] = "Someone called for me...?" },
        ["text"] = "Хтось мене кликав...?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [151721907] = {
        ["english"] = { [1] = "Since you are a tailor of some skill, I can tell you that I know some special recipes.   I know recipes for both the Wispcloak and the Deathchill Cloak." },
        ["text"] = "Раз ти вже досвідчений кравець, можу сказати, що знаю кілька особливих рецептів.   Я знаю рецепти Плаща вогника й Плаща смертельного холоду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4162808164] = {
        ["english"] = { [1] = "Nice to see you again, $N." },
        ["text"] = "Радий знову тебе бачити, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1835248898] = {
        ["english"] = { [1] = "Not only am I havin' all the mithril bars I be needin', but all the Horde collections are done now mon. It's lookin' like we just waitin' on the Alliance and then we be goin' to war!" },
        ["text"] = "У мене не просто є всі потрібні мітрилові зливки — Орда вже завершила всі збори, друже. Схоже, тепер лишилося чекати на Альянс, а тоді — війна!",
        ["npcs"] = { [1] = 15469 },
        ["roles"] = { ["greeting"] = true },
    },
    [73759856] = {
        ["english"] = { [1] = "Some say that strength and bravery are most needed for an army's success.  And it's true!  But an army also needs supplies to keep itself in good shape, and it's my job to make sure they have what they need." },
        ["text"] = "Кажуть, для успіху армії найбільше потрібні сила й хоробрість.  І це правда!  Але армії також потрібні припаси, щоб залишатися боєздатною, і моя робота — стежити, щоб у них було все необхідне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2475251230] = {
        ["english"] = { [1] = "Our enemies surround us.  I would have a better life for the Mok'Nathal, but the forces we are at battle with have chosen otherwise for us.$B$BIf you would prove yourself worthy to the Mok'Nathal, aid us in their elimination." },
        ["text"] = "Наші вороги оточують нас.  Я хотів би кращого життя для Мок’Натал, але сили, з якими ми воюємо, вирішили інакше.$B$BЯкщо хочеш довести, що гідний Мок’Натал, допоможи нам їх знищити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2844019305] = {
        ["english"] = { [1] = "Reporting for duty, sir." },
        ["text"] = "Прибув на службу, пане.",
        ["npcs"] = { [1] = 15612 },
        ["roles"] = { ["reply"] = true },
    },
    [2979477471] = {
        ["english"] = { [1] = "Listen closely to what you are told and do not quickly trust, or distrust.  For even friends serve their own ends, $c.$B$BOur great Warchief knows this, and to prove that there are warlocks within the Horde who do not wish to destroy it from within or gain control over it, I have volunteered to aid our young leader in anyway I can." },
        ["text"] = "Уважно слухай, що тобі кажуть, і не поспішай ні довіряти, ні сумніватися.  Навіть друзі переслідують власні цілі, $c.$B$BНаш великий Вождь це розуміє, і щоб довести, що серед чорнокнижників Орди є ті, хто не прагне знищити її зсередини чи захопити над нею владу, я добровільно зголосився допомагати нашому молодому провідникові всім, чим зможу.",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["greeting"] = true },
    },
    [3784491518] = {
        ["english"] = { [1] = "Some adventurers think enchanting doesn't work. I find that when I challenge them to battle they change their tune!" },
        ["text"] = "Деякі шукачі пригод думають, що зачарування не працює. Коли я викликаю їх на бій, вони швидко змінюють думку!",
        ["npcs"] = { [1] = 3345 },
        ["roles"] = { ["greeting"] = true },
    },
    [3497408051] = {
        ["english"] = { [1] = "Ranked arena matches start in $4262d. Would-be champions are already busy honing their skills and acquiring the best gear they can. Are you going to be ready?" },
        ["text"] = "Рейтингові матчі на арені почнуться через $4262d. Майбутні чемпіони вже вдосконалюють навички й добувають найкраще спорядження. Ти будеш готовий?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2175411039] = {
        ["english"] = { [1] = "Soldier, you have new orders. You're to pull back and report to the sergeant!" },
        ["text"] = "Солдате, у тебе нові накази. Відступай і доповідай сержанту!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2363692855] = {
        ["english"] = { [1] = "Needlework requires a steady hand. And patience... above all, patience." },
        ["text"] = "Шиття потребує твердої руки. І терпіння... понад усе — терпіння.",
        ["npcs"] = { [1] = 4193 },
        ["roles"] = { ["greeting"] = true },
    },
    [496381844] = {
        ["english"] = { [1] = "So... you want to be a tailor? Very well, we'll see if you have what it takes." },
        ["text"] = "То... хочеш стати кравцем? Гаразд, подивимося, чи маєш хист.",
        ["npcs"] = { [1] = 3523 },
        ["roles"] = { ["greeting"] = true },
    },
    [409216575] = {
        ["english"] = { [1] = "It's the big building in Razor Hill that's not the barracks.  Just talk to Innkeeper Grosk inside.  Got that?" },
        ["text"] = "Це велика будівля в Колючому Пагорбі, але не казарма.  Просто поговори всередині з господарем заїзду Ґроском.  Зрозуміло?",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [21172216] = {
        ["english"] = { [1] = "Mmm... food." },
        ["text"] = "М-м-м... їжа.",
        ["npcs"] = { [1] = 14845 },
        ["roles"] = { ["reply"] = true },
    },
    [1538781414] = {
        ["english"] = { [1] = "So... you took out the King eh?  I knew that these bozos would make you the new king, I just knew it!  That's all these bozos understand - power.$B$BIt would seem that the more henchmen you keep alive, the higher your tribute will be.  Not to shabby - makes for an interesting challenge I'd say.  If you leave, I wouldn't expect to remain king.  One of these yokels will no doubt step up and take your place.$B$BOne more thing... you didn't happen to find my key, did you?" },
        ["text"] = "Отже... ти прибрав Короля, еге?  Я знав, що ці телепні зроблять тебе новим королем, просто знав!  Вони розуміють лише одне — силу.$B$BСхоже, що більше поплічників залишиш живими, то більшою буде твоя данина.  Непогано — цікавий виклик, як на мене.  Якщо підеш звідси, не розраховуй залишитися королем.  Якийсь із цих бовдурів напевно займе твоє місце.$B$BІ ще дещо... ти часом не знайшов мій ключ?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2577866094] = {
        ["english"] = { [1] = "Komin Winterhoof at Holistic Herbalism is the one you want to talk to then.  He can be found on the middle rise." },
        ["text"] = "Тоді тобі треба поговорити з Коміном Зимове Копито з «Цілісного травництва».  Він на середньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [926829400] = {
        ["english"] = { [1] = "On behalf of the illustrious and still neutral Steamwheedle Cartel, I hope you enjoy your stay.$B$BRemember, everyone is welcome in Gadgetzan! Everyone except pirates." },
        ["text"] = "Від імені славетного й досі нейтрального картелю Хиткої Шестерні бажаю приємного перебування.$B$BПам’ятай: у Пристробляску раді всім! Усім, крім піратів.",
        ["npcs"] = { [1] = 9460 },
        ["roles"] = { ["greeting"] = true },
    },
    [2507828447] = {
        ["english"] = { [1] = "It... is... not... the best... time, $N. I must concen... trate." },
        ["text"] = "Зараз... не... найкращий... час, $N. Я мушу зосере... дитися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [748407114] = {
        ["english"] = { [1] = "Legion everywhere... they must be dealt with!" },
        ["text"] = "Легіон усюди... з ними треба покінчити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2384775871] = {
        ["english"] = { [1] = "My early classes are always filled with bright-eyed young lads. Few make it past the first test, though.$B$BI've given up on shouting, 'when I yell vanish, you need to vanish.' They never listen. Now, the test simply kills the inept." },
        ["text"] = "Мої початкові заняття завжди повні яснооких юнаків. Та мало хто проходить перше випробування.$B$BЯ вже перестав кричати: «Коли я кажу зникнути — треба зникати». Вони все одно не слухають. Тепер випробування просто вбиває нездар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3345966241] = {
        ["english"] = { [1] = "So, you have found me. I suppose that you have come to learn of suppression and control.$B$BI will teach you much more than that... you will also learn of sacrifice.$B$B<Daio grins.>" },
        ["text"] = "Отже, ти мене знайшов. Гадаю, ти прийшов навчитися придушення й контролю.$B$BЯ навчу тебе значно більшого... ти також пізнаєш жертву.$B$B<Дайо шкіриться.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3104727716] = {
        ["english"] = { [1] = "So, now that I'm the king... what have you got for me?!" },
        ["text"] = "То тепер, коли я король... що в тебе для мене є?!",
        ["npcs"] = { [1] = 14325, [2] = 14326 },
        ["roles"] = { ["reply"] = true },
    },
    [3893376418] = {
        ["english"] = { [1] = "So, I found this shackle key..." },
        ["text"] = "Отже, я знайшов цей ключ від кайданів...",
        ["npcs"] = { [1] = 14338 },
        ["roles"] = { ["reply"] = true },
    },
    [3937434631] = {
        ["english"] = { [1] = "So you're looking to relearn what you forgot, eh? Or maybe learn what you were never taught? I know just the thing, $N. Over by Steamwheedle port, to the east, you'll find a magical book in Narain's hut called \"Soothsaying for Dummies.\" Give it a read.$B$B<Nixx winks.>$B$BYou'll find all that you need to know and then some..." },
        ["text"] = "То хочеш заново вивчити те, що забув, еге? Або, може, навчитися тому, чого тебе ніколи не вчили? Я знаю саме те, що треба, $N. На сході, біля порту Хиткої Шестерні, у хатині Нарайна знайдеш магічну книгу «Ворожіння для чайників». Прочитай її.$B$B<Нікс підморгує.>$B$BТам знайдеш усе, що треба знати, і навіть більше...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1632451446] = {
        ["english"] = { [1] = "Nothing frees the spirit like soaring through the sky.  There is such a place in our great tribal center Thunder Bluff.  The road north out of Bloodhoof Village will guide you there.  Once you ride the elevator to the top speak with one of the Bluffwatchers who can give you further directions." },
        ["text"] = "Ніщо так не звільняє дух, як політ небом.  Таке місце є в нашому великому племінному центрі — Громовому Бескиді.  Дорога на північ із селища Криваве Копито приведе тебе туди.  Піднімешся ліфтом нагору — поговори з одним із вартових Бескиду, вони підкажуть далі.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1040965546] = {
        ["english"] = { [1] = "Our need for assistance in Arathi Basin is greater than one might imagine, $N.  So too is the honor and reputation one might acquire there in this time of need, however.  I implore you to seek out the Arathi Basin battlemaster in this city." },
        ["text"] = "Наша потреба в допомозі в Низині Араті більша, ніж може здатися, $N.  Та й честь і репутація, яких там можна здобути в такий час, теж неабиякі.  Благаю, знайди в цьому місті розпорядника Низини Араті.",
        ["npcs"] = { [1] = 14990 },
        ["roles"] = { ["greeting"] = true },
    },
    [1226295896] = {
        ["english"] = { [1] = "Last I heard from Hauthaa, she indicated that we are $3228w percent of the way there.$B$BI cannot express how vital it is to our efforts that we get them created. Our men and women are going to need better armor and weapons, and the anvil and forge are the key to that.$B$BYou will find the smith behind the Sun's Reach Armory, $N." },
        ["text"] = "Востаннє, коли я чув про Гауту, вона сказала, що ми виконали $3228w відсотків роботи.$B$BЯ не можу передати словами, наскільки важливо для наших зусиль завершити їхнє створення. Нашим чоловікам і жінкам знадобляться кращі обладунки та зброя, а ковадло й горно — ключ до цього.$B$BКоваля знайдеш за Зброярнею Сонячного Краю, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [771995919] = {
        ["english"] = { [1] = "Just because something isn't broke doesn't mean you can't fix it.  You lookin' for something, sweety?" },
        ["text"] = "Якщо щось не зламане, це ще не означає, що його не можна полагодити.  Щось шукаєш, любчику?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2782792444] = {
        ["english"] = { [1] = "Nice going! I knew I was right about you, no matter what those other people said. Ha! I'm kidding! Okay, on with your lessons." },
        ["text"] = "Чудово! Я знав, що не помилився щодо тебе, хай там що казали інші. Ха! Жартую! Гаразд, продовжуймо уроки.",
        ["npcs"] = { [1] = 11017 },
        ["roles"] = { ["greeting"] = true },
    },
    [2719635494] = {
        ["english"] = { [1] = "Many animals lost their lives so that we could gain these materials. Do not take their sacrifice lightly, $N. Handle the leather with the respect it deserves." },
        ["text"] = "Заради цих матеріалів загинуло багато тварин. Не стався легковажно до їхньої жертви, $N. Поводься зі шкірою з належною пошаною.",
        ["npcs"] = { [1] = 11081 },
        ["roles"] = { ["greeting"] = true },
    },
    [626393079] = {
        ["english"] = { [1] = "So you would like to learn a few things? I would be happy to get you started!" },
        ["text"] = "То хочеш дечого навчитися? Я із задоволенням допоможу почати!",
        ["npcs"] = { [1] = 1103 },
        ["roles"] = { ["greeting"] = true },
    },
    [273268867] = {
        ["english"] = { [1] = "So you think you are good enough to learn from me? The great Snarl? You are no more than a lowly worm beneath my boot. However, taking on an underling might make me seem more appealing to Sumi and Tumi. Let's see what meager skills you possess." },
        ["text"] = "То ти думаєш, що достатньо вправний, аби вчитися в мене? У великого Снарла? Ти лише жалюгідний хробак під моїм чоботом. Та якщо я візьму собі підлеглого, то, може, стану привабливішим для Сумі й Тумі. Подивімося, які жалюгідні навички в тебе є.",
        ["npcs"] = { [1] = 1383 },
        ["roles"] = { ["greeting"] = true },
    },
    [530909606] = {
        ["english"] = { [1] = "Last I heard, Elder Runetotem was traveling to Razor Hill in Durotar." },
        ["text"] = "Востаннє я чув, що старійшина Рунічний Тотем прямував до Колючого Пагорба в Дуротарі.",
        ["npcs"] = { [1] = 15579, [2] = 15582, [3] = 15588, [4] = 15597 },
        ["roles"] = { ["greeting"] = true },
    },
    [3253076693] = {
        ["english"] = { [1] = "Ours is the path of glory, $r! The puny Alliance is still trying to scrape together their war supplies, while we have gathered all of ours and stand ready to send them to Silithus." },
        ["text"] = "Наш шлях — шлях слави, $r! Жалюгідний Альянс іще шкребе по засіках воєнні припаси, а ми вже зібрали все своє й готові відправити в Силітус.",
        ["npcs"] = { [1] = 15460 },
        ["roles"] = { ["greeting"] = true },
    },
    [2180154403] = {
        ["english"] = { [1] = "Ms. Pomeroy gathers herbs for an Alchemist who lives up in the hills between Northshire and Stormwind.  Check for her at his cottage and see if she'll show you the profession." },
        ["text"] = "Пані Померой збирає трави для алхіміка, що живе на пагорбах між Північнокраєм і Штормовієм.  Знайди її біля його хатини й попроси показати тобі ремесло.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3039926583] = {
        ["english"] = { [1] = "Skaldrenox!  I hold your scepter, and charge you to enter this world!" },
        ["text"] = "Скалдреноксе!  У мене твій скіпетр, і я наказую тобі ввійти в цей світ!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1127468991] = {
        ["english"] = { [1] = "RAWGRLRLRLRRLGLRL!!!" },
        ["text"] = "РРРРАВҐРЛРЛРЛРРЛҐЛРЛ!!!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2275224865] = {
        ["english"] = { [1] = "Prepare to meet your maker." },
        ["text"] = "Готуйся зустріти свого творця.",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["reply"] = true },
    },
    [1482952286] = {
        ["english"] = { [1] = "Now ya be knowin' everything, mon! Prepare yourself... we attack soon!" },
        ["text"] = "Тепер ти все знати, друже! Готуйся... скоро ми атакувати!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3653741919] = {
        ["english"] = { [1] = "Manaforge Ultris, of course!  Where have you been?$B$BThe manaforge was overloaded and created a huge explosion.  It left a tear in reality and now void creatures have been pouring in through it.  You can see them all over the place towards the northeast." },
        ["text"] = "Манакузня Ультріс, звісно!  Де ти був?$B$BМанакузню перевантажили, і стався величезний вибух.  Він розірвав саму реальність, і тепер крізь розлом сюди ринуть створіння Порожнечі.  Їх повно на північному сході.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2252767972] = {
        ["english"] = { [1] = "It's no lie, traitor.  Banehollow wants your heart, and I'm going to get it for him." },
        ["text"] = "Це не брехня, зраднику.  Бейнгоул хоче твоє серце, і я принесу його йому.",
        ["npcs"] = { [1] = 14523 },
        ["roles"] = { ["reply"] = true },
    },
    [2188278409] = {
        ["english"] = { [1] = "So ye want to be a Blacksmith eh? Grab an apron and a hammer $g lad : lass;, let's see what ye've got." },
        ["text"] = "То хочеш стати ковалем, еге? Бери фартух і молот, $g хлопче : дівчино;, подивимося, на що ти здатний.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2478757881] = {
        ["english"] = { [1] = "Let's see... fourteen plus seven, carry the two... oh, yes?" },
        ["text"] = "Так... чотирнадцять плюс сім, два тримаємо в умі... о, так?",
        ["npcs"] = { [1] = 5518 },
        ["roles"] = { ["greeting"] = true },
    },
    [2583530473] = {
        ["english"] = { [1] = "Kil'jaeden's defenders here on the Sunwell Plateau are much stronger than anything we faced outside on the Island. The Legion have even twisted our Arcane Guardian technology with fel energy to create something much more sinister. Just one of those Sunblade Protectors decimated my troops, and I ordered a swift retreat. I expected my squad to be pushed completely off the plateau, but the enemy surprised me by calling off the pursuit." },
        ["text"] = "Захисники Кіл’джедена тут, на плато Сонячного Колодязя, значно сильніші за все, з чим ми стикалися на острові. Легіон навіть спотворив нашу технологію арканічних вартових енергією Скверни, створивши щось набагато зловісніше. Лише один із тих Захисників Сонячного Клинка розгромив мої війська, і я наказав негайно відступати. Я очікував, що мій загін повністю витіснять із плато, та ворог здивував мене, припинивши переслідування.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3435477713] = {
        ["english"] = { [1] = "One of the cultists seems to have stumbled onto my blade and died... can I have a new disguise? I promise that I will be more careful this time." },
        ["text"] = "Схоже, один із культистів випадково наткнувся на мій клинок і помер... можна мені нове маскування? Обіцяю, цього разу буду обережніший.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [130610742] = {
        ["english"] = { [1] = "Sorry, but I only train rogues." },
        ["text"] = "Вибач, але я навчаю лише розбійників.",
        ["npcs"] = { [1] = 917 },
        ["roles"] = { ["greeting"] = true },
    },
    [1743783744] = {
        ["english"] = { [1] = "So where was I? Oh yea, so the orcs rushed Windsor and Windsor, well, he didn't move an inch. He stood tall as they charged him, ten at a time. All I could see was the glow from Ironfoe and a lot of blood. This went on for hours, maybe days. I don't remember. Anyhow, FINALLY, it stopped." },
        ["text"] = "На чому я зупинився? А, точно. Орки кинулися на Віндзора, а Віндзор... він не відступив ані на крок. Стояв на весь зріст, поки вони нападали на нього десятками. Я бачив лише сяйво Залізобоя й купу крові. Це тривало годинами, може, днями. Не пам’ятаю. Так чи інакше, ЗРЕШТОЮ все припинилося.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3920011711] = {
        ["english"] = { [1] = "Ragefire Chasm can be found beneath the Shadow Cleft in the center of Orgrimmar." },
        ["text"] = "Ущелину Люті Вогню можна знайти під Розколиною Тіні в центрі Орґріммара.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2419955847] = {
        ["english"] = { [1] = "My, my, I never thought I would have the chance to see Ulduar myself. Why, when Brann asked me to help fund this expedition, how could I refuse?!" },
        ["text"] = "Ох-ох, ніколи не думав, що сам побачу Ульдуар. Та коли Бранн попросив допомогти профінансувати цю експедицію, як я міг відмовити?!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [721447465] = {
        ["english"] = { [1] = "Let me confer with my colleagues." },
        ["text"] = "Дозволь мені порадитися з колегами.",
        ["npcs"] = { [1] = 8479 },
        ["roles"] = { ["reply"] = true },
    },
    [2129412596] = {
        ["english"] = { [1] = "Of course! Go with Elune's blessing." },
        ["text"] = "Звісно! Іди з благословенням Елуни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1445215819] = {
        ["english"] = { [1] = "So what did you do?" },
        ["text"] = "І що ти зробив?",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [3116651587] = {
        ["english"] = { [1] = "Malygos the Spellweaver, the Lord of Magic, Master of the Blue Dragonflight. He is the blue dragon aspect, one of the most ancient creatures on Azeroth.$b$bHe is said to be recovering from a madness which has lasted for millennia, but his recent actions lead me to believe that he is still far from sane.$b$bHis solution to our dilemma is to search out and destroy every magic-wielding mortal on Azeroth.$b$bAs the guardians of life, this has forced the red dragonflight to take action.$b$bDragon now fights against dragon, and the fate of our frail world lies in the balance." },
        ["text"] = "Маліґос Заклинач Заклять, Володар Магії, повелитель Синьої драконячої зграї. Він — синій дракон-Аспект, одна з найдавніших істот Азероту.$b$bКажуть, він одужує від безумства, що тривало тисячоліттями, але його недавні вчинки змушують мене думати, що до здорового глузду йому ще далеко.$b$bЙого розв’язання нашої дилеми — відшукати й знищити кожного смертного Азероту, що володіє магією.$b$bЯк хранителі життя, ми, червона зграя, були змушені втрутитися.$b$bТепер дракон б’ється з драконом, а доля нашого крихкого світу висить на волосині.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [940949510] = {
        ["english"] = { [1] = "Right then! So the Mistress had come back for a second go at the hives but Brann was having none of that nonsense! Before the melee began, she started talking to something or someone. Crazier still, she started chanting in a language none of us had ever heard." },
        ["text"] = "Отже! Пані повернулася, щоб удруге сунутися до вуликів, але Бранн і чути про це не хотів! Перед бійкою вона почала говорити з чимось або кимось. А ще дивніше — завела співуче заклинання мовою, якої ніхто з нас ніколи не чув.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [2382031134] = {
        ["english"] = { [1] = "Only the most valiant and honorable amongst the tribe can earn the honor of being laid to rest at Red Rocks." },
        ["text"] = "Лише найхоробріші й найчесніші з племені здобувають честь бути похованими біля Червоних Скель.",
        ["npcs"] = { [1] = 3233 },
        ["roles"] = { ["greeting"] = true },
    },
    [1897812562] = {
        ["english"] = { [1] = "Once, it is true, I was human. What might otherwise be a shortcoming works to our advantage, $N, for I know human weaknesses intimately." },
        ["text"] = "Так, колись я був людиною. Те, що інакше могло б бути вадою, грає нам на руку, $N, бо людські слабкості я знаю досконало.",
        ["npcs"] = { [1] = 11044 },
        ["roles"] = { ["greeting"] = true },
    },
    [4016905822] = {
        ["english"] = { [1] = "So what brings you to Light's Hope?" },
        ["text"] = "Що привело тебе до Надії Світла?",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["reply"] = true },
    },
    [3873516624] = {
        ["english"] = { [1] = "So the Searing Blade is expendable?" },
        ["text"] = "То Пекучий Клинок можна просто списати?",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["reply"] = true },
    },
    [2169429295] = {
        ["english"] = { [1] = "Oh, ok!  Here you are, $N.  It's the least I can do for all the help you've given me." },
        ["text"] = "О, гаразд!  Ось, тримай, $N.  Це найменше, що я можу зробити за всю твою допомогу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3239732935] = {
        ["english"] = { [1] = "Race does not dictate honor, $r. While you remain on my farmstead, I ask that you remember and respect this credo.$B$BI have known orcs who have been as honorable as the most noble of knights and humans who have been as vile as the most ruthless of Scourge.$B$BBut I shall not bore you with tales of my youth! There is much work to be done - if that is what you desire. " },
        ["text"] = "Раса не визначає честі, $r. Поки ти на моїй фермі, прошу пам’ятати й поважати це правило.$B$BЯ знав орків, шляхетніших за найчесніших лицарів, і людей, огидніших за найжорстокіших прислужників Батога.$B$BТа не буду втомлювати тебе оповідями про молодість! Роботи багато — якщо саме цього ти шукаєш. ",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["greeting"] = true },
    },
    [3212863722] = {
        ["english"] = { [1] = "Mooranta can help you learn skinning.  She can be found just outside the Thunder Bluff Armorers on the middle rise." },
        ["text"] = "Муранта може навчити тебе знімати шкури.  Знайдеш її просто біля зброярів Громового Бескиду на середньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3627783316] = {
        ["english"] = { [1] = "No one really knows who made the Darkmoon Cards or what their true purpose is, but I can tell you that they have been found all over Azeroth, usually in the hands of a villain attempting to unlock their mysteries.\010\010There are four types of Darkmoon Cards; Beasts, Elementals, Portals and Warlords, with eight cards, Ace to Eight in each suit. If you collect all eight of one suit then you can turn them into a deck that you can give to our Professor Thaddeus Paleo in exchange for a powerful trinket.\010" },
        ["text"] = "Ніхто достеменно не знає, хто створив карти Темного Місяця чи яке їхнє справжнє призначення, але можу сказати, що їх знаходили по всьому Азероту — зазвичай у руках лиходіїв, які намагалися розгадати їхні таємниці.\010\010Є чотири типи карт Темного Місяця: Звірі, Елементалі, Портали й Воєводи. У кожній масті по вісім карт — від туза до вісімки. Якщо збереш усі вісім однієї масті, зможеш скласти колоду й віддати її нашому професору Таддеусу Палео в обмін на могутню дрібничку.\010",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [397026897] = {
        ["english"] = { [1] = "So many years of battle and slavery, it feels good to have a home again. " },
        ["text"] = "Після стількох років битв і рабства добре знову мати дім. ",
        ["npcs"] = { [1] = 3314 },
        ["roles"] = { ["greeting"] = true },
    },
    [14426604] = {
        ["english"] = { [1] = "Meat, skin, bones... a good hunter lets nothing go to waste. Every scrap of leather can be salvaged, perhaps to reinforce an ally's armor. Thus, each of us is strong alone, but together we become invincible." },
        ["text"] = "М’ясо, шкіра, кістки... добрий мисливець нічого не марнує. Кожен клапоть шкіри можна використати, скажімо, щоб посилити обладунок союзника. Тож кожен із нас сильний сам по собі, але разом ми непереможні.",
        ["npcs"] = { [1] = 3069 },
        ["roles"] = { ["greeting"] = true },
    },
    [1792658401] = {
        ["english"] = { [1] = "Mage" },
        ["text"] = "Маг",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3296, [19] = 5595, [20] = 5624, [21] = 5725, [22] = 5953, [23] = 6272, [24] = 6740, [25] = 8931, [26] = 12996, [27] = 13076, [28] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [2446433568] = {
        ["english"] = { [1] = "So many uses for the plague, so little time!" },
        ["text"] = "Стільки застосувань для чуми й так мало часу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4184132664] = {
        ["english"] = { [1] = "Kirin'Var survived 20 long years and countless orc assaults, but it could not withstand the forces of Kael'thas. A man who once called himself a member of the Kirin Tor murdered all of us, save one.$B$BArchmage Vargoth survived the attack, so Kael'thas imprisoned him within the Violet Tower, warding it with a magic that forbids the passage of any of the Kirin Tor." },
        ["text"] = "Кірін’Вар вистояв 20 довгих років і пережив незліченні напади орків, але не зміг протистояти силам Кель’таса. Людина, яка колись називала себе членом Кірін-Тору, убила всіх нас, крім одного.$B$BАрхімаг Варґот пережив напад, тож Кель’тас ув’язнив його у Фіолетовій вежі й наклав чари, що не дозволяють жодному члену Кірін-Тору пройти всередину.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1846105039] = {
        ["english"] = { [1] = "My hatred is strong <snort>, but the time is right to tell you a tale, $r.$B$BLong ago a battle took place between gods. Agamaggan, our great boar god, fell to the earth after being defeated in the War of the Ancients, his blood raining down and his bones torn asunder. <snort>$B$BGreat thorns reached up out of the earth where his blood touched the ground, and his skull adorns one of the caverns to the south." },
        ["text"] = "Моя ненависть сильна <хрюк>, але час розповісти тобі історію, $r.$B$BДавним-давно відбулася битва богів. Аґамаґґан, наш великий бог-вепр, упав на землю після поразки у Війні Древніх, його кров лилася дощем, а кістки розлетілися на шматки. <хрюк>$B$BТам, де його кров торкалася землі, з ґрунту виростали велетенські колючки, а його череп прикрашає одну з печер на півдні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3706127732] = {
        ["english"] = { [1] = "Sorry $g lad : lass;, ye aren't quite up to the challenge of learning from me. Go see my son Groum, it would make his day to get a new apprentice." },
        ["text"] = "Вибач, $g хлопче : дівчино;, ти ще не готовий до навчання в мене. Піди до мого сина Ґроума — він зрадіє новому учневі.",
        ["npcs"] = { [1] = 10276 },
        ["roles"] = { ["greeting"] = true },
    },
    [526726591] = {
        ["english"] = { [1] = "So let us pretend I get this hide, what else would you need and what could you actually make?" },
        ["text"] = "Припустімо, я дістану цю шкуру. Що ще тобі знадобиться й що ти взагалі зможеш виготовити?",
        ["npcs"] = { [1] = 10637 },
        ["roles"] = { ["reply"] = true },
    },
    [249219433] = {
        ["english"] = { [1] = "So how did he die?" },
        ["text"] = "І як він помер?",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [4075579070] = {
        ["english"] = { [1] = "Perhaps I can be of some assistance. I will make a deal with you, Satyr. I shall recover this unforged breastplate and slay the beast, Goraluk Anvilcrack. In exchange for this task, you will teach me how to create the breastplate." },
        ["text"] = "Можливо, я зможу допомогти. Укладемо угоду, сатире. Я поверну цей невикуваний нагрудник і вб’ю звіра Ґоралука Тріскоковада. Натомість ти навчиш мене створювати такий нагрудник.",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["reply"] = true },
    },
    [3918520950] = {
        ["english"] = { [1] = "Shouldn't you be saving the world?" },
        ["text"] = "Хіба ти не маєш рятувати світ?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [3190331461] = {
        ["english"] = { [1] = "So let me get this straight. You were swimming, nay, doing backstrokes in molten lava with this... this lava suit of yours? Yes? And out of nowhere, this here beast swallowed you whole? " },
        ["text"] = "Дай-но я все правильно зрозумію. Ти плавав — ні, плив на спині — у розплавленій лаві в цьому... своєму лавовому костюмі? Так? І раптом нізвідки взявся цей звір і проковтнув тебе цілком? ",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["reply"] = true },
    },
    [2690653924] = {
        ["english"] = { [1] = "Northrend awaits, $r. The majestic Cloudkisser will take you straight across to the sea to Vengeance Landing in Howling Fjord." },
        ["text"] = "Нортренд чекає, $r. Велична Хмароцілунка перенесе тебе просто через море до Гавані Помсти в Ревучому фйорді.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2828182823] = {
        ["english"] = { [1] = "Need supplies for the field?" },
        ["text"] = "Потрібні припаси для польових робіт?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1283580877] = {
        ["english"] = { [1] = "Something wrong?" },
        ["text"] = "Щось не так?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1275106346] = {
        ["english"] = { [1] = "Oh, what a sacred place is here overthrown!" },
        ["text"] = "О, яке священне місце тут повалено!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3220892662] = {
        ["english"] = { [1] = "Open your mind, wanderer, and we shall begin." },
        ["text"] = "Відкрий свій розум, мандрівнику, і ми почнемо.",
        ["npcs"] = { [1] = 3606 },
        ["roles"] = { ["greeting"] = true },
    },
    [558164810] = {
        ["english"] = { [1] = "So cold... and hungry.$B$BMy poor friend, I hope you've found peace. I can't stand to think about what they could have done to you.$B$BYou! You there! Please, you have to help me escape. One of them has a key, can you find it? I know they have it. If you get it, you can help me get out of here. Trey is probably already dead, but there's still time! Please, can you help me?" },
        ["text"] = "Так холодно... і голодно.$B$BМій бідний друже, сподіваюся, ти знайшов спокій. Я не можу навіть думати про те, що вони могли з тобою зробити.$B$BТи! Гей, ти! Будь ласка, допоможи мені втекти. В одного з них є ключ, знайдеш його? Я знаю, що він у них. Якщо дістанеш, зможеш допомогти мені вибратися. Трей, мабуть, уже мертвий, але ще є час! Будь ласка, допоможеш?",
        ["npcs"] = { [1] = 11016 },
        ["roles"] = { ["greeting"] = true },
    },
    [4155897878] = {
        ["english"] = { [1] = "May da spirits protect you mon." },
        ["text"] = "Нехай духи захищають тебе, друже.",
        ["npcs"] = { [1] = 3403 },
        ["roles"] = { ["greeting"] = true },
    },
    [3493732104] = {
        ["english"] = { [1] = "Not just any fish, mortal. This fish was a minnow. A very special minnow." },
        ["text"] = "Не просто якась риба, смертний. Це був мальок. Дуже особливий мальок.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [4279814893] = {
        ["english"] = { [1] = "Look for it high up on the west side of the Valley of Strength. They'll only let you in if you're an officer! Talk to Sergeant Ba'sha outside otherwise." },
        ["text"] = "Шукай високо на західному боці Долини Сили. Усередину пускають лише офіцерів! Якщо ти не офіцер, поговори із сержантом Ба’шою надворі.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3775924991] = {
        ["english"] = { [1] = "Learning about new plant species is extremely important for our expedition.  Not just the medicinal or edible ones either.$B$BPlants provide the foundation for many other forms of life to exist.  Understanding them allows us to better understand nature as a whole." },
        ["text"] = "Вивчення нових видів рослин надзвичайно важливе для нашої експедиції.  І не лише лікувальних чи їстівних.$B$BРослини є основою існування багатьох інших форм життя.  Розуміючи їх, ми краще розуміємо природу загалом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3146572848] = {
        ["english"] = { [1] = "Smokeywood Pastures has set up shop in Orgrimmar and Ironforge. I wonder what they'll dream up this year?" },
        ["text"] = "«Пасовища Димного Лісу» відкрили крамниці в Орґріммарі та Залізогарті. Цікаво, що вони вигадають цього року?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4100779666] = {
        ["english"] = { [1] = "May the Light protect you this day." },
        ["text"] = "Нехай Світло захищає тебе цього дня.",
        ["npcs"] = { [1] = 925, [2] = 927, [3] = 928, [4] = 5491, [5] = 5492, [6] = 8140 },
        ["roles"] = { ["greeting"] = true },
    },
    [3728648072] = {
        ["english"] = { [1] = "Skinning" },
        ["text"] = "Зняття шкур",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [40] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [3810641523] = {
        ["english"] = { [1] = "No time to talk -- I have work to do!" },
        ["text"] = "Немає часу на балачки — у мене робота!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3726145816] = {
        ["english"] = { [1] = "Look around you $c.  You are in rare company to be certain, yet still I think you need to prove yourself.  Hmm, perhaps I shall allow you to aid us in our cause at Arathi Basin.  Would you like that?" },
        ["text"] = "Озирнися, $c.  Ти справді серед добірного товариства, але, гадаю, тобі ще треба себе довести.  Гм, можливо, я дозволю тобі допомогти нашій справі в Низині Араті.  Хочеш?",
        ["npcs"] = { [1] = 15007 },
        ["roles"] = { ["greeting"] = true },
    },
    [3236408263] = {
        ["english"] = { [1] = "Not much fishing to be had around here, but what little there is to be had is Paxton's ye can be sure.  Ye can find him fishing out on Iceflow Lake." },
        ["text"] = "Тут рибалити особливо ніде, але якщо вже десь і можна, то Пакстон точно знає де.  Знайдеш його з вудкою біля озера Крижаного Потоку.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3745955190] = {
        ["english"] = { [1] = "Not bad. Go talk with Snarl, he just moved to Orgrimmar to study under Saru. Look for him in the Warrior district near Saru's smithy. Oh and he'll test you, so you better be as ready as you think you are." },
        ["text"] = "Непогано. Поговори зі Снарлом, він щойно перебрався в Орґріммар, щоб навчатися в Сару. Шукай його у Військовому районі біля кузні Сару. І так, він тебе випробує, тож краще будь настільки готовий, наскільки сам думаєш.",
        ["npcs"] = { [1] = 3174 },
        ["roles"] = { ["greeting"] = true },
    },
    [4236118871] = {
        ["english"] = { [1] = "Smashing the pumpkin reveals a hidden treasure!  This is the greatest day you've ever known!" },
        ["text"] = "Розбивши гарбуз, ти знаходиш прихований скарб!  Це найкращий день у твоєму житті!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2380098219] = {
        ["english"] = { [1] = "Slow down, $r. The one you need to kill is already dead. Killing him again will serve no purpose. There are very few ways in which a lich can actually be destroyed and none of those means are available to you or I. That is why I have a plan. A plan that will have a very noticeable and real impact upon the Cult." },
        ["text"] = "Не поспішай, $r. Той, кого тобі треба вбити, вже мертвий. Убивати його ще раз немає сенсу. Ліча можна справді знищити лише кількома способами, і жоден із них недоступний ні тобі, ні мені. Саме тому в мене є план. План, який матиме дуже помітний і цілком реальний вплив на Культ.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [1716427232] = {
        ["english"] = { [1] = "My watch is eternal, mortal." },
        ["text"] = "Моя варта вічна, смертний.",
        ["npcs"] = { [1] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [1740788630] = {
        ["english"] = { [1] = "Slip a little coin into the boss's hand and look what it gets ya. I love my job. Though, if I could find a way to get that little firecracker Snurk reassigned to this port....well, I can't imagine it any better. But i'm betting that you aren't here about my bussiness practices. You're looking for a Zeppelin to Undercity, am I right? Well, that's great, because it docks rigt here behind me. Oh and hey, if you see Snurk, put a good word in for me, would ya?" },
        ["text"] = "Підсунь босу монетку — й дивись, що отримуєш. Обожнюю свою роботу. От якби ще вдалося перевести сюди в порт ту запальну малу Снурк... кращого й уявити не можу. Але ти, мабуть, не заради моїх ділових методів прийшов. Шукаєш дирижабль до Підміста, так? Чудово, бо він причалює просто тут, у мене за спиною. І якщо побачиш Снурк, замов за мене добре слово, гаразд?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3520980104] = {
        ["english"] = { [1] = "It's great bein' a member of da \"Brew of the Month\" club." },
        ["text"] = "Кайфово бути членом клубу «Хміль місяця».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2241820302] = {
        ["english"] = { [1] = "Ragefire" },
        ["text"] = "Лють Вогню",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [3123998818] = {
        ["english"] = { [1] = "Oh, the ever-present obsession with material wealth.  Well, fortune smiles on you, as you can find the auction house in the Tradesman's Terrace." },
        ["text"] = "О, ця вічна одержимість матеріальними багатствами.  Що ж, удача тобі всміхнулася: аукціонний дім знайдеш на Торговій терасі.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1694594678] = {
        ["english"] = { [1] = "Michelle Belle's bedside manner is remarkable!  While she might not be able to teach you that, she surely could teach you some proper First Aid.  She currently resides in the Lion's Pride Inn." },
        ["text"] = "Мішель Белль чудово вміє поводитися з пацієнтами!  Цього вона, може, й не навчить, зате Першої допомоги — залюбки.  Зараз вона мешкає в таверні «Гордість Лева».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [4272071823] = {
        ["english"] = { [1] = "Officers' Lounge" },
        ["text"] = "Офіцерська вітальня",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["reply"] = true },
    },
    [298602742] = {
        ["english"] = { [1] = "Looking for Shenthul of the Shadowswift Brotherhood, huh?  In The Drag across from Droffers and Son Salvage look for a tunnel leading down into the Cleft of Shadow." },
        ["text"] = "Шукаєш Шентула з Братства Тіньової Прудкості, еге?  У Хитрому провулку навпроти «Дроффер і син: утиль» шукай тунель, що веде вниз у Розколину Тіні.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1960767005] = {
        ["english"] = { [1] = "Ner'zhul is my answer." },
        ["text"] = "Моя відповідь — Нер’зул.",
        ["npcs"] = { [1] = 4488 },
        ["roles"] = { ["reply"] = true },
    },
    [4022606115] = {
        ["english"] = { [1] = "Looks like you had the same idea I did. Hunting for fruit, are you?" },
        ["text"] = "Схоже, нам спало на думку одне й те саме. Фрукти шукаєш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1829526179] = {
        ["english"] = { [1] = "Please teach me." },
        ["text"] = "Навчи мене, будь ласка.",
        ["npcs"] = { [1] = 2485, [2] = 2489, [3] = 2492, [4] = 4165, [5] = 5957, [6] = 5958 },
        ["roles"] = { ["reply"] = true },
    },
    [1121804708] = {
        ["english"] = { [1] = "So you have come to Niby to learn the secrets of calling down an infernal servant from the Nether.$B$BSilence! Niby knows all!$B$BNiby is not so quick to part with such knowledge. First, you must assist Niby with a very important task." },
        ["text"] = "Отже, ти прийшов до Нібі, щоб дізнатися таємниці прикликання інфернального слуги з Порожнечі.$B$BТихо! Нібі все знати!$B$BНібі не так легко ділитися такими знаннями. Спершу ти маєш допомогти Нібі з дуже важливим завданням.",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["greeting"] = true },
    },
    [2468633313] = {
        ["english"] = { [1] = "Keep your wits about you, $r, we're surrounded by the walking dead here." },
        ["text"] = "Не втрачай голови, $r, тут нас оточують ходячі мерці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2048457547] = {
        ["english"] = { [1] = "Place Termite Barrel on the crate." },
        ["text"] = "Постав бочку з термітами на ящик.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2351099813] = {
        ["english"] = { [1] = "Six Lieutenants control the front line's defenses. They must be destroyed first and fast! We cannot risk one of their priests returning the fallen Lieutenants to life.$B$BShould all of the Lieutenants be killed in quick succession, the morale of the front lines will falter! It will be shattered! Their troops will run in fear, leaving the remaining soldiers without backup." },
        ["text"] = "Шість лейтенантів контролюють оборону передової. Їх треба знищити першими й швидко! Не можна ризикувати, що один із їхніх жерців поверне полеглих лейтенантів до життя.$B$BЯкщо всіх лейтенантів убити один за одним за короткий час, бойовий дух передової зламається! Він буде розтрощений! Їхні війська втечуть у страху, залишивши решту солдатів без підтримки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2293876272] = {
        ["english"] = { [1] = "Shadow Hunter Denjai uses this board to post important announcements and news of bounties on the foes of Zabra'jin." },
        ["text"] = "Мисливець тіней Денджай використовує цю дошку для важливих оголошень і повідомлень про винагороди за ворогів Забра’джина.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2764111522] = {
        ["english"] = { [1] = "Just browsing my wares or is there something specific I can help you find today?" },
        ["text"] = "Просто розглядаєш мої товари чи я можу допомогти знайти щось конкретне?",
        ["npcs"] = { [1] = 277, [2] = 279, [3] = 338, [4] = 482, [5] = 483, [6] = 1257, [7] = 1275, [8] = 1285, [9] = 1286, [10] = 1287, [11] = 1289, [12] = 1291, [13] = 1294, [14] = 1295, [15] = 1297, [16] = 1298, [17] = 1299, [18] = 1301, [19] = 1316, [20] = 1402, [21] = 1427, [22] = 1428, [23] = 1431, [24] = 3518, [25] = 4959, [26] = 4981, [27] = 5386, [28] = 5494, [29] = 6174, [30] = 16105 },
        ["roles"] = { ["greeting"] = true },
    },
    [1277373347] = {
        ["english"] = { [1] = "Look up to the heavens, $c. The Dragonflights have not been seen in this area for a thousand years! Those Qiraji are up to something, I just know it!" },
        ["text"] = "Поглянь у небо, $c. Драконячих зграй не бачили в цих краях уже тисячу років! Ці кіражі щось замислили, я певен!",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [2522676363] = {
        ["english"] = { [1] = "It's quite simple, really, $N. My old merc company, The Veiled Blade, took the wrong mission at the wrong time.$B$BWe were hired by a goblin smuggler out of Booty Bay, one Gremnik Rizzlesprang, who was covetous of Lord Valthalak's spellbook. Or, maybe there was some old rivalry there? I suppose we'll never know now, because Gremnik was killed not too long ago by a group of Valthalak's spectral assassins. They really can be very deadly when a large number of them gather.$B$BWhere was I?" },
        ["text"] = "Усе досить просто, $N. Моя стара рота найманців, «Завуальований Клинок», взялася не за те завдання й не в той час.$B$BНас найняв гоблін-контрабандист із Бухти Наживи на ім’я Ґремнік Різлспренґ, якому кортіло заволодіти книгою заклять лорда Валтахака. А може, між ними була якась давня ворожнеча? Тепер ми вже, мабуть, ніколи не дізнаємося, бо нещодавно Ґремніка вбила група примарних убивць Валтахака. Коли їх збирається багато, вони справді можуть бути смертельно небезпечними.$B$BНа чому я зупинився?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [1466616073] = {
        ["english"] = { [1] = "Leave me.  My wounds are great and I fear they will overtake me.  Thank you, $N.  I will die here, but because of you... I'll die in peace." },
        ["text"] = "Залиш мене.  Мої рани надто тяжкі, і боюся, вони мене здолають.  Дякую, $N.  Я помру тут, але завдяки тобі... помру з миром у душі.",
        ["npcs"] = { [1] = 10917 },
        ["roles"] = { ["greeting"] = true },
    },
    [2183114021] = {
        ["english"] = { [1] = "May de spirits guide ya, $c." },
        ["text"] = "Нехай духи ведуть тебе, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2122151406] = {
        ["english"] = { [1] = "Kalaran, please enchant the torch." },
        ["text"] = "Каларане, будь ласка, зачаруй смолоскип.",
        ["npcs"] = { [1] = 8479 },
        ["roles"] = { ["reply"] = true },
    },
    [1600184071] = {
        ["english"] = { [1] = "It's simple, really. Rob the lich, Ras Frostwhisper, of his powers. Return him to his mortal form and then slay him, once and for all." },
        ["text"] = "Усе просто. Позбавити ліча Раса Морозошепота його сил. Повернути йому смертну подобу, а тоді вбити раз і назавжди.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [3723701897] = {
        ["english"] = { [1] = "Mighty fine weather we're having here, wouldn't you say?" },
        ["text"] = "Чудова сьогодні погода, правда?",
        ["npcs"] = { [1] = 10305 },
        ["roles"] = { ["greeting"] = true },
    },
    [1844270850] = {
        ["english"] = { [1] = "Speak to Pephredo at the Darkbriar Lodge in the Valley of Spirits, up above and to the west of the Valley of Strength." },
        ["text"] = "Поговори з Пефредо в оселі Темної Жини в Долині Духів, вище й на захід від Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1092936187] = {
        ["english"] = { [1] = "Sit and listen to my story, $r." },
        ["text"] = "Сідай і вислухай мою історію, $r.",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["greeting"] = true },
    },
    [2418172829] = {
        ["english"] = { [1] = "Splendid! Marvelous! An excellent performance!" },
        ["text"] = "Прекрасно! Дивовижно! Чудовий виступ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1564056446] = {
        ["english"] = { [1] = "Sir! Until my body ceases to function!" },
        ["text"] = "Пане! До останньої миті функціонування мого тіла!",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["reply"] = true },
    },
    [1081329692] = {
        ["english"] = { [1] = "Sinu a'manore. If you seek to learn how to conjure a portal to Theramore, I can show you." },
        ["text"] = "Sinu a'manore. Якщо хочеш навчитися створювати портал до Терамора, я покажу тобі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [285762068] = {
        ["english"] = { [1] = "Some supplies for the road?  Perhaps a refreshment to enjoy while you watch the fights?" },
        ["text"] = "Припаси в дорогу?  Може, щось освіжаюче, поки дивишся бої?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2360256711] = {
        ["english"] = { [1] = "Promised One, we thank you for the warning. The Stillpine tribe will be prepared." },
        ["text"] = "Обіцяний, дякуємо за попередження. Плем’я Тихої Сосни буде готове.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3784146883] = {
        ["english"] = { [1] = "Losing my life was a danger I had come to terms with.  Losing Ysida is something I cannot endure, even after my own death." },
        ["text"] = "Я змирився з небезпекою втратити власне життя.  Але втратити Ісіду — цього я не витримаю навіть після своєї смерті.",
        ["npcs"] = { [1] = 16016 },
        ["roles"] = { ["greeting"] = true },
    },
    [121593077] = {
        ["english"] = { [1] = "Our friends in the Alliance gather to fight alongside the Silverwing Sentinels in Warsong Gulch. Will you travel there to help them?" },
        ["text"] = "Наші друзі з Альянсу збираються битися пліч-о-пліч зі Срібнокрилими Вартовими в Ущелині Пісні Війни. Вирушиш туди допомогти їм?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3415876092] = {
        ["english"] = { [1] = "Shaman" },
        ["text"] = "Шаман",
        ["npcs"] = { [1] = 1423, [2] = 3084, [3] = 3212, [4] = 3215, [5] = 3217, [6] = 3218, [7] = 3219, [8] = 3220, [9] = 3221, [10] = 3222, [11] = 3223, [12] = 3224, [13] = 3296, [14] = 5953 },
        ["roles"] = { ["reply"] = true },
    },
    [1121012929] = {
        ["english"] = { [1] = "It's here... somewhere... I know it. Somewhere in this library is the knowledge I'm looking for..." },
        ["text"] = "Воно тут... десь тут... Я знаю. Десь у цій бібліотеці є знання, яких я шукаю...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4042148510] = {
        ["english"] = { [1] = "Many locked supply boxes were lost when the Naga overran the Zoram Strand in Ashenvale." },
        ["text"] = "Чимало замкнених ящиків із припасами було втрачено, коли наґи захопили Зорамське узбережжя в Ясенедолі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1275918660] = {
        ["english"] = { [1] = "Oh... one of those types.  Well, Maximillian is the only one around here that knows about the dark arts.  You can probably find him in the dark of the Lion's Pride Inn basement." },
        ["text"] = "О... один із таких.  Що ж, Максиміліан тут єдиний, хто знається на темних мистецтвах.  Напевно, знайдеш його в темряві підвалу таверни «Гордість Лева».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3391859717] = {
        ["english"] = { [1] = "Since we've begun our stay in the crater, Dadanga's taken a liking to the large bloodpetal sprouts that grow all over the place here.$B$BI'm sure she'd enjoy a snack, if you feel like bringing her some..." },
        ["text"] = "Відколи ми оселилися в кратері, Даданґа полюбила великі паростки кровопелюстки, що ростуть тут усюди.$B$BУпевнений, вона не відмовиться від перекусу, якщо принесеш їй трохи...",
        ["npcs"] = { [1] = 9273 },
        ["roles"] = { ["greeting"] = true },
    },
    [3281104031] = {
        ["english"] = { [1] = "Ohh, thank you soo much for getting me out of that cage because I was in there for soo long and it smelled like minced mutton that had been sitting out in the sun for a week and I don't like mutton to begin with because when I was little, well littler, I was actually turned into a sheep for a minute and so I know what it feels like to be a sheep and I don't want someone eating me, especially an overgrown troll dressed up like a kitty....$b$b<Ashli takes a deep breath.>$b$bHow's my hair?$B" },
        ["text"] = "О-о, дуже тобі дякую, що витяг мене з тієї клітки, бо я сиділа там та-а-ак довго, а пахло там як рубана баранина, що тиждень пролежала на сонці, а я й так не люблю баранину, бо коли була маленькою, ну ще меншою, мене якось на хвилину перетворили на вівцю, тож я знаю, як це — бути вівцею, і не хочу, щоб мене хтось з’їв, особливо здоровенний троль, перевдягнений котиком....$b$b<Ешлі глибоко вдихає.>$b$bЯк моя зачіска?$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1417749096] = {
        ["english"] = { [1] = "Since the fall of Dalaran and the destruction of Quel'Thalas, wares of this sort have been hard to come by. But Lucan Cordell and some of our other Tradesman have been doing a fine job of filling our orders with quality merchandise." },
        ["text"] = "Після падіння Даларана й знищення Квел’Таласа такі товари стало важко дістати. Але Лукан Корделл та інші наші торговці чудово виконують замовлення й постачають якісні речі.",
        ["npcs"] = { [1] = 297, [2] = 1141, [3] = 1304, [4] = 1307, [5] = 1308, [6] = 1309, [7] = 1310, [8] = 1312, [9] = 1313, [10] = 1314, [11] = 1315, [12] = 1318, [13] = 1347, [14] = 1405, [15] = 1413, [16] = 1414, [17] = 1415, [18] = 2330, [19] = 3627, [20] = 4078, [21] = 4984, [22] = 5081, [23] = 7295, [24] = 11827, [25] = 11828, [26] = 14497 },
        ["roles"] = { ["greeting"] = true },
    },
    [4093533805] = {
        ["english"] = { [1] = "Nana always said there was no greater thing in the whole world than a warm, toasty slice of fresh, homemeade cherry pie." },
        ["text"] = "Бабуся завжди казала, що немає у світі нічого кращого за теплий, підсмажений шматок свіжого домашнього вишневого пирога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3843133421] = {
        ["english"] = { [1] = "Since my husband left for the front, Helene here has been my strength. Her kind heart and sharp sword have helped me through a lot of tough times. I don't know what I would've done without her." },
        ["text"] = "Відтоді як мій чоловік пішов на фронт, Гелена стала моєю опорою. Її добре серце й гострий меч допомогли мені пережити чимало тяжких часів. Не знаю, що б я без неї робила.",
        ["npcs"] = { [1] = 1632 },
        ["roles"] = { ["greeting"] = true },
    },
    [1967683542] = {
        ["english"] = { [1] = "Nadyia has made quite the leatherworker in her years of practice.  Travel west on the road to Darnassus to pay her a visit and maybe she can bestow some of her knowledge upon you." },
        ["text"] = "За роки практики Надія стала чудовою шкіряницею.  Іди дорогою на захід у бік Дарнаса, навідай її — можливо, вона поділиться з тобою знаннями.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [3886128742] = {
        ["english"] = { [1] = "Just a minor adjustment here... ah there we go!" },
        ["text"] = "Лише невеличке регулювання... ага, ось так!",
        ["npcs"] = { [1] = 1702 },
        ["roles"] = { ["greeting"] = true },
    },
    [4235815718] = {
        ["english"] = { [1] = "My sister Silanna is naive to the growing danger in these woods. But like it or not, as soon as I get this wagon loaded we're moving within the city walls. $b$bIt appears that I've got more bags here than I need. Perhaps you could make use of them.$B" },
        ["text"] = "Моя сестра Сіланна наївно недооцінює небезпеку, що зростає в цих лісах. Та хоче вона того чи ні, щойно я завантажу цей віз, ми переїдемо за міські мури. $b$bСхоже, тут у мене більше сумок, ніж потрібно. Може, вони стануть тобі в пригоді.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [940738857] = {
        ["english"] = { [1] = "Leave this place, stranger, lest it consume you as it has all that it has touched." },
        ["text"] = "Залиш це місце, незнайомцю, доки воно не поглинуло й тебе, як усе, до чого торкалося.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["greeting"] = true },
    },
    [4293829027] = {
        ["english"] = { [1] = "Move along, rube." },
        ["text"] = "Проходь далі, телепню.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [3888039775] = {
        ["english"] = { [1] = "Since landing here I have seen horrors that had previously only haunted my darkest nightmares, but nothing could have prepared me for what lies beyond the mist.$B$B<Mootoo nods.>$B$BThrough that fog, not more than a few yards from us, stand the bloodthirsty creatures known as Kvaldir. None have returned from the fog and few that were originally at the landing when the mist rolled in have escaped. The area has since been condemned by Hellscream. Enter at your own risk..." },
        ["text"] = "Відтоді як ми висадилися тут, я побачив жахи, що раніше переслідували лише найтемніші мої кошмари, але ніщо не могло підготувати мене до того, що ховається за туманом.$B$B<Муту киває.>$B$BЗа тим туманом, лише за кілька ярдів звідси, стоять кровожерні істоти, відомі як квалдіри. Ніхто не повернувся з туману, і лише небагатьом із тих, хто був на березі, коли він насунувся, вдалося втекти. Відтоді Пеклокрик оголосив цю територію забороненою. Заходь на свій страх і ризик...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2937170418] = {
        ["english"] = { [1] = "My apologies, I did not realize that you could understand what I was saying. What is it you are doing out here?" },
        ["text"] = "Перепрошую, я не зрозумів, що ти можеш мене розуміти. Що ти тут робиш?",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["reply"] = true },
    },
    [1783622320] = {
        ["english"] = { [1] = "Read on, if you dare..." },
        ["text"] = "Читай далі, якщо наважишся...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3069439319] = {
        ["english"] = { [1] = "Sin'dorei have lost far too much in the past years.  Our land, our homes, even our identities...$B$BIt's about time we started taking it all back." },
        ["text"] = "Сін’дорай втратили надто багато за останні роки.  Нашу землю, домівки, навіть саму ідентичність...$B$BНастав час почати повертати все це.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [773068140] = {
        ["english"] = { [1] = "Kildrath tends to overdramatize the situation. For example, \"Garona: A Study on Stealth and Treachery,\" has been stolen over 400 times.$B$BThe mark of the Athenaeum protects the tomes, preventing any unauthorized viewings." },
        ["text"] = "Кілдрат полюбляє надмірно драматизувати. Наприклад, «Ґарона: дослідження скритності та зради» викрадали вже понад 400 разів.$B$BЗнак Читальні захищає фоліанти й не дає нікому переглядати їх без дозволу.",
        ["npcs"] = { [1] = 14382 },
        ["roles"] = { ["greeting"] = true },
    },
    [3192264679] = {
        ["english"] = { [1] = "Now ye just be fass and facety, mon!  Ye fixin' fe vex me, ye maga dog blaggard?$B$BG'waan den, ye lily-livered scallywag.  Be seen ya first light!" },
        ["text"] = "Оце ти нахабний і зухвалий, друже!  Ти мене дратувати надумав, клятий пес?$B$BНу то йди, боягузливий сухопутний щур.  Побачимося на світанку!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4170176211] = {
        ["english"] = { [1] = "Simply stated, this is correct.$B$BThe Earthen's physical features are that of a smaller stature humanoid, though their composition is that of Azeroth's various stone core compounds.  Their design maximizes strength and stamina without sacrificing cognitive processing power.  Their skin and musculature are nearly impervious to physical damage, and with very minor modifications the Earthen display a remarkable resiliency to unwanted magical forces." },
        ["text"] = "Простіше кажучи, це правильно.$B$BЗемельники мають фізичні риси невисоких гуманоїдів, але їхній склад утворений із різних кам’яних речовин ядра Азероту.  Їхня конструкція максимізує силу й витривалість без втрати обчислювальної здатності.  Їхня шкіра й мускулатура майже невразливі до фізичної шкоди, а після зовсім незначних змін земельники демонструють надзвичайну стійкість до небажаних магічних сил.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [2931803766] = {
        ["english"] = { [1] = "Our units are upgraded to Veteran, but I don't have enough supplies to upgrade them to Champion." },
        ["text"] = "Наші підрозділи вже ветерани, але припасів, щоб зробити їх чемпіонами, бракує.",
        ["npcs"] = { [1] = 13257 },
        ["roles"] = { ["greeting"] = true },
    },
    [852556267] = {
        ["english"] = { [1] = "My people, they are as shattered as the relic you seek to repair." },
        ["text"] = "Мій народ розбитий так само, як реліквія, яку ти прагнеш відновити.",
        ["npcs"] = { [1] = 10304 },
        ["roles"] = { ["greeting"] = true },
    },
    [3856664540] = {
        ["english"] = { [1] = "Simmer say Gordo got guts, but got no brains.  Why he mean?" },
        ["text"] = "Сіммер казати, Ґордо мати кишки, але не мати мізків.  Що він мати на увазі?",
        ["npcs"] = { [1] = 10666 },
        ["roles"] = { ["greeting"] = true },
    },
    [271666656] = {
        ["english"] = { [1] = "Sildinair has trained many of the Sentinels who guard our beloved city.  I am certain she can make a warrior out of the likes of you.  Seek her out at the Warrior's Terrace near the entrance to our city." },
        ["text"] = "Сілдінаїр навчила багатьох Вартових, які захищають наше улюблене місто.  Я певен, вона зробить воїна навіть із тебе.  Шукай її на Терасі Воїнів біля входу до міста.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [22237846] = {
        ["english"] = { [1] = "Recover the scepter shard, $N. Nefarius must not be allowed to destr... destroy the shard." },
        ["text"] = "Поверни уламок скіпетра, $N. Не можна дозволити Нефарію знищ... знищити уламок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2763445592] = {
        ["english"] = { [1] = "My younger brother here is quite the rising star in the Consortium. Of course, he's too modest to acknowledge it." },
        ["text"] = "Мій молодший брат тут — справжня висхідна зірка Консорціуму. Звісно, він надто скромний, щоб це визнати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2013677151] = {
        ["english"] = { [1] = "Lisrythe may be a bit... intimidating at first, but she stocks what you are looking for. She sells her wares outside the large library on Scryer's Tier." },
        ["text"] = "Лісріт спершу може здатися трохи... страхітливою, але в неї є те, що ти шукаєш. Вона торгує біля великої бібліотеки на Ярусі Провидців.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [24430612] = {
        ["english"] = { [1] = "Mmrrglglglg? Glbmr brmmrggl glmrrbmrgl.$B$BGrglgrlbrr mrgl!!!" },
        ["text"] = "Ммррґлґлґлґ? Ґлбмр брммрґґл ґлмррбмрґл.$B$BҐрґлґрлбрр мрґл!!!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2747085779] = {
        ["english"] = { [1] = "Lexicon of Power" },
        ["text"] = "Лексикон сили",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3932619175] = {
        ["english"] = { [1] = "Shut inside this little house, I dream of joining the battles that rage outside the city walls. Still, duty compels me to share my knowledge with others who fight in my stead... for now." },
        ["text"] = "Замкнений у цьому маленькому будинку, я мрію приєднатися до битв, що вирують за міськими мурами. Та обов’язок змушує мене ділитися знаннями з тими, хто б’ється замість мене... поки що.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1792741357] = {
        ["english"] = { [1] = "My job title is Waste Management Specialist." },
        ["text"] = "Моя посада — фахівець з утилізації відходів.",
        ["npcs"] = { [1] = 11316 },
        ["roles"] = { ["greeting"] = true },
    },
    [4117351877] = {
        ["english"] = { [1] = "Shredders?!  They just won't cut it anymore.  They're so yesterday!$B$BIf we're going to build rockets - if we're going to get the X-52 off the ground - we need better tech!" },
        ["text"] = "Кришильники?!  Вони вже нікуди не годяться.  Це вчорашній день!$B$BЯкщо ми хочемо будувати ракети — якщо хочемо підняти X-52 у повітря — потрібні кращі технології!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3288848329] = {
        ["english"] = { [1] = "Show me where I can fly." },
        ["text"] = "Покажи, куди я можу полетіти.",
        ["npcs"] = { [1] = 931, [2] = 1387, [3] = 1571, [4] = 2299, [5] = 2389, [6] = 2409, [7] = 2432, [8] = 2835, [9] = 2851, [10] = 2861, [11] = 4267, [12] = 4312, [13] = 4317, [14] = 4319, [15] = 4321, [16] = 4407, [17] = 6026, [18] = 6706, [19] = 6726, [20] = 7823, [21] = 7824, [22] = 8018, [23] = 8019, [24] = 8020, [25] = 8609, [26] = 8610, [27] = 10583, [28] = 10897, [29] = 11138, [30] = 11139, [31] = 11899, [32] = 11901, [33] = 12577, [34] = 12578, [35] = 12596, [36] = 12616, [37] = 12617, [38] = 12740, [39] = 13177, [40] = 15177, [41] = 15178, [42] = 16227 },
        ["roles"] = { ["reply"] = true },
    },
    [2212832075] = {
        ["english"] = { [1] = "Ready for training? Then try to keep up, $N. We've got a lot of ground to cover." },
        ["text"] = "Готовий тренуватися? Тоді не відставай, $N. Нам треба багато чого пройти.",
        ["npcs"] = { [1] = 4611 },
        ["roles"] = { ["greeting"] = true },
    },
    [394235912] = {
        ["english"] = { [1] = "Not right now, $gpal:sugar;... I got things to do. See ya around." },
        ["text"] = "Не зараз, $gдруже:солоденька;... у мене справи. Ще побачимося.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [697675438] = {
        ["english"] = { [1] = "Show me what you got! You won't be sorry, I promise!" },
        ["text"] = "Покажи, що маєш! Не пошкодуєш, обіцяю!",
        ["npcs"] = { [1] = 8736 },
        ["roles"] = { ["greeting"] = true },
    },
    [2239658050] = {
        ["english"] = { [1] = "Show me what I have access to, Lokhtos." },
        ["text"] = "Покажи, до чого я маю доступ, Локтосе.",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["reply"] = true },
    },
    [2631442799] = {
        ["english"] = { [1] = "Listen to the stories of an elder. $N. I have many to speak of..." },
        ["text"] = "Послухай оповіді старійшини, $N. Мені є про що розповісти...",
        ["npcs"] = { [1] = 7776 },
        ["roles"] = { ["greeting"] = true },
    },
    [2519473404] = {
        ["english"] = { [1] = "Of all the wondrous places within Darnassus, which would you have me direct you to?" },
        ["text"] = "До якого з дивовижних місць Дарнаса тебе провести?",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1893010711] = {
        ["english"] = { [1] = "Oh, you must mean the Stormwind Counting House.  It's not far from the gates after you enter Stormwind." },
        ["text"] = "О, ти, мабуть, маєш на увазі Рахункову палату Штормовію.  Вона недалеко від брами, щойно ввійдеш у Штормовій.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2607990881] = {
        ["english"] = { [1] = "Show me what hooch you've got to sell, Kreeg." },
        ["text"] = "Покажи, яку випивку продаєш, Кріґу.",
        ["npcs"] = { [1] = 14322 },
        ["roles"] = { ["reply"] = true },
    },
    [3560755440] = {
        ["english"] = { [1] = "Only a mage can learn portal magic, $c." },
        ["text"] = "Лише маг може опанувати магію порталів, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3557661889] = {
        ["english"] = { [1] = "Only you can save me from Kaganishu, $N." },
        ["text"] = "Лише ти можеш врятувати мене від Каґанішу, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1974968632] = {
        ["english"] = { [1] = "Of course there's no danger in everything catching flames and exploding like a huge helium bomb. This baby will get you to Undercity faster and safer than any boat, and the view is truly breathtaking. Speaking of breath, smoking is not allowed on board the zeppelin, and fire spells are banned from being cast during the trip." },
        ["text"] = "Звісно, жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить тебе до Підміста швидше й безпечніше за будь-який корабель, а краєвид просто перехоплює подих. До речі про подих: на борту дирижабля не можна курити, а під час польоту заборонено застосовувати вогняні закляття.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [147767428] = {
        ["english"] = { [1] = "Our forces in Alterac Valley need wisdom to achieve victory $c.  You look like the one to lead them." },
        ["text"] = "Нашим силам в Альтерацькій долині потрібна мудрість для перемоги, $c.  Схоже, саме ти можеш їх повести.",
        ["npcs"] = { [1] = 7427 },
        ["roles"] = { ["greeting"] = true },
    },
    [2447456257] = {
        ["english"] = { [1] = "Let's go!" },
        ["text"] = "Ходімо!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3817667675] = {
        ["english"] = { [1] = "Shoja'my is over in front of the inn.  Now move along, I'm busy." },
        ["text"] = "Шоджа’мі стоїть перед заїздом.  А тепер іди, я зайнятий.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2129827765] = {
        ["english"] = { [1] = "Shhh... do you smell something?" },
        ["text"] = "Тс-с... ти щось відчуваєш?",
        ["npcs"] = { [1] = 10778 },
        ["roles"] = { ["greeting"] = true },
    },
    [2674172785] = {
        ["english"] = { [1] = "Shh! Keep your voice down. The babes are sleeping." },
        ["text"] = "Тсс! Тихіше. Малюки сплять.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [385204883] = {
        ["english"] = { [1] = "On behalf of the Royal Apothecary Society, I am pleased to offer you the finest steeds available for the Forsaken.  These beasts have endured trials and tribulations as we all have, and now they too have emerged stronger and more resilient than mere mortal flesh would have had them destined to be!  Please, inspect them for yourself and see." },
        ["text"] = "Від імені Королівського товариства аптекарів я радий запропонувати тобі найкращих скакунів, доступних Відреченим.  Ці звірі пережили випробування й негаразди, як і всі ми, і теж вийшли з них сильнішими та витривалішими, ніж дозволила б їм проста смертна плоть!  Оглянь їх сам і переконайся.",
        ["npcs"] = { [1] = 4731 },
        ["roles"] = { ["greeting"] = true },
    },
    [3754192473] = {
        ["english"] = { [1] = "Revered." },
        ["text"] = "Шанований.",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [2814756229] = {
        ["english"] = { [1] = "My poor flying machine. She didn't survive the crash and without spare parts, I'll never get 'er up and running again!" },
        ["text"] = "Моя бідолашна літальна машина. Вона не пережила аварії, а без запасних деталей я вже ніколи не підніму її в повітря!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2653270422] = {
        ["english"] = { [1] = "Sheesh, you don't have to beg! Anyways, I'm almost done with the story.$B$BSo, the whole company is in the middle of that massive chamber fighting over this amulet, and you know how it echoes in there! In the end it was broken into three pieces, and we rolled the dice, with it going to various people or groups.$B$BThe rest is a bit of a blur, though, because it was at about that time that old Valthalak's spirit decided to make an entrance and start summoning forth all of these spectral assassins." },
        ["text"] = "Та годі, не треба благати! Я вже майже закінчив історію.$B$BОтже, вся рота посеред тієї величезної зали б’ється за цей амулет, а ти знаєш, яка там луна! Зрештою його розбили на три частини, ми кинули кості, й уламки дісталися різним людям або групам.$B$BДалі все трохи як у тумані, бо саме тоді дух старого Валтахака вирішив з’явитися й почав викликати всіх цих примарних убивць.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [4118105289] = {
        ["english"] = { [1] = "No better place to learn First Aid than under the watchful eye of Shaina Fuller at the Cathedral of Light.  \010\010To get there, just look for the yellow rooftops, or the towering spire of the Cathedral itself which you can see from almost anywhere in the city." },
        ["text"] = "Немає кращого місця для навчання Першої допомоги, ніж під пильним оком Шайни Фуллер у Соборі Світла.  \010\010Щоб дістатися туди, шукай жовті дахи або високий шпиль самого Собору — його видно майже з будь-якої точки міста.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2780514970] = {
        ["english"] = { [1] = "She's a beaut', isn't she? Sky'ree... the faithful gryphon of our commander. Kurdran himself, he holds his audiences in th' stronghold. I care fer our Sky'ree here when he's busy. Gorgeous creature, she is; as strong and fierce as they come. She'd die fer Kurdran, she would. A more loyal soul ye've ne'er seen.'Tis an honor to care fer her, it is." },
        ["text"] = "Красуня, правда? Небокрила... вірний грифон нашого командира. Сам Курдран приймає відвідувачів у фортеці. Я доглядаю за Небокрилою, коли він зайнятий. Чудова істота — сильна й люта, яких мало. Вона віддала б життя за Курдрана. Вірнішої душі не знайдеш. Для мене честь доглядати її.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1769686031] = {
        ["english"] = { [1] = "Josetta has been a blessing to this town with her aid of the local guards.  If you seek her for training in the ways of a priest, you can find her in the Lion's Pride Inn." },
        ["text"] = "Джозетта стала справжнім благословенням для цього містечка, допомагаючи місцевій варті.  Якщо шукаєш її, щоб навчитися мистецтва жерця, знайдеш її в таверні «Гордість Лева».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1174812206] = {
        ["english"] = { [1] = "She now resides at the side of Emperor Thaurissan. He has her under some sort of powerful thought altering spell... and here I sit, completely helpless.\010" },
        ["text"] = "Тепер вона живе поруч з імператором Тауріссаном. Він тримає її під дією якихось могутніх чарів, що змінюють думки... а я сиджу тут абсолютно безпорадний.\010",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [2935133668] = {
        ["english"] = { [1] = "Press the red button labeled 'E.C.A.C.'" },
        ["text"] = "Натисни червону кнопку з написом «E.C.A.C.»",
        ["npcs"] = { [1] = 7166 },
        ["roles"] = { ["reply"] = true },
    },
    [2085607139] = {
        ["english"] = { [1] = "She demanded that we immediately head back to Hive'Regal! Brann would have none of that sass. He told her that there's no way we would go back into those hives without an army backing us up. It had gotten far too dangerous. The number of those stinking insects seemed to have tripled from when we first ventured into 'em.$B$BThat's when Natalia lost it!" },
        ["text"] = "Вона вимагала негайно повернутися до Вулика Реґал! Бранн не стерпів такої зухвалості. Він сказав, що ми нізащо не повернемося до тих вуликів без армії за спиною. Там стало надто небезпечно. Кількість тих смердючих комах, здавалося, потроїлася відтоді, як ми вперше туди сунулися.$B$BОт тоді Наталія й зірвалася!",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [3668966352] = {
        ["english"] = { [1] = "Press the yellow button labeled 'Thieves' Tools.'" },
        ["text"] = "Натисни жовту кнопку з написом «Злодійські інструменти».",
        ["npcs"] = { [1] = 7166 },
        ["roles"] = { ["reply"] = true },
    },
    [3506781034] = {
        ["english"] = { [1] = "Shadowfang Keep is in southern Silverpine just north of Pyrewood Village." },
        ["text"] = "Фортеця Тіньового Ікла розташована на півдні Срібного бору, трохи північніше селища Погребального Вогнища.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2798253470] = {
        ["english"] = { [1] = "Shadow Hunter Denjai sent me here with a small contingent of builders and warriors to establish this outpost. We've barely finished building it and he's already asking for reports!$B$BIf you need supplies, I can offer a few things, but we're still waiting for our first shipment." },
        ["text"] = "Мисливець тіней Денджай послав мене сюди з невеликим загоном будівельників і воїнів заснувати цю заставу. Ми ледве закінчили будівництво, а він уже вимагає звітів!$B$BЯкщо потрібні припаси, можу запропонувати кілька речей, але ми ще чекаємо на перше постачання.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1453579038] = {
        ["english"] = { [1] = "Ram racing is easier than it seems, but it takes skill to master. Just use the reins, eat apples if you can and avoid exhausting your ram." },
        ["text"] = "Перегони на баранах простіші, ніж здаються, але щоб стати майстром, потрібна вправність. Просто користуйся поводами, їж яблука, якщо можеш, і не виснажуй барана.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4229298238] = {
        ["english"] = { [1] = "Let's sing a song!$B$BBrew, brawl,$BBrew, brawl!$BA Dark Iron's life for me!$B$BHah hah!  $N, I like you!" },
        ["text"] = "Заспіваймо пісню!$B$BХміль, бійка,$BХміль, бійка!$BЖиття Темного Заліза — для мене!$B$BХа-ха!  $N, ти мені подобаєшся!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1984413352] = {
        ["english"] = { [1] = "Seymour, the principal skinner in Shattrath and grand master of the trade, may be found in the lower city's open marketplace." },
        ["text"] = "Сеймура, головного шкурника Шаттрату й великого майстра ремесла, можна знайти на відкритому ринку Нижнього міста.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [452822431] = {
        ["english"] = { [1] = "My brethren were here not long ago.  My connection to them has grown tenuous.  A powerful presence in the courtyard guards the way forward." },
        ["text"] = "Мої побратими були тут зовсім недавно.  Мій зв’язок із ними слабшає.  Шлях уперед у дворі охороняє могутня присутність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2915947312] = {
        ["english"] = { [1] = "So why are you still here?" },
        ["text"] = "То чому ти досі тут?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2234722406] = {
        ["english"] = { [1] = "Oy, mon!$b$bThis not be what it looks like. Well, maybe...$b$bIt be complicated." },
        ["text"] = "Ой, друже!$b$bЦе не те, що здається. Ну, може...$b$bВсе складно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2132045943] = {
        ["english"] = { [1] = "Look for Innkeeper Grishka in the Valley of Strength.  Her inn is on the east side, north of the main city gates." },
        ["text"] = "Шукай господиню заїзду Ґрішку в Долині Сили.  Її заїзд на східному боці, північніше головної міської брами.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [207209041] = {
        ["english"] = { [1] = "Oh, thank you!  The pit of blackness inside of me has been lifted!  I can see again... and I see the face of my savior!" },
        ["text"] = "О, дякую!  Чорна безодня всередині мене зникла!  Я знову бачу... і бачу обличчя свого спасителя!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4056252680] = {
        ["english"] = { [1] = "Jocaste was the greatest of Hunters of her time.  These days you can find her over in the Cenarion Enclave where she teaches those who are just starting down the Hunter's path." },
        ["text"] = "Джокаста була найвеличнішою мисливицею свого часу.  Тепер її можна знайти в Кенарійському анклаві, де вона навчає тих, хто лише ступає на шлях мисливця.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [789924165] = {
        ["english"] = { [1] = "Mind you, this part I learned later because I wasn't out there at the time.$B$BWhen they ratcheted up the suction on the pump, up came pieces of a robot that looked like a gnome! Of course the fools worked night and day to put it back together without telling us.$B$BThis is when we lost communication with the pumping station." },
        ["text"] = "Зауваж, цю частину я дізнався вже пізніше, бо тоді мене там не було.$B$BКоли вони посилили всмоктування насоса, нагору полізли частини робота, схожого на гнома! Звісно, ті дурні день і ніч складали його докупи, нічого нам не сказавши.$B$BСаме тоді ми втратили зв’язок із насосною станцією.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [119668508] = {
        ["english"] = { [1] = "Send me on my way... I beg you..." },
        ["text"] = "Відпусти мене... благаю...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1190610084] = {
        ["english"] = { [1] = "Seikwa can take care of your animal friends when you have the need.  Seek her out in front of the inn." },
        ["text"] = "Сейква подбає про твоїх тварин, коли буде потрібно.  Шукай її перед заїздом.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1718279277] = {
        ["english"] = { [1] = "Our punishment is also our blessing." },
        ["text"] = "Наше покарання — водночас наше благословення.",
        ["npcs"] = { [1] = 9040 },
        ["roles"] = { ["greeting"] = true },
    },
    [3587055888] = {
        ["english"] = { [1] = "Seen any strange things in the desert lately?" },
        ["text"] = "Останнім часом бачив у пустелі щось дивне?",
        ["npcs"] = { [1] = 7564 },
        ["roles"] = { ["reply"] = true },
    },
    [343768064] = {
        ["english"] = { [1] = "Lok'tar $c!  We have need of your services in Alterac Valley.  Shall I add you to the lists?" },
        ["text"] = "Лок’тар, $c!  Нам потрібні твої послуги в Альтерацькій долині.  Додати тебе до списків?",
        ["npcs"] = { [1] = 14942 },
        ["roles"] = { ["greeting"] = true },
    },
    [4057825038] = {
        ["english"] = { [1] = "Let me break down a little math for you: \"goblin\" plus \"engineering\" equals KNOW HOW, baby.  Anyone who tells you otherwise simply doesn't know how to add." },
        ["text"] = "Ось тобі проста математика: «гоблін» плюс «інженерія» дорівнює ТЯМОВИТІСТЬ, крихітко.  Хто каже інакше, той просто не вміє рахувати.",
        ["npcs"] = { [1] = 8126 },
        ["roles"] = { ["greeting"] = true },
    },
    [2794289095] = {
        ["english"] = { [1] = "Oh the drama and fuss the young Master exerted. You would think the fate of the world rested squarely on his shoulders. Only mortals could have such a skewed perspective on our world.$B$BAlas, he left me with his meager magical secrets... Librams or some such nonsense. I have no use for these paultry magics but perhaps you might be interested in their enchantments." },
        ["text"] = "О, скільки драм і метушні здіймав молодий Майстер. Можна було подумати, що доля світу лежить просто на його плечах. Лише смертні можуть так викривлено дивитися на наш світ.$B$BТа він залишив мені свої мізерні магічні секрети... лібрaми чи якусь подібну нісенітницю. Мені ці жалюгідні чари ні до чого, але, можливо, тебе зацікавлять їхні зачарування.",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [3511911442] = {
        ["english"] = { [1] = "Seek out Shandrina in Silverwind Refuge.  She can sell you the \"Expert Cookbook\"." },
        ["text"] = "Шукай Шандріну в Прихистку Срібного Вітру.  Вона продасть тобі «Кулінарну книгу експерта».",
        ["npcs"] = { [1] = 1355, [2] = 1430, [3] = 1699, [4] = 3087, [5] = 4210, [6] = 5159, [7] = 6286 },
        ["roles"] = { ["greeting"] = true },
    },
    [4067865786] = {
        ["english"] = { [1] = "My colleagues and I are gathering the deadliest substances we know and testing their effects on our enemies. Once I have everything I need, I shall brew such plagues as this world has never seen." },
        ["text"] = "Ми з колегами збираємо найсмертоносніші речовини, які знаємо, й випробовуємо їх на ворогах. Коли матиму все необхідне, я зварю такі пошесті, яких цей світ іще не бачив.",
        ["npcs"] = { [1] = 4611 },
        ["roles"] = { ["greeting"] = true },
    },
    [4281311137] = {
        ["english"] = { [1] = "Oh, ye want to learn to pick some daisies do ye?  Ha!  I'm just teasing ye $gladdie : lass;.  \010\010A fine profession it is, and Reyna Stonebranch can show ye how it's done.  She works at the Ironforge Physician on the southern side of The Great Forge." },
        ["text"] = "О, хочеш навчитися зривати ромашки, еге?  Ха!  Я лише дражнюся, $gхлопче : дівчино;.  \010\010Це чудове ремесло, і Рейна Кам’яна Гілка покаже, як усе робиться.  Вона працює в «Залізогартському лікарі» на південному боці Великого Горна.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2734366874] = {
        ["english"] = { [1] = "Orcs? Badlands? I'm invulnerable!" },
        ["text"] = "Орки? Безплідні краї? Я невразливий!",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["reply"] = true },
    },
    [2500330050] = {
        ["english"] = { [1] = "Krang Stonehoof stands astride his training circle at the southeast corner of the village." },
        ["text"] = "Кранґ Кам’яне Копито стоїть біля свого тренувального кола в південно-східному кутку селища.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1860479395] = {
        ["english"] = { [1] = "Security override permitted. Secondary defensive systems activated.$B$BBackup deactivation for secondary systems can be accessed via individual generators located on the concourse." },
        ["text"] = "Обхід системи безпеки дозволено. Вторинні оборонні системи активовано.$B$BРезервне вимкнення вторинних систем доступне через окремі генератори, розташовані на галереї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2096536607] = {
        ["english"] = { [1] = "Normal dogs won't come anywhere near me nowadays.  I was devastated when I found out... I used to love the beasts.$B$BPlaguehounds make for a fine substitute, however.  They're not quite as... easy on the eyes.  But then again, neither am I!" },
        ["text"] = "Звичайні собаки тепер і близько до мене не підходять.  Коли я це зрозумів, був спустошений... колись я дуже любив цих звірів.$B$BЗате чумні гончаки — непогана заміна.  Вони не такі вже... приємні на вигляд.  Але, з іншого боку, я теж!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3726423592] = {
        ["english"] = { [1] = "Ribbit." },
        ["text"] = "Ква.",
        ["npcs"] = { [1] = 14866 },
        ["roles"] = { ["greeting"] = true },
    },
    [2317647829] = {
        ["english"] = { [1] = "Ready for another lesson? All right, then. First, relax. You gotta stay loose to stir a potion just right." },
        ["text"] = "Готовий до нового уроку? Гаразд. Спершу розслабся. Треба бути вільним у рухах, щоб правильно помішувати зілля.",
        ["npcs"] = { [1] = 3184 },
        ["roles"] = { ["greeting"] = true },
    },
    [2462482210] = {
        ["english"] = { [1] = "Season's greetings, and peace to you!" },
        ["text"] = "Веселих свят і миру тобі!",
        ["npcs"] = { [1] = 15760 },
        ["roles"] = { ["greeting"] = true },
    },
    [2037408852] = {
        ["english"] = { [1] = "Scholomance" },
        ["text"] = "Некроситет",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2462972856] = {
        ["english"] = { [1] = "Scarlet Monastery lies in the hills northeast of Tirisfal Glades." },
        ["text"] = "Багряний монастир розташований на пагорбах на північний схід від Тірісфальського перелісся.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1034743655] = {
        ["english"] = { [1] = "One has opened up on the Tradesman's Terrace.  If you take the path leading Southeast from the bank, it should be easy to find." },
        ["text"] = "Одне відкрилося на Торговій терасі.  Якщо підеш стежкою на південний схід від банку, знайдеш без проблем.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [392011968] = {
        ["english"] = { [1] = "Last I heard the Horde had accumulated $2021w of $2020w peacebloom, $2050w of $2051w firebloom and $2054w out of $2055w purple lotuses." },
        ["text"] = "Востаннє я чув, що Орда зібрала $2021w із $2020w мироцвіту, $2050w із $2051w вогнецвіту та $2054w із $2055w пурпурових лотосів.",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [2670482581] = {
        ["english"] = { [1] = "Plenty of good mining to be had in Durotar, or so I hear.  So good in fact that we have a Mining Trainer right here in Razor Hill.  You'll find Krunn next to the heated forge in the northwest corner of town." },
        ["text"] = "Кажуть, у Дуротарі чудове гірництво.  Настільки чудове, що в нас навіть є наставник гірництва просто тут, у Колючому Пагорбі.  Крунна знайдеш біля розпеченого горна в північно-західному кутку міста.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1197991727] = {
        ["english"] = { [1] = "My faith guides my actions, $r. I know that Ivus will come." },
        ["text"] = "Віра керує моїми вчинками, $r. Я знаю, що Івус прийде.",
        ["npcs"] = { [1] = 13442 },
        ["roles"] = { ["greeting"] = true },
    },
    [3695272833] = {
        ["english"] = { [1] = "May the Light bend to your will in all endeavors." },
        ["text"] = "Нехай Світло кориться твоїй волі в усіх справах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [303623749] = {
        ["english"] = { [1] = "Johaan say Gordo need a tailor to fix Gordo tummy." },
        ["text"] = "Джоґаан каже, Ґордо треба кравець, полагодити Ґордо животик.",
        ["npcs"] = { [1] = 10666 },
        ["roles"] = { ["greeting"] = true },
    },
    [990907537] = {
        ["english"] = { [1] = "Sayoc, da ugly orc here, teach you daggers. You want teaching in other places, you talk to Archibald in the War Quarter of Undercity, hokay?" },
        ["text"] = "Сайок, той гидкий орк тут, навчити тебе кинджалам. Хочеш вчитися в іншому місці — говори з Арчибальдом у Бойовому кварталі Підміста, гаразд?",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [741773898] = {
        ["english"] = { [1] = "Sayoc is the orc weapon master.  He is located in Orgrimmar's Valley of Honor.  He can train the use of bows, daggers, fist weapons, one and two-handed axes and thrown weapons.\010\010Hanashi, the troll weapon master in the Valley of Honor of Orgrimmar, can instruct in the use of bows, one and two-handed axes, staves and all thrown weapons.\010\010Ansekhwa, the tauren weapon master, is on Thunder Bluff's lower rise.  He teaches the use of one and two-handed maces, staves and guns.\010" },
        ["text"] = "Сайок — орк-майстер зброї.  Він у Долині Честі Орґріммара.  Навчає володінню луками, кинджалами, кулачною зброєю, одноручними й дворучними сокирами та метальною зброєю.\010\010Ганаші, троль-майстер зброї в Долині Честі Орґріммара, навчає володінню луками, одноручними й дворучними сокирами, посохами та всією метальною зброєю.\010\010Ансеква, таурен-майстер зброї, перебуває на нижньому виступі Громового Бескиду.  Він навчає володінню одноручними й дворучними булавами, посохами та рушницями.\010",
        ["npcs"] = { [1] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [3150073171] = {
        ["english"] = { [1] = "Let me see, let me see. I had those numbers here somewhere. Ah yes, here they are! To date, the Alliance has collected $2047w stranglekelp, out of $2048w needed. It also says here that we have $2053w of $2055w purple lotus and $2057w out of $2058w arthas' tears needed." },
        ["text"] = "Так, подивімося. Десь тут у мене були ці числа. Ага, ось вони! Наразі Альянс зібрав $2047w душника з потрібних $2048w. Тут також написано, що ми маємо $2053w із $2055w пурпурових лотосів і $2057w із потрібних $2058w сліз Артаса.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1862403490] = {
        ["english"] = { [1] = "Oy mon! I know you?$b$bAhh yeah, Prigmon not forget a face.$b$bYou... followin' me, mon? Cuz whatver it be, Prigmon never done it!" },
        ["text"] = "Ой, друже! Я тебе знаю?$b$bА-а, так, Пріґмон обличчя не забуває.$b$bТи... стежиш за мною, еге? Бо що б там не було — Пріґмон цього не робив!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3235179612] = {
        ["english"] = { [1] = "Makaru can be found day and night at Red Canyon Mining in the Valley of Honor, just off the lake." },
        ["text"] = "Макару можна знайти вдень і вночі в копальні Червоного каньйону в Долині Честі, неподалік озера.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [591980857] = {
        ["english"] = { [1] = "My apologies, Lady Prestor." },
        ["text"] = "Перепрошую, леді Престор.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3044406712] = {
        ["english"] = { [1] = "Sayoc and Hanashi, Orgrimmar's weapon masters, are true artisans of the thrown weapon. They train willing students in the Valley of Honor." },
        ["text"] = "Сайок і Ганаші, майстри зброї Орґріммара, — справжні митці метальної зброї. Вони навчають охочих у Долині Честі.",
        ["npcs"] = { [1] = 11869, [2] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [4061207038] = {
        ["english"] = { [1] = "Say, you wouldn't happen to have an extra set of reins..." },
        ["text"] = "Слухай, у тебе часом немає зайвого набору поводів...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1731087829] = {
        ["english"] = { [1] = "Say, you look familiar. Have we met?" },
        ["text"] = "Слухай, ти здаєшся знайомим. Ми зустрічалися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2891836265] = {
        ["english"] = { [1] = "Ragnaros will reign supreme!" },
        ["text"] = "Раґнарос пануватиме навіки!",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [2275710987] = {
        ["english"] = { [1] = "Our work in the Living Grove must not be endangered.  Our very lives hinge upon its continued health and growth." },
        ["text"] = "Не можна наражати на небезпеку нашу роботу в Живому Гаю.  Від його здоров’я й зростання залежать наші життя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [557811640] = {
        ["english"] = { [1] = "Johnson?  I think he's around here somewhere..." },
        ["text"] = "Джонсон?  Здається, він десь тут...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3261954599] = {
        ["english"] = { [1] = "My knowledge is limited, though I am still learning. It is time for you to move on, traveler. Find Josef Gregorian in Undercity and tell him you are ready." },
        ["text"] = "Мої знання обмежені, хоча я ще навчаюся. Тобі час рухатися далі, мандрівнику. Знайди Йозефа Ґреґоріана в Підмісті й скажи, що ти готовий.",
        ["npcs"] = { [1] = 3004 },
        ["roles"] = { ["greeting"] = true },
    },
    [433363692] = {
        ["english"] = { [1] = "Over the course of 8,000 years, only a handful of these blades were created - each blade unique in both power and appearance. The blades of Quel'Serrar would take on the characteristics of their creator." },
        ["text"] = "За 8000 років було створено лише кілька таких клинків — кожен унікальний і за силою, і за виглядом. Клинки Квел’Серрара набували рис свого творця.",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [360406402] = {
        ["english"] = { [1] = "Please, leave this place, $N. You know nothing of what troubles us..." },
        ["text"] = "Будь ласка, покинь це місце, $N. Ти нічого не знаєш про наші біди...",
        ["npcs"] = { [1] = 10304 },
        ["roles"] = { ["greeting"] = true },
    },
    [1363268997] = {
        ["english"] = { [1] = "Say, you happen to see that arch in the lake to the west?  I wonder where that goes?  I should go divin' over there." },
        ["text"] = "Слухай, ти бачив ту арку в озері на заході?  Цікаво, куди вона веде?  Треба б там пірнути.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [440280345] = {
        ["english"] = { [1] = "Say, I sense a measure of disbelief in your voice - but yes, that's how it happened." },
        ["text"] = "Чую у твоєму голосі недовіру — але так, саме так усе й сталося.",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["greeting"] = true },
    },
    [2998789081] = {
        ["english"] = { [1] = "Mortals, I am indebted to you for freeing me from the terrible corruption that besets this place. Though I have not yet recovered fully, I can help you battle Yogg-Saron.$B$BI can grant you and your friends the Speed of Invention, increasing your damage and movement speed. In addition, I can destabilize the matrices of certain Saronite based life-forms, reducing their attack and casting speeds." },
        ["text"] = "Смертні, я у вас у боргу за те, що визволили мене від жахливої скверни, яка опанувала це місце. Я ще не відновився повністю, але можу допомогти вам у битві з Йоґґ-Сароном.$B$BЯ можу дарувати вам і вашим друзям Швидкість Винахідництва, збільшуючи вашу шкоду та швидкість руху. Крім того, я можу дестабілізувати матриці деяких форм життя на основі сароніту, зменшуючи їхню швидкість атаки й вимовляння заклять.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3334844378] = {
        ["english"] = { [1] = "Morganus the stable master can be found out in front of the stables strangely enough." },
        ["text"] = "Доглядач стайні Морганус, як не дивно, стоїть просто перед стайнями.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1210255473] = {
        ["english"] = { [1] = "None will question your actions, $c.  You did what had to be done." },
        ["text"] = "Ніхто не поставить під сумнів твої дії, $c.  Ти зробив те, що мусив.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2097153508] = {
        ["english"] = { [1] = "Karazhan wasn't always quite as... ominous.  The darkening of Karazhan only came with Medivh's death.  Or what we believe was Medivh's death." },
        ["text"] = "Каражан не завжди був таким... зловісним.  Темрява оповила Каражан лише після смерті Медіва.  Або того, що ми вважаємо смертю Медіва.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [67215632] = {
        ["english"] = { [1] = "Nurse Neela greets all of her future customers as they enter the Gallows' End Tavern at the southeast end of town." },
        ["text"] = "Сестра Ніла вітає всіх своїх майбутніх клієнтів при вході до таверни «Кінець Шибениці» на південно-східній околиці міста.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1851894394] = {
        ["english"] = { [1] = "Salutations.  My function is to offer access to and, when permissible, insight into information regarding the Creators' synthesis of the Earthen on the world designated as Azeroth.  I am ready to share this information with you now at your leisure." },
        ["text"] = "Вітаю.  Моя функція — надавати доступ і, коли дозволено, пояснення щодо інформації про створення Творцями земельників у світі, позначеному як Азерот.  Я готовий поділитися цією інформацією, коли тобі буде зручно.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [1256372317] = {
        ["english"] = { [1] = "Keep your eyes open, $c. Even Durotar is not safe from our enemies." },
        ["text"] = "Не втрачай пильності, $c. Навіть Дуротар не захищений від наших ворогів.",
        ["npcs"] = { [1] = 3139 },
        ["roles"] = { ["greeting"] = true },
    },
    [2788292988] = {
        ["english"] = { [1] = "Salutations.  I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound." },
        ["text"] = "Вітаю.  Я — вартовий входу.  Якщо Плити Ульдуму ще не інтегровані у твій набір дисків, я не дозволю ввійти до комплексу Ульдум.",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["greeting"] = true },
    },
    [2618845662] = {
        ["english"] = { [1] = "Lee's caught some pretty odd things up at Crystal Lake.  He told me a story about this weird mask he fished up some months ago.  If you ask me, I think he just had one too many at the Lion's Pride that night." },
        ["text"] = "Лі виловлював у Кришталевому озері доволі дивні речі.  Якось він розповідав про дивну маску, яку витягнув кілька місяців тому.  Як на мене, того вечора він просто перебрав у «Гордості Лева».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2531396554] = {
        ["english"] = { [1] = "Rocket-Chief Fuselage, commander of B.O.O.M - the Braintrust of Orbital Operations and Mechanics - at your service.$B$BAre all systems go?!  It looks like the X-52 Nether-Rocket still needs a lot of work!$B$BCome on people... we're T-minus NEVER here!" },
        ["text"] = "Ракетний шеф Фюзеляж, командир Б.У.М. — Бюро Ультраорбітальної Механіки — до ваших послуг.$B$BУсі системи готові?!  Схоже, X-52 «Ракета Порожнечі» ще потребує купи роботи!$B$BВорушіться, люди... у нас тут відлік до НІКОЛИ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2414712863] = {
        ["english"] = { [1] = "S.T.O.U.T. is more than just a target for throwing steins, it's a valuable training asset.  If you can hit S.T.O.U.T. you can probably hit anything!$b$bJust try not to hit me." },
        ["text"] = "С.Т.А.У.Т. — це не просто мішень для кидання кухлів, а цінний тренувальний засіб.  Якщо влучиш у С.Т.А.У.Т., то, мабуть, влучиш у будь-що!$b$bТільки постарайся не влучити в мене.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [459793821] = {
        ["english"] = { [1] = "My sisters and I welcome you, $r." },
        ["text"] = "Ми з сестрами вітаємо тебе, $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1666740589] = {
        ["english"] = { [1] = "My husband's been missing for days.  We went on this pilgrimage together; we were supposed to finish it together.$B$BAll this worry has gotten me tapping into mana crystals more often than I really should." },
        ["text"] = "Мій чоловік зник кілька днів тому.  Ми разом вирушили в це паломництво й мали разом його завершити.$B$BВід хвилювання я звертаюся до кристалів мани значно частіше, ніж слід.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4202082863] = {
        ["english"] = { [1] = "Rupert Boch is his name.  I hear that he's upstairs in one of the rooms at the Gallows' End Tavern on the southeast end of town." },
        ["text"] = "Його звати Руперт Бок.  Чув, він нагорі в одній із кімнат таверни «Кінець Шибениці» на південно-східній околиці міста.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1631233284] = {
        ["english"] = { [1] = "Once the jewel of northern Lordaeron, the city of Stratholme is where Prince Arthas turned against his mentor, Uther Lightbringer, and slaughtered hundreds of his own subjects who were believed to have contracted the plague of undeath. Arthas' surrender to the Lich King soon followed. The broken city is now inhabited by the undead Scourge - led by the powerful lich, Kel'Thuzad, and a contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan. The two sides are locked in constant, violent combat. \010" },
        ["text"] = "Колись перлина північного Лордерону, Стратгольм став місцем, де принц Артас повстав проти свого наставника Утера Світлоносця й вирізав сотні власних підданих, яких вважали зараженими чумою невмертя. Невдовзі Артас підкорився Королю-лічу. Тепер зруйноване місто населяє невмерлий Батіг на чолі з могутнім лічем Кел’Тузадом, а також загін Багряного Походу під проводом Великого хрестоносця Датроґана. Обидві сторони ведуть безперервну жорстоку війну. ",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1366815406] = {
        ["english"] = { [1] = "Living out here in the desert is rough! I get so thirsty standing outside in this heat." },
        ["text"] = "Жити тут, у пустелі, нелегко! Я страшенно хочу пити, коли цілими днями стою на такій спеці.",
        ["npcs"] = { [1] = 7564 },
        ["roles"] = { ["greeting"] = true },
    },
    [3589244033] = {
        ["english"] = { [1] = "Looks like you're too late, $c. We have all of the roast raptor that we need; killed, cooked and salted. Anyway, it looks like some of the others around here could use some help. You should go check with them. I'm going to see if they'll let me go home now." },
        ["text"] = "Схоже, ти запізнився, $c. Ми вже маємо весь потрібний смажений раптор: убитий, приготований і засолений. Та іншим тут іще може знадобитися допомога. Перевір у них. А я піду дізнаюся, чи відпустять мене нарешті додому.",
        ["npcs"] = { [1] = 15456 },
        ["roles"] = { ["greeting"] = true },
    },
    [2591406765] = {
        ["english"] = { [1] = "Please, feel free to speak to me anytime, $N. You have served Magatha well. I am sure she will call upon you in the future." },
        ["text"] = "Звертайся до мене будь-коли, $N. Ти добре послужив Маґаті. Я певен, вона ще покличе тебе в майбутньому.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4239338430] = {
        ["english"] = { [1] = "Rumors exist of a single, legendary blade of Quel'Serrar crafted for an unknown entity by the combined might of the five Aspects. Before the abominations of Nefarian and Deathwing were thrust into our world, such meetings of the Aspect were represented by the term 'Prismatic.' I could only assume that the Prismatic Blade of Quel'Serrar was a most glorious creation." },
        ["text"] = "Ходять чутки про єдиний легендарний клинок Квел’Серрара, створений для невідомої сутності спільною силою п’ятьох Аспектів. До того, як потвори Нефаріан і Смертекрил увірвалися в наш світ, такі зібрання Аспектів називали «Призматичними». Можу лише припустити, що Призматичний клинок Квел’Серрара був найславетнішим творінням.",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [3594501879] = {
        ["english"] = { [1] = "Ruby Drakes excel at mitigating damage and protecting their allies.$B$BUsing Searing Wrath, they can breathe streams of liquid fire that jump from target to target, dealing increasing damage with each jump.$B$BWhenever a Ruby drake is damaged by an enemy attack, it gains an Evasive charge.  These charges can be used to perform a series of evasive maneuvers, allowing the drake to dodge incoming attacks and spells for a time." },
        ["text"] = "Рубінові дракони чудово зменшують отримувану шкоду й захищають союзників.$B$BЗа допомогою «Пекучого гніву» вони видихають потоки рідкого вогню, що перескакують від цілі до цілі й з кожним стрибком завдають більше шкоди.$B$BЩоразу, коли рубіновий дракон отримує шкоду від ворожої атаки, він накопичує заряд Ухилення.  Ці заряди можна витрачати на серію маневрів, які певний час дозволяють ухилятися від атак і заклять.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1601482404] = {
        ["english"] = { [1] = "Keeping your ram in a canter or gallop for too long will exhaust him. If you want your ram to recover a bit, let him walk or trot. If there are apple bushels around, take him there to recover." },
        ["text"] = "Якщо занадто довго тримати барана на легкому чи швидкому галопі, він виснажиться. Щоб дати йому трохи відпочити, переведи його на крок або рись. Якщо поблизу є кошики з яблуками, підведи його до них, щоб він відновив сили.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4145804482] = {
        ["english"] = { [1] = "Rough times, huh, $N? No matter where you turn someone needs help, and my wife and I are no exception." },
        ["text"] = "Тяжкі часи, еге, $N? Куди не глянь — усім потрібна допомога, і ми з дружиною не виняток.",
        ["npcs"] = { [1] = 233 },
        ["roles"] = { ["greeting"] = true },
    },
    [2964628093] = {
        ["english"] = { [1] = "Miranda, could you please tell me the insignia cost of items that you are offering for adventurers with other reputations?" },
        ["text"] = "Мірандо, скажіть, будь ласка, скільки знаків коштують предмети, які ви пропонуєте шукачам пригод з іншою репутацією?",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [3261525990] = {
        ["english"] = { [1] = "Only a fool would dare disturb me in my lair." },
        ["text"] = "Лише дурень наважиться потривожити мене в моєму лігві.",
        ["npcs"] = { [1] = 9459 },
        ["roles"] = { ["greeting"] = true },
    },
    [984015976] = {
        ["english"] = { [1] = "Nope, nobody who can teach ye herbalism out here.  I think ye'll have better luck in Ironforge though." },
        ["text"] = "Ні, тут ніхто не навчить тебе травництва.  Думаю, у Залізогарті пощастить більше.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2279806088] = {
        ["english"] = { [1] = "Listen up, flapjack, we're in for the fight of our lives with the bugs in Ahn'Qiraj and we need to get prepared for it. I'm collecting iron bars here.  Currently, the Alliance only has $2002w iron bars, but we're projected to need a total of $2003w for the war effort." },
        ["text"] = "Слухай сюди, оладку, на нас чекає бій не на життя, а на смерть із жуками в Ан’Кіражі, тож треба готуватися. Я збираю залізні зливки.  Зараз Альянс має лише $2002w залізних зливків, а для воєнних потреб нам знадобиться загалом $2003w.",
        ["npcs"] = { [1] = 15431 },
        ["roles"] = { ["greeting"] = true },
    },
    [2037691656] = {
        ["english"] = { [1] = "Light be with you, $c." },
        ["text"] = "Нехай Світло буде з тобою, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [301599277] = {
        ["english"] = { [1] = "Omen sleeps in the depths of Lake Elune'ara, but may be summoned at the southeast banks near the Stormrage Barrow Dens.  There, you will find special cluster launchers...$B$BUse your rockets in the launchers and Omen's minions will come.  Fire more rockets, nearly three dozen, or fire Elune's Candles at his minions, and soon he will awaken." },
        ["text"] = "Омен спить у глибинах озера Елуне’ара, але його можна прикликати на південно-східному березі біля курганів Шаленства Бурі.  Там ти знайдеш спеціальні пускові установки для зв’язок ракет...$B$BВикористай у них свої ракети, і прийдуть прислужники Омена.  Запусти ще ракет — майже три десятки — або застосуй Свічки Елуни проти його прислужників, і незабаром він прокинеться.",
        ["npcs"] = { [1] = 15864 },
        ["roles"] = { ["greeting"] = true },
    },
    [3457454024] = {
        ["english"] = { [1] = "Ohhh, the pain is... overwhelming...." },
        ["text"] = "О-о-ох, біль... нестерпний....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3998491729] = {
        ["english"] = { [1] = "May the blessings of the night be yours, friend!  I am Illiyana Moonblaze, and I am the main supplier for the Silverwing Sentinels here in Ashenvale.  As you improve your standing with the Sentinels, I will make available to you a fine selection of goods that you can use inside Warsong Gulch.  Should you find yourself in need of item repair, I also provide those services." },
        ["text"] = "Нехай благословення ночі буде з тобою, друже!  Я Ілліяна Місячне Полум’я, головна постачальниця Срібнокрилих Вартових тут, у Ясенедолі.  Що вищою буде твоя репутація серед Вартових, то кращий вибір товарів для Ущелини Пісні Війни я тобі запропоную.  Якщо знадобиться полагодити спорядження, я також це роблю.",
        ["npcs"] = { [1] = 14753 },
        ["roles"] = { ["greeting"] = true },
    },
    [3030162796] = {
        ["english"] = { [1] = "One note stands out from the other various pieces of parchment that are tacked onto this wanted poster.  It's a call to slay the bonelashers of the Bone Wastes." },
        ["text"] = "Серед клаптів пергаменту, приколотих до цього оголошення про розшук, один запис особливо впадає в око.  Це заклик винищувати кісткохльостів Кістяної пустки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [292270099] = {
        ["english"] = { [1] = "Riplash will never return to its former glory, but these boat-riding scum will pay for their deeds - I swear it!" },
        ["text"] = "Риплеш уже ніколи не поверне колишньої слави, але ці покидьки на човнах заплатять за свої вчинки — клянуся!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2370946831] = {
        ["english"] = { [1] = "Right, the meeting.  Let's get down to it then.$B$BThe fact is that the lumber and livestock being gathered from the Ruuan Weald, which you're responsible for, has slowed to a trickle.$B$BWe need those resources, but you've allowed the druids of the Cenarion Expedition to get in the way!" },
        ["text"] = "Так, зустріч.  Перейдімо до справи.$B$BФакт у тому, що потік деревини й худоби з Рууанської хащі, за який відповідаєш ти, майже вичерпався.$B$BНам потрібні ці ресурси, але ти дозволив друїдам Кенарійської експедиції стати на заваді!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [699855350] = {
        ["english"] = { [1] = "Rifles, dynamite, bombs, exploding sheep... what's not to love?  To learn how to make these and many other exciting tools of the trade head to the Undercity, under the Ruins of Lordaeron to the south of Brill.  Take the elevators down at the back of the ruins.  Once you arrive speak to one of the Undercity Guardians about where the trainer is exactly." },
        ["text"] = "Рушниці, динаміт, бомби, вибухові вівці... що тут може не подобатися?  Щоб навчитися створювати це та багато інших захопливих інструментів ремесла, вирушай до Підміста під руїнами Лордерону на південь від Брілля.  Спустися ліфтами в задній частині руїн.  Прибувши, спитай одного з вартових Підміста, де саме знайти наставника.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2687771336] = {
        ["english"] = { [1] = "Matron!  Is that bad man going to eat us?" },
        ["text"] = "Матроно!  Той поганий чоловік нас з’їсть?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1042678899] = {
        ["english"] = { [1] = "Me, train you? Come on--we both know I can't. It's this teaching, you see. My own skills suffer. You want training, go to Doctor Herbert Halsey, a Forsaken in the Apothecarium of the Undercity." },
        ["text"] = "Я — тренувати тебе? Та годі, ми обоє знаємо, що я не можу. Це все через викладання — мої власні навички страждають. Хочеш навчання — іди до доктора Герберта Голсі, Відреченого з Аптекаріуму Підміста.",
        ["npcs"] = { [1] = 2391 },
        ["roles"] = { ["greeting"] = true },
    },
    [1001378344] = {
        ["english"] = { [1] = "Return to your people and tell them to send one of your shaman to me." },
        ["text"] = "Повернися до свого народу й скажи їм прислати до мене одного з ваших шаманів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2598735557] = {
        ["english"] = { [1] = "Krumn is the bull you are looking for. He can be found on the lower rise at Thunder Bluff Civic Information." },
        ["text"] = "Крумн — це бик, якого ти шукаєш. Його можна знайти на нижньому виступі в Довідковій службі Громового Бескиду.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2320428408] = {
        ["english"] = { [1] = "Practicing!  Soon I'll be good enough to join the other summoners and take my turn inside the Shadow Labyrinth at Auchindoun.$B$BI hope that I'll get the chance to summon something big!  Maybe something as big as Murmur, though I wouldn't lose control of him!" },
        ["text"] = "Тренуюся!  Скоро стану достатньо вправним, щоб приєднатися до інших заклиначів і чергувати в Тіньовому лабіринті Акіндуна.$B$BСподіваюся, мені дадуть прикликати щось велике!  Може, навіть таке велике, як Мурмур, хоча я точно не втрачу над ним контроль!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3460477000] = {
        ["english"] = { [1] = "Season's savings to you and yours!" },
        ["text"] = "Святкових знижок тобі й твоїм близьким!",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [2650596545] = {
        ["english"] = { [1] = "Listen, mon!$b$bI tell ya all I be knowin', but first ya gotta be savin' me from these savages and their killer bears.$b$bDeal?" },
        ["text"] = "Слухай, друже!$b$bЯ розповім усе, що знаю, але спершу врятуй мене від цих дикунів та їхніх ведмедів-убивць.$b$bДомовились?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1774765326] = {
        ["english"] = { [1] = "Please teach me how to make a Gordok Ogre Suit!" },
        ["text"] = "Навчи мене, будь ласка, робити костюм огра Ґордока!",
        ["npcs"] = { [1] = 14338 },
        ["roles"] = { ["reply"] = true },
    },
    [1213460478] = {
        ["english"] = { [1] = "Revered" },
        ["text"] = "Шанований",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [388543130] = {
        ["english"] = { [1] = "Return to the draenei and tell them to send me one of their shaman." },
        ["text"] = "Повернися до дренеїв і скажи їм прислати до мене одного зі своїх шаманів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3355102890] = {
        ["english"] = { [1] = "Sorry, but my services are only of use to hunters." },
        ["text"] = "Вибач, але мої послуги корисні лише мисливцям.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1973680519] = {
        ["english"] = { [1] = "Many are the paths of the Earth Mother.  Wherever you decide to travel, may she watch over you." },
        ["text"] = "Численні шляхи Матері-Землі.  Куди б ти не вирушив, нехай вона тебе оберігає.",
        ["npcs"] = { [1] = 10378 },
        ["roles"] = { ["greeting"] = true },
    },
    [2030410490] = {
        ["english"] = { [1] = "Rest your weary feet, we have all the time in the world..." },
        ["text"] = "Відпочинь, ноги натруджені. У нас попереду ціла вічність...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [28114999] = {
        ["english"] = { [1] = "Rest your weary bones for a spell." },
        ["text"] = "Дай своїм втомленим кісткам трохи відпочити.",
        ["npcs"] = { [1] = 2388, [2] = 5688, [3] = 6739, [4] = 6741 },
        ["roles"] = { ["greeting"] = true },
    },
    [1731209062] = {
        ["english"] = { [1] = "Some call me... Impsy?" },
        ["text"] = "Дехто називає мене... Імпсі?",
        ["npcs"] = { [1] = 14470 },
        ["roles"] = { ["greeting"] = true },
    },
    [2036335181] = {
        ["english"] = { [1] = "Lady Jaina, this may sound like an odd request... but I have a young ward who is quite shy.  You are a hero to him, and he asked me to get your autograph." },
        ["text"] = "Леді Джайно, це може здатися дивним проханням... але я опікуюся одним дуже сором’язливим хлопчиком.  Ви для нього герой, і він попросив мене взяти ваш автограф.",
        ["npcs"] = { [1] = 4968 },
        ["roles"] = { ["reply"] = true },
    },
    [2270993395] = {
        ["english"] = { [1] = "Rend, son of Blackhand: Impotent chieftain of the Blackrock clan. A more stubborn bastard does not exist.$B$BAt the end of the second War, Rend and his brother, Maim, fled to find sanctuary within the mountainous stronghold of Blackrock Spire. It was there that Rend declared himself Warchief of the weakened Blackrock clan." },
        ["text"] = "Ренд, син Чорнорука: безсилий вождь клану Чорного Каменю. Упертішого покидька не знайти.$B$BНаприкінці Другої війни Ренд і його брат Майм втекли шукати притулку в гірській твердині Чорнокамінного Шпиля. Саме там Ренд проголосив себе Вождем ослабленого клану Чорного Каменю.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [2574358222] = {
        ["english"] = { [1] = "Rayne, where should I look for savage fronds?" },
        ["text"] = "Рейн, де мені шукати дикі вайї?",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["reply"] = true },
    },
    [1484343046] = {
        ["english"] = { [1] = "Renataki, of the Thousand Blades.$B$BPain is his lifeblood.  Fear, his ally.  May he one day return and bring joyous bloodshed with him.  $B$BRenataki now dwells far from here.  One day, he may return..." },
        ["text"] = "Ренатакі Тисячі Клинків.$B$BБіль — його життєва кров.  Страх — його союзник.  Нехай одного дня він повернеться й принесе з собою радісне кровопролиття.  $B$BТепер Ренатакі перебуває далеко звідси.  Одного дня він може повернутися...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1111214802] = {
        ["english"] = { [1] = "Kah Mistrunner at Mountaintop Bait & Tackle on the high rise will show you the way to find inner peace and serenity while fishing for your next meal." },
        ["text"] = "Ка Містреннер у крамниці «Гірська наживка та снасті» на верхньому виступі покаже тобі шлях до внутрішнього спокою й безтурботності, поки ти ловитимеш собі наступню вечерю.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [415484812] = {
        ["english"] = { [1] = "Of course there's no danger in everything catching flames and exploding like a huge helium bomb. This baby will get you to Undercity faster and safer than any boat, and the view is truly breathtaking. Speaking of breath, smoking is not allowed while on board the zeppelin, and fire spells are banned from being cast during the trip." },
        ["text"] = "Звісно, жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить тебе до Підміста швидше й безпечніше за будь-який корабель, а краєвид просто перехоплює подих. До речі про подих: на борту дирижабля не можна курити, а під час польоту заборонено застосовувати вогняні закляття.",
        ["npcs"] = { [1] = 9564, [2] = 12137 },
        ["roles"] = { ["greeting"] = true },
    },
    [3312683183] = {
        ["english"] = { [1] = "Mr. Floppy and I went for a walk, but then we got lost and I was really scared, cause there were these wolves, you know, and they chased us, but then I saw this tower and Mr. Floppy and I hid here and the wolves finally went away after a while and it was terrible and now we don't know how to get back home." },
        ["text"] = "Ми з містером Флоппі пішли гуляти, а потім заблукали, і мені було дуже страшно, бо там були вовки, розумієш, і вони гналися за нами, але тоді я побачив цю вежу, і ми з містером Флоппі тут сховалися, і вовки зрештою пішли, а це було жахливо, і тепер ми не знаємо, як повернутися додому.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3031227164] = {
        ["english"] = { [1] = "Now where was I?  I yeah...  So I said to her, \"But I need you!  I need you!\"... and she just laughed and slithered away!  It's the honest truth, $N.  Naga can be so cruel!" },
        ["text"] = "На чому я зупинився?  Ага...  Отже, я сказав їй: «Але ти мені потрібна! Потрібна!»... а вона лише засміялася й поповзла геть!  Чиста правда, $N.  Наґи бувають такими жорстокими!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4281940903] = {
        ["english"] = { [1] = "Silas, why is most everything at the fair free?  How do you make a profit?" },
        ["text"] = "Сайласе, чому майже все на ярмарку безкоштовне? Як ви заробляєте?",
        ["npcs"] = { [1] = 14823 },
        ["roles"] = { ["reply"] = true },
    },
    [3853434880] = {
        ["english"] = { [1] = "Recently, the Dark Irons have been seen on the surface world with greater regularity. Fortresses have been built in the Badlands. Massive exploratory forces have been sent into the depths of Uldaman in search of ancient lore. They have even invaded our own homeland, striking at our dam near the loch." },
        ["text"] = "Останнім часом дворфів Темного Заліза дедалі частіше бачать на поверхні. У Безплідних краях вони збудували фортеці. Величезні дослідницькі загони відправили в глибини Ульдамана шукати стародавні знання. Вони навіть вторглися в наші землі й ударили по греблі біля озера.",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["greeting"] = true },
    },
    [997765192] = {
        ["english"] = { [1] = "Recently, a night elf druid named Naralex discovered a network of underground caverns within the heart of the Barrens. Believing he could use the caverns' springs to restore lushness to the Barrens, the druid began siphoning the energies of the fabled Emerald Dream. His vision somehow became a nightmare, however, and soon the Wailing Caverns changed into a den of vicious, deadly predators. It is said that Naralex still resides somewhere inside the labyrinth, trapped beyond the edges of the Emerald Dream. \010" },
        ["text"] = "Нещодавно друїд нічних ельфів на ім’я Наралекс відкрив мережу підземних печер у самому серці Степів. Вірячи, що джерела печер допоможуть повернути Степам пишну рослинність, друїд почав черпати енергію легендарного Смарагдового Сну. Та його видіння якимось чином перетворилося на кошмар, і невдовзі Плачучі печери стали лігвом лютих смертоносних хижаків. Кажуть, Наралекс досі перебуває десь у лабіринті, ув’язнений за межами Смарагдового Сну. ",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2424854224] = {
        ["english"] = { [1] = "Monty be me name an' rats be me game." },
        ["text"] = "Монті мене звати, а щури — моя справа.",
        ["npcs"] = { [1] = 12997 },
        ["roles"] = { ["greeting"] = true },
    },
    [4133712299] = {
        ["english"] = { [1] = "Of course." },
        ["text"] = "Звісно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2231046673] = {
        ["english"] = { [1] = "Reavij has all the subtlety of a kodo! What's funny is that he doesn't think he's being obvious. I see the way he stares at me when he thinks no one's looking.$B$BHe creeps me out. I really wish Shadow Hunter Denjai hadn't sent him with us. Setting up Swamprat Post was the perfect opportunity to get away from him." },
        ["text"] = "У Реавіджа тонкість як у кодо! Найсмішніше, що він думає, ніби ніхто нічого не помічає. Я бачу, як він витріщається на мене, коли думає, що ніхто не дивиться.$B$BВін мене лякає. Дуже шкода, що мисливець тіней Денджай послав його з нами. Заснування застави Болотного Щура було ідеальним шансом від нього втекти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3456394231] = {
        ["english"] = { [1] = "Please, please, please tell me you are here to get me out of these shackles.  There's got to be a key somewhere...$B$BAt the very least, maybe you can take out Guard Slip'kik.  I think I might be able to help you out!$B$BSee that broken trap over yonder?  The ogres are too stupid to figure out how to fix it.  Clearly, it needs a thorium widget and some frost oil.  If you fix it, I bet you could lure Slip'kik into it, and BLAMMO - trapped ogre guard!" },
        ["text"] = "Будь ласка, будь ласка, скажи, що ти прийшов звільнити мене від цих кайданів.  Десь мусить бути ключ...$B$BАбо хоча б прибери вартового Сліп’кіка.  Думаю, я зможу тобі допомогти!$B$BБачиш он ту зламану пастку?  Огри надто тупі, щоб зрозуміти, як її полагодити.  Очевидно, їй потрібна торієва деталь і трохи крижаної оливи.  Полагодиш — і, закладаюся, зможеш заманити туди Сліп’кіка, а тоді БАБАХ — огр-вартовий у пастці!",
        ["npcs"] = { [1] = 14338 },
        ["roles"] = { ["greeting"] = true },
    },
    [2018511467] = {
        ["english"] = { [1] = "Show me what you have for sale." },
        ["text"] = "Покажи, що продаєш.",
        ["npcs"] = { [1] = 4265 },
        ["roles"] = { ["reply"] = true },
    },
    [551578166] = {
        ["english"] = { [1] = "Razorfen Kraul can be found on the very southern tip of the Barrens on the west side of the road." },
        ["text"] = "Лабіринти Бритвоскалих розташовані на самому півдні Степів, на західному боці дороги.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2470543870] = {
        ["english"] = { [1] = "Razorfen Downs can be found on the very southern tip of the Barrens on the east side of the road." },
        ["text"] = "Кургани Бритвоскалих розташовані на самому півдні Степів, на східному боці дороги.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2931333258] = {
        ["english"] = { [1] = "Razorfen Downs" },
        ["text"] = "Кургани Бритвоскалих",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [1345221975] = {
        ["english"] = { [1] = "Perhaps there exists a way?" },
        ["text"] = "Може, існує якийсь спосіб?",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["reply"] = true },
    },
    [2143011595] = {
        ["english"] = { [1] = "Renataki, of the Thousand Blades.$B$BPain is his lifeblood.  Fear, his ally.  May he one day return and bring joyous bloodshed with him.$B$BRenataki now dwells near the edge of madness." },
        ["text"] = "Ренатакі Тисячі Клинків.$B$BБіль — його життєва кров.  Страх — його союзник.  Нехай одного дня він повернеться й принесе з собою радісне кровопролиття.$B$BТепер Ренатакі перебуває біля межі божевілля.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1235066360] = {
        ["english"] = { [1] = "Narain Soothfancy, at your service! Retired engineer and master soothsayer! I can tell your future before it even happens!" },
        ["text"] = "Нарайн Віщелюб до ваших послуг! Відставний інженер і майстер-віщун! Я можу передбачити твоє майбутнє ще до того, як воно станеться!",
        ["npcs"] = { [1] = 11811 },
        ["roles"] = { ["greeting"] = true },
    },
    [3656856204] = {
        ["english"] = { [1] = "Metal, as with all things, should be used in balance with nature.  Karn Stonehoof has a smithy setup near the pond on the lower rise.  Seek out his wisdom." },
        ["text"] = "Метал, як і все інше, слід використовувати в гармонії з природою.  Карн Кам’яне Копито має кузню біля ставка на нижньому виступі.  Шукай його мудрості.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [4122704348] = {
        ["english"] = { [1] = "Paladin? Have you been partaking of the Apothecary's concoctions or some such thing? I have heard a rumor that some elven contingent is visiting the Dark Lady within the Undercity. Perhaps one of them might know." },
        ["text"] = "Паладин? Ти часом не куштував аптекарських сумішей чи чогось такого? Я чув чутки, що якась делегація ельфів відвідала Темну Пані в Підмісті. Може, хтось із них знає.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3646980832] = {
        ["english"] = { [1] = "Ras Frostwhat? Who is that?" },
        ["text"] = "Рас Морозо-що? Хто це?",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [3412003901] = {
        ["english"] = { [1] = "Ranked arena matches start again in $6318d.$B$BWould-be champions are already busy honing their skills and acquiring the best gear they can. Are you going to be ready?" },
        ["text"] = "Рейтингові матчі на арені знову почнуться через $6318d.$B$BМайбутні чемпіони вже вдосконалюють навички й добувають найкраще спорядження. Ти будеш готовий?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3682476220] = {
        ["english"] = { [1] = "One day, Rejek be mighty warrior." },
        ["text"] = "Одного дня Реджек бути могутній воїн.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1856955631] = {
        ["english"] = { [1] = "Randal's a bit of a dandy, but he's dependable, which is more than I can say for a lot of the students I take on. Still, I guess I can't blame them for wanting a bit of adventure." },
        ["text"] = "Рендал трохи франт, але надійний — а це вже більше, ніж можу сказати про багатьох учнів. Хоча, мабуть, не варто їх звинувачувати за бажання трохи пригод.",
        ["npcs"] = { [1] = 5564 },
        ["roles"] = { ["greeting"] = true },
    },
    [3610001787] = {
        ["english"] = { [1] = "Lok'tar ogar! Victory or death - it is these words that bind me to the Horde. For they are the most sacred and fundamental of truths to any warrior of the Horde.$B$BI give my flesh and blood freely to the Warchief. I am the instrument of my Warchief's desire. I am a weapon of my Warchief's command.$B$BFrom this moment until the end of days I live and die - FOR THE HORDE!" },
        ["text"] = "Лок’тар оґар! Перемога або смерть — ці слова єднають мене з Ордою. Для кожного воїна Орди це найсвятіша й найосновніша істина.$B$BЯ добровільно віддаю свою плоть і кров Вождю. Я — знаряддя волі мого Вождя. Я — зброя його наказу.$B$BВід цієї миті й до кінця днів я житиму й помиратиму — ЗА ОРДУ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3281943079] = {
        ["english"] = { [1] = "Let me sleep just five more minutes, mon..." },
        ["text"] = "Дай мені поспати ще лише п’ять хвилин, друже...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2992109789] = {
        ["english"] = { [1] = "My son, Taelan, was only a child when I was found guilty of treason and banished from the Alliance to live a life in exile. I chose to remain here so that I could watch over him; to somehow insure that he would grow up an honorable man.$B$BAs I had hoped, he took my place as lord of Mardenholde; but in a cruel twist of fate, joined the ranks of the Scarlet Crusade. He is now their Highlord, $r." },
        ["text"] = "Мій син Таелан був лише дитиною, коли мене визнали винним у зраді й вигнали з Альянсу на життя у засланні. Я вирішив залишитися тут, щоб наглядати за ним і бодай якось подбати, аби він виріс чесною людиною.$B$BЯк я й сподівався, він посів моє місце як лорд Марденгольду; та жорстока іронія долі привела його до лав Багряного Походу. Тепер він їхній Верховний лорд, $r.",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["greeting"] = true },
    },
    [1775418039] = {
        ["english"] = { [1] = "King Magni expects us to win the tournament and make him proud. We will not fail." },
        ["text"] = "Король Маґні чекає, що ми переможемо в турнірі й зробимо його гордим. Ми не підведемо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [255567400] = {
        ["english"] = { [1] = "Mystical goods and commodities is my business, stranger." },
        ["text"] = "Моя справа — містичні товари й усілякі рідкісні речі, незнайомцю.",
        ["npcs"] = { [1] = 14739 },
        ["roles"] = { ["greeting"] = true },
    },
    [3979759004] = {
        ["english"] = { [1] = "Leave me be, fool!" },
        ["text"] = "Дай мені спокій, дурню!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1648758132] = {
        ["english"] = { [1] = "Rand Rhobart is fairly good at skinning felbats and the like.  You can find him at a camp along the road to the southeast of Brill.  Take the road southeast out of town and then head east at the intersection." },
        ["text"] = "Ренд Робарт непогано знімає шкури зі сквернокрилів та подібних істот.  Знайдеш його в таборі біля дороги на південний схід від Брілля.  Вийди з міста на південний схід, а на перехресті поверни на схід.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [404427202] = {
        ["english"] = { [1] = "Lady stitch us up and bandage when we get hit.  You find her in inner ring of Rogues' Quarter." },
        ["text"] = "Пані нас латає й бинтує, коли нас ранять.  Знайдеш її на внутрішньому кільці Кварталу розбійників.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3352445972] = {
        ["english"] = { [1] = "Ram racing is easier than it seems, but it takes skill to master. Just use the reins, eat apples if you can and avoid exhausting your ram.$B$B" },
        ["text"] = "Перегони на баранах простіші, ніж здаються, але щоб стати майстром, потрібна вправність. Просто користуйся поводами, їж яблука, якщо можеш, і не виснажуй барана.$B$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1765076538] = {
        ["english"] = { [1] = "Keep your voice down, $c. We wouldn't want them to hear us." },
        ["text"] = "Говори тихіше, $c. Не хочемо ж, щоб вони нас почули.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4069155910] = {
        ["english"] = { [1] = "Leave at once, stranger!  I have no business with you." },
        ["text"] = "Негайно йди звідси, незнайомцю!  Мені немає до тебе діла.",
        ["npcs"] = { [1] = 15194 },
        ["roles"] = { ["greeting"] = true },
    },
    [1535948524] = {
        ["english"] = { [1] = "Let the event begin!" },
        ["text"] = "Нехай подія почнеться!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4088541762] = {
        ["english"] = { [1] = "No, no, please continue... it's just that the air up here is so, um, smoky." },
        ["text"] = "Ні-ні, продовжуй, будь ласка... просто повітря тут угорі таке, е-е, задимлене.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [3548078587] = {
        ["english"] = { [1] = "Orgrim's Hammer is ready to strike in Icecrown.  You will find no finer vessel." },
        ["text"] = "«Молот Орґріма» готовий завдати удару в Крижаній Короні.  Кращого корабля не знайдеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1257394379] = {
        ["english"] = { [1] = "So what happened?" },
        ["text"] = "І що сталося?",
        ["npcs"] = { [1] = 9021, [2] = 11216, [3] = 14348 },
        ["roles"] = { ["reply"] = true },
    },
    [863191560] = {
        ["english"] = { [1] = "Master Nesingwary has a big hunt ahead of him.  I find helping him prepare for a day in the jungle is much more relaxing than helping him ready for combat.  Although I do miss some of those glorious moments on the battlefield." },
        ["text"] = "На майстра Незінґварі чекає велике полювання.  Допомагати йому готуватися до дня в джунглях значно спокійніше, ніж споряджати його до бою.  Хоча мені бракує деяких славетних митей на полі битви.",
        ["npcs"] = { [1] = 716 },
        ["roles"] = { ["greeting"] = true },
    },
    [941249530] = {
        ["english"] = { [1] = "Kazum!  I hold your scepter!  I command you to enter this world!" },
        ["text"] = "Казуме!  Твій скіпетр у мене!  Я наказую тобі ввійти в цей світ!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [758328947] = {
        ["english"] = { [1] = "Slip a little coin into the boss's hand and look what it gets ya. I love my job. Though, if I could find a way to get that little firecracker Snurk reassigned to this port....well, I can't imagine it any better. But I'm betting that you aren't here about my business practices. You're looking for the Zeppelin to Undercity, am I right? Well that's great, because it docks right here behind me. Oh and hey, if you see Snurk, put a good word in for me, would ya?" },
        ["text"] = "Підсунь босу монетку — й дивись, що отримуєш. Обожнюю свою роботу. От якби ще вдалося перевести сюди в порт ту запальну малу Снурк... кращого й уявити не можу. Але ти, мабуть, не заради моїх ділових методів прийшов. Шукаєш дирижабль до Підміста, так? Чудово, бо він причалює просто тут, у мене за спиною. І якщо побачиш Снурк, замов за мене добре слово, гаразд?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2249272677] = {
        ["english"] = { [1] = "Malukaz chatters incessantly about the historical importance of this forest, but I don't have the luxury of indulging in history until our present problems are settled.$B$BI'm not saying his work here isn't important, but someone has to see to the defenses and logistics of running the hold." },
        ["text"] = "Малуказ без упину базікає про історичне значення цього лісу, але я не маю розкоші занурюватися в минуле, доки ми не владнали теперішні проблеми.$B$BНе кажу, що його робота тут неважлива, та хтось мусить дбати про оборону й забезпечення фортеці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [945806998] = {
        ["english"] = { [1] = "Oh....$b$bWhere am I?" },
        ["text"] = "Ох....$b$bДе я?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3450949859] = {
        ["english"] = { [1] = "Pets to take care of?  Just make sure you clean up after it!  Look for Shoja'my in front of the inn." },
        ["text"] = "Є вихованці, про яких треба подбати?  Тільки не забувай за ними прибирати!  Шукай Шоджа’мі перед заїздом.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [5667954] = {
        ["english"] = { [1] = "Oh, I am so glad you have returned, $N.$B$BMy brother's spirit has now be freed from the corruption, but I choose to remain here, in my mourning.$B$BThank you so much for your help, $N." },
        ["text"] = "О, я так радий, що ти повернувся, $N.$B$BДух мого брата тепер звільнений від скверни, але я вирішив залишитися тут у жалобі.$B$BЩиро дякую за твою допомогу, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2812308949] = {
        ["english"] = { [1] = "Raene, I lost Dartol's Rod of Transformation." },
        ["text"] = "Рейно, я загубив жезл перетворення Дартола.",
        ["npcs"] = { [1] = 3691 },
        ["roles"] = { ["reply"] = true },
    },
    [1132808333] = {
        ["english"] = { [1] = "Of course not, dear $g boy:girl;. You 'adventurer' types are often victims of circumstance; subject to the political drama which tends to unfold between citizenry and royalty.$B$BMy advice to you, then, is to seek out something else, more specifically: A new career.$B$BThis world has enough heroes." },
        ["text"] = "Звісно ні, $g любий хлопче : люба дівчино;. Ви, «шукачі пригод», часто стаєте жертвами обставин і політичних драм між простолюдом та владою.$B$BТож моя порада — знайди собі щось інше. Конкретніше: нову кар’єру.$B$BУ цьому світі й без того досить героїв.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1787114019] = {
        ["english"] = { [1] = "May the spirits be with you." },
        ["text"] = "Нехай духи будуть із тобою.",
        ["npcs"] = { [1] = 986, [2] = 3030, [3] = 3031, [4] = 3032, [5] = 3062, [6] = 3066, [7] = 3157, [8] = 3173, [9] = 3344, [10] = 13417 },
        ["roles"] = { ["greeting"] = true },
    },
    [975459400] = {
        ["english"] = { [1] = "Radiation?!$B$BNo, you don't need to worry about that!  Sheesh, the things that people believe these days.$B$BSo, what do you think of our operations down here?  State of the art, baby!  You better believe it." },
        ["text"] = "Радіація?!$B$BНі, про це тобі не треба хвилюватися!  Ох і вигадують люди нині.$B$BНу то як тобі наша робота тут унизу?  Передові технології, крихітко!  Можеш не сумніватися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1801050350] = {
        ["english"] = { [1] = "So that's how Windsor died..." },
        ["text"] = "Отже, ось як загинув Віндзор...",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [435718104] = {
        ["english"] = { [1] = "Quid pro quo! I'll teach you what I know, but first I want you to perform a small task?" },
        ["text"] = "Послуга за послугу! Я навчу тебе того, що знаю, але спершу виконаєш невеличке завдання?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3232454642] = {
        ["english"] = { [1] = "Puzzled by what you see, stranger?$B$BWe give praise to the spirits of our ancestors by keeping the flame of their memory alive and paying it tribute." },
        ["text"] = "Дивує те, що бачиш, незнайомцю?$B$BМи вшановуємо духів предків, підтримуючи полум’я пам’яті про них і віддаючи йому шану.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4082290226] = {
        ["english"] = { [1] = "It's not always about money, clem!  While we receive generous donations - some extremely substantial - our traveling troupe of performers is fueled creatively by a need to brighten this war-torn world.  Don't worry about us, but instead let us worry about how to best entertain you." },
        ["text"] = "Не все крутиться довкола грошей, Клеме!  Ми отримуємо щедрі пожертви — часом надзвичайно щедрі, — та нашу мандрівну трупу надихає прагнення принести трохи світла в цей понівечений війною світ.  Не хвилюйся за нас — краще дозволь нам подбати про те, як тебе якнайкраще розважити.",
        ["npcs"] = { [1] = 14823 },
        ["roles"] = { ["greeting"] = true },
    },
    [3529663556] = {
        ["english"] = { [1] = "Put your back into it, $glad:lass;. Hard work and determination--that's the way! Don't let anyone tell you book learnin' is all ye need." },
        ["text"] = "Налягай, $gхлопче:дівчино;. Важка праця й наполегливість — ось шлях! Не слухай тих, хто каже, що досить лише книжок.",
        ["npcs"] = { [1] = 1246 },
        ["roles"] = { ["greeting"] = true },
    },
    [2524811602] = {
        ["english"] = { [1] = "It's so good to see another sin'dorei $g brother : sister;!  As you can imagine, there's not much in the way of conversation around here." },
        ["text"] = "Так приємно бачити ще одного сін’дорай $g брате : сестро;!  Як можеш здогадатися, тут не надто багато співрозмовників.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2719203086] = {
        ["english"] = { [1] = "Oh the horror! The tragedy! We are on the verge of a breakthrough, yet all could be lost." },
        ["text"] = "О, який жах! Яка трагедія! Ми на порозі прориву, та все може бути втрачено.",
        ["npcs"] = { [1] = 14374 },
        ["roles"] = { ["greeting"] = true },
    },
    [59049129] = {
        ["english"] = { [1] = "Listen $g sonny:missy;, I'll have you know that whatever attacked us was no priestess of nothin'! Her eyes were aglow with something evil and she was genuinely frothing at the mouth! She came in, did some kind of crazy scream that sent us all runnin' in separate directions then started flayin' our minds one by one. I'd be hearin' shadowy words in my head, watchin' the other's periodically black out here and there. It was madness! We would have been done for if not for the damned monkey." },
        ["text"] = "Слухай, $g синку:панно;, кажу тобі: те, що на нас напало, ніякою жрицею не було! Очі в неї світилися чимось лихим, а з рота справді йшла піна! Вона ввірвалася, якось несамовито заверещала — ми всі порозбігалися в різні боки, — а тоді почала по одному шматувати нам розум. Я чув у голові тіньові голоси й бачив, як інші раз по раз непритомніли. Суцільне божевілля! Нам був би кінець, якби не та клята мавпа.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [433019056] = {
        ["english"] = { [1] = "My captors were cruel beyond measure, $N. They would alternate between Lieutenant Kirith and I, torturing one while the other watched. During a lull in the activity of an especially brutal day, Kirith told me what had happened to my men and a plan he had been formulating to free them from their masters.$B$BThey suffered a fate far worse than death, or even the pain Kirith and I  endured." },
        ["text"] = "Мої мучителі були неймовірно жорстокі, $N. Вони по черзі катували нас із лейтенантом Кірітом: одного мучили, а другого змушували дивитися. Під час затишшя після особливо жорстокого дня Кіріт розповів, що сталося з моїми людьми, і про план, який він придумував, щоб визволити їх від господарів.$B$BЇх спіткала доля значно гірша за смерть чи навіть муки, які пережили ми з Кірітом.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [1293880718] = {
        ["english"] = { [1] = "Look to this fallen dragon, $r. The might of the Horde is unquestionable!" },
        ["text"] = "Поглянь на цього поваленого дракона, $r. Міць Орди беззаперечна!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [737697102] = {
        ["english"] = { [1] = "Look for Faruza.  Last I saw she was standing out front between the stables and the house on the northwest end of town." },
        ["text"] = "Шукай Фарузу.  Востаннє я бачив її надворі між стайнями й будинком у північно-західній частині міста.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [892146574] = {
        ["english"] = { [1] = "Just remember, $N, it's in our best interests that you do as much as possible for these... these people." },
        ["text"] = "Пам’ятай, $N, у наших же інтересах, щоб ти зробив якомога більше для цих... цих людей.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3508018955] = {
        ["english"] = { [1] = "Killian Hagey teach skinning in Rogues' Quarter on inner ring." },
        ["text"] = "Кілліан Гейґі вчить знімати шкури в Кварталі розбійників, на внутрішньому кільці.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [762517043] = {
        ["english"] = { [1] = "Progeny of Aegwynn, he that would be the last Guardian of Tirisfal... Medivh." },
        ["text"] = "Нащадок Ейґвін, той, кому судилося стати останнім Хранителем Тірісфалю... Медів.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [3432673984] = {
        ["english"] = { [1] = "Like Kel'Thuzad, I too was once a mage of the Kirin Tor. And like Kel'Thuzad, I seek the legendary Atiesh, greatstaff of the Guardian. Our fates are intertwined as such, $c." },
        ["text"] = "Як і Кел’Тузад, я колись був магом Кірін-Тору. І так само, як Кел’Тузад, я шукаю легендарний Атієш, великий посох Хранителя. Ось так переплелися наші долі, $c.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [3938361532] = {
        ["english"] = { [1] = "Matters of such an official nature are only handled in Darnassus.  You must travel there to begin the process of your guild's creation." },
        ["text"] = "Такі офіційні справи вирішуються лише в Дарнасі.  Тобі доведеться вирушити туди, щоб розпочати створення своєї гільдії.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1010946904] = {
        ["english"] = { [1] = "Priest trainer?  You go to outer ring of War Quarter and look for them there." },
        ["text"] = "Наставник жерців?  Іди на зовнішнє кільце Бойового кварталу й шукай там.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [20073862] = {
        ["english"] = { [1] = "May Elune walk with you, $c.  The Temple of the Moon has come to help the troubled citizens of Auberdine." },
        ["text"] = "Нехай Елуна йде поруч із тобою, $c.  Храм Місяця прийшов на допомогу стривоженим мешканцям Аубердіна.",
        ["npcs"] = { [1] = 10219 },
        ["roles"] = { ["greeting"] = true },
    },
    [1625383877] = {
        ["english"] = { [1] = "Looks like we have as many lean wolf steaks as the Horde wants. They told me to pack up what we have here and ready it to be shipped it out to Cenarion Hold in Silithus. But it looks like some of the others here might still be collecting whatever it is that they're in charge of. Go bug one of them." },
        ["text"] = "Схоже, пісних вовчих стейків у нас уже стільки, скільки Орді потрібно. Мені наказали спакувати все й підготувати до відправлення в Кенарійську цитадель у Силітусі. Але дехто тут, здається, досі збирає те, за що відповідає. Іди докучай їм.",
        ["npcs"] = { [1] = 15533 },
        ["roles"] = { ["greeting"] = true },
    },
    [128970865] = {
        ["english"] = { [1] = "Priest" },
        ["text"] = "Жрець",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3296, [19] = 3571, [20] = 4262, [21] = 5595, [22] = 5624, [23] = 5725, [24] = 5953, [25] = 6272, [26] = 6740, [27] = 8931, [28] = 12996, [29] = 13076, [30] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [3050147772] = {
        ["english"] = { [1] = "Presumed to exist. Only a greater chromatic dragonkin or dragon could possess such a carapace." },
        ["text"] = "Імовірно існує. Лише великий хроматичний драконід або дракон міг би мати такий панцир.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [293832436] = {
        ["english"] = { [1] = "No, not that I can tell. It seems to be mostly based on region. Some races have labled them slimes, some oozes. It seems to be preference mostly.$B$BEvery time I've encountered ooze, sludge, or slime they have basically been the same creatures. The differences seem to be based on their environment, which is why we need a pure sample." },
        ["text"] = "Ні, наскільки я бачу. Схоже, все переважно залежить від регіону. Одні раси називають їх слизами, інші — слизовиками. Здебільшого це лише питання вподобання.$B$BЩоразу, коли я зустрічав слизовиків, багнюк чи слизів, це були по суті ті самі створіння. Відмінності, схоже, залежать від довкілля, тому нам і потрібен чистий зразок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3119613118] = {
        ["english"] = { [1] = "Praise Elune! It has been many years since I have had visitors." },
        ["text"] = "Хвала Елуні! Минуло багато років відтоді, як у мене були гості.",
        ["npcs"] = { [1] = 8436 },
        ["roles"] = { ["greeting"] = true },
    },
    [3960332889] = {
        ["english"] = { [1] = "Potions and oils, these are things that Yelmak will teach you of if you are worthy.  Look for his shop in the middle of The Drag." },
        ["text"] = "Зілля й оливи — цього Єлмак навчить тебе, якщо ти гідний.  Шукай його крамницю посеред Хитрого провулка.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1309760762] = {
        ["english"] = { [1] = "Make it quick, $c." },
        ["text"] = "Швидше, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1894424700] = {
        ["english"] = { [1] = "Need to requisition some supplies?" },
        ["text"] = "Треба отримати припаси?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [892614948] = {
        ["english"] = { [1] = "Possessed by what?" },
        ["text"] = "Одержимий чим?",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [1705632098] = {
        ["english"] = { [1] = "Looks like there be only $2113w more days left to fish until all this here war materiel is shipped over to the Silithus desert mon. Then they's gonna be getting' it all ready, and someone is gonna have to ring that gong down south of Cenarion Hold there to open them gates and be startin' the war." },
        ["text"] = "Схоже, лишилося тільки $2113w днів рибалити, перш ніж усі ці воєнні припаси повезуть у пустелю Силітуса, друже. Потім усе підготують, і комусь доведеться вдарити в той гонг на південь від Кенарійської цитаделі, щоб відчинити брами й почати війну.",
        ["npcs"] = { [1] = 15534 },
        ["roles"] = { ["greeting"] = true },
    },
    [1242204855] = {
        ["english"] = { [1] = "Ponder on da thing you have witnessed this day, $n.$b$bDa future already be written. Only thing to decide be your part in it, mon." },
        ["text"] = "Поміркуй над тим, що побачив сьогодні, $n.$b$bМайбутнє вже написане. Треба лише вирішити, яку роль у ньому зіграєш ти, друже.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [974624469] = {
        ["english"] = { [1] = "Polearm" },
        ["text"] = "Древкова зброя",
        ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11868, [5] = 11869, [6] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [1128185429] = {
        ["english"] = { [1] = "Our Alchemist's name is Carolai Anise.  You'll find her in a house at the northwest end of Brill." },
        ["text"] = "Нашу алхімікиню звати Каролай Аніс.  Знайдеш її в будинку на північно-західній околиці Брілля.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1195854682] = {
        ["english"] = { [1] = "Maces, they taught by Ansekhwa, found on da lower central rise of Thunder Bluff." },
        ["text"] = "Булави, їм Ансеква вчить, на нижньому центральному виступі Громового Бескиду.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [3632143657] = {
        ["english"] = { [1] = "Maybe... What do I do now?" },
        ["text"] = "Може... Що мені тепер робити?",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["reply"] = true },
    },
    [4111363426] = {
        ["english"] = { [1] = "Polar Bracers." },
        ["text"] = "Полярні наручі.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2617640697] = {
        ["english"] = { [1] = "Mailbox" },
        ["text"] = "Поштова скринька",
        ["npcs"] = { [1] = 4262, [2] = 5595, [3] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [478397807] = {
        ["english"] = { [1] = "Plucky?  I heard race master Kronkrider up on the the tower knows where he is." },
        ["text"] = "Плакі?  Чув, розпорядник перегонів Кронкрайдер на вежі знає, де він.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [8052608] = {
        ["english"] = { [1] = "Please tell me more about Zaetar." },
        ["text"] = "Розкажи мені більше про Заєтара.",
        ["npcs"] = { [1] = 13716 },
        ["roles"] = { ["reply"] = true },
    },
    [3489536439] = {
        ["english"] = { [1] = "Oh yes, that's right.$B$BSo, here we are invading deep into the upper reaches of Blackrock Spire, against their lord and leader; this was before Drakkisath. Not too smart if you ask me, but our leader, Anthion Harmon, you met him, was always one who loved a challenge.$B$BSurprisingly, everything went according to plan, right up to the point where we were prying Valthalak's spellbook out of his stiff fingers. That's when it all went south.$B$BShould I continue? You look like your eyes are glazing over." },
        ["text"] = "О так, точно.$B$BОтже, ми вторглися далеко у верхні яруси Чорнокамінного Шпиля, прямо проти їхнього лорда й ватажка; це було ще до Драккісата. Не надто розумно, як на мене, але наш лідер Антіон Гармон — ти його зустрічав — завжди любив виклики.$B$BНа диво, все йшло за планом аж до моменту, коли ми видирали книгу заклять Валтахака з його закляклих пальців. Тоді все й полетіло шкереберть.$B$BПродовжувати? У тебе вже очі скляніють.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [3126123874] = {
        ["english"] = { [1] = "Mrglrglrglrgl... glrgl?" },
        ["text"] = "Мрґлрґлрґлрґл... ґлрґл?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [342045743] = {
        ["english"] = { [1] = "Kar Aman, $N. You look to be a strong $c--you would do well to mind yourself in this area. Touching things you know nothing about, or showing disrespect to your elders is just cause for punishment.$B$BYou may not respect me or my companions, but you will learn to respect our power if you prove foolish enough.$B$BNow, enough with the pleasantries, was there something I can do for you?" },
        ["text"] = "Кар Аман, $N. На вигляд ти сильний $c — тобі варто поводитися тут обачно. Торкатися речей, про які нічого не знаєш, або виявляти неповагу до старших — цілком достатня причина для покарання.$B$BМожеш не поважати мене чи моїх супутників, але навчишся поважати нашу силу, якщо виявишся достатньо нерозумним.$B$BА тепер досить люб’язностей. Чимось можу допомогти?",
        ["npcs"] = { [1] = 6266 },
        ["roles"] = { ["greeting"] = true },
    },
    [3719282154] = {
        ["english"] = { [1] = "Plucky doesn't want Tirth to know he's still in the Shimmering Flats, so he turned himself into a chicken!$B$BIf you find Plucky, beckon him to you.  Maybe he'll come out of hiding." },
        ["text"] = "Плакі не хоче, щоб Тірт знав, що він досі на Мерехтливій Рівнині, тож перетворився на курку!$B$BЯк знайдеш Плакі — поклич його жестом.  Може, він вийде зі схованки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3279515976] = {
        ["english"] = { [1] = "Pleased to meet you, $c." },
        ["text"] = "Радий знайомству, $c.",
        ["npcs"] = { [1] = 2708 },
        ["roles"] = { ["greeting"] = true },
    },
    [3419923340] = {
        ["english"] = { [1] = "Not bad, for a beginner! I guess it couldn't hurt for me to show you a few things..." },
        ["text"] = "Непогано, як для новачка! Гадаю, не завадить показати тобі кілька речей...",
        ["npcs"] = { [1] = 11029 },
        ["roles"] = { ["greeting"] = true },
    },
    [2966166576] = {
        ["english"] = { [1] = "Look inside the Gallows' End Tavern's main dining room for Austil de Mon.  The tavern is on the southeast edge of Brill." },
        ["text"] = "Шукай Остіля де Мона в головній залі таверни «Кінець Шибениці».  Таверна стоїть на південно-східній околиці Брілля.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [266331166] = {
        ["english"] = { [1] = "Making it out of here without a blade in your back or poison in your veins would be an accomplishment." },
        ["text"] = "Вибратися звідси без клинка в спині чи отрути у венах — уже досягнення.",
        ["npcs"] = { [1] = 6771 },
        ["roles"] = { ["greeting"] = true },
    },
    [549504282] = {
        ["english"] = { [1] = "Pleased to make you acquaintance. May I help you?" },
        ["text"] = "Радий знайомству. Чим можу допомогти?",
        ["npcs"] = { [1] = 3523 },
        ["roles"] = { ["greeting"] = true },
    },
    [638700628] = {
        ["english"] = { [1] = "Over in the Hall of Arms you can find our resident stable master, Ulbrek Firehand.  He'll make sure any pets ye have are well fed and rightly cared for." },
        ["text"] = "У Залі зброї знайдеш нашого доглядача стайні Ульбрека Вогнерука.  Він подбає, щоб твої вихованці були нагодовані й доглянуті як слід.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3521935195] = {
        ["english"] = { [1] = "Keep your voice down. We wouldn't want to attract any attention from these beasties!" },
        ["text"] = "Говори тихіше. Не хочемо ж привертати увагу цих звірюк!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3454152516] = {
        ["english"] = { [1] = "Please, help me $g brother : sister;...$B$BI will soon pass from this world, and though I suffer I know I shall not any more once I pass.  The wildlife though, my $g brother : sister;... the wildlife suffers too, and it knows no release.  I ask for your aid with my last breaths of life." },
        ["text"] = "Будь ласка, допоможи мені, $g брате : сестро;...$B$BСкоро я покину цей світ, і хоч зараз страждаю, знаю, що після смерті болю більше не буде.  Але дика природа, $g мій брате : моя сестро;... вона теж страждає й не знає визволення.  Останнім подихом прошу тебе допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1871809263] = {
        ["english"] = { [1] = "Over by Crystal Lake there lives a lady named Adele Fielder.  She makes patches for the local guards with the extra leather she gets from the local skinner, Helene.  She would probably be the one to see if you're interested in learning the profession." },
        ["text"] = "Біля Кришталевого озера живе жінка на ім’я Адель Філдер.  Вона робить латки для місцевої варти із зайвої шкіри, яку отримує від місцевої шкурниці Гелени.  Якщо хочеш навчитися ремесла, варто звернутися до неї.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1840570823] = {
        ["english"] = { [1] = "Please, don't say anything to me. I don't want to get into any more trouble with them." },
        ["text"] = "Будь ласка, нічого мені не кажи. Я не хочу знову мати через них неприємності.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1612105370] = {
        ["english"] = { [1] = "Please, tell me more." },
        ["text"] = "Розкажи мені більше, будь ласка.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [1587054147] = {
        ["english"] = { [1] = "It's hard to imagine that so much death and despair could be confined to such a small area; yet beyond the swamp is a land plagued by chaos and destruction.$B$BWatch your step, adventurer. The Blasted Lands are the final resting place to far greater beings than you." },
        ["text"] = "Важко уявити, що стільки смерті й відчаю може вміститися на такій малій території; та за болотом лежить край, охоплений хаосом і руйнуванням.$B$BДивися під ноги, шукачу пригод. Спустошені землі стали останнім прихистком для істот, значно могутніших за тебе.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [3791291788] = {
        ["english"] = { [1] = "Korfax, where can I find Dark Iron scraps?" },
        ["text"] = "Корфаксе, де мені знайти уламки Темного Заліза?",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["reply"] = true },
    },
    [3115390574] = {
        ["english"] = { [1] = "May the Lich King burn in hellfire for what he has called down upon this land." },
        ["text"] = "Нехай Король-ліч горить у пекельному вогні за все, що він накликав на цю землю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4091217190] = {
        ["english"] = { [1] = "Please, $r...$b$bLeave nothing for the Scourge to raise!" },
        ["text"] = "Будь ласка, $r...$b$bНе залиш Батогу нічого, що можна підняти з мертвих!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3652049928] = {
        ["english"] = { [1] = "Please, $r.$b$bRelease me..." },
        ["text"] = "Будь ласка, $r.$b$bЗвільни мене...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4122865529] = {
        ["english"] = { [1] = "Make haste, $c!$b$bThis crisis is nowhere near being under control." },
        ["text"] = "Поквапся, $c!$b$bЦя криза ще й близько не під контролем.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [413994375] = {
        ["english"] = { [1] = "Just in... another batch of Darkmoon Special Reserve.  Come get yours before they're all gone!" },
        ["text"] = "Щойно прибуло... ще одна партія «Особливого запасу Темного Місяця».  Забирай своє, поки все не розібрали!",
        ["npcs"] = { [1] = 14844 },
        ["roles"] = { ["greeting"] = true },
    },
    [3045365206] = {
        ["english"] = { [1] = "Little forsaken know all weapons.  Him Archibald.  You find on inner ring of War Quarter." },
        ["text"] = "Малий відречений знає всю зброю.  Він Арчибальд.  Знайдеш на внутрішньому кільці Бойового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3513650618] = {
        ["english"] = { [1] = "So you're here for the Warsong axes. Well, it's about time, $N. That crate has been sitting out there for days, now.$B$BFeel free to haul it away whenever you are ready." },
        ["text"] = "Отже, ти прийшов по сокири Пісні Війни. Нарешті, $N. Та скриня вже кілька днів стоїть надворі.$B$BЗабирай її, коли будеш готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2240795333] = {
        ["english"] = { [1] = "OK boss, when you ready for da tribue from your henchmen, you let me know!" },
        ["text"] = "Гаразд, босе, коли будеш готовий отримати данину від своїх поплічників — скажи мені!",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["greeting"] = true },
    },
    [2597504929] = {
        ["english"] = { [1] = "Please tell me more about the Gordunni ogres." },
        ["text"] = "Розкажи мені більше про огрів Ґордунні.",
        ["npcs"] = { [1] = 7763 },
        ["roles"] = { ["reply"] = true },
    },
    [2894773472] = {
        ["english"] = { [1] = "Soon, $n!$b$bSoon ya be tastin' true power. Soon ya be rewarded for your dedication and service.$B" },
        ["text"] = "Скоро, $n!$b$bСкоро ти скуштувати справжню силу. Скоро ти отримати нагороду за свою відданість і службу.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3483055761] = {
        ["english"] = { [1] = "Only those who have proven themselves to not be hostile toward the Timbermaw may pass through the Hold without fear of being attacked.  Have you made an effort to earn our trust, outsider?" },
        ["text"] = "Лише ті, хто довів свою неворожість до Деревопащих, можуть безпечно проходити через Твердиню.  Чи доклав ти зусиль, щоб заслужити нашу довіру, чужинцю?",
        ["npcs"] = { [1] = 15395 },
        ["roles"] = { ["greeting"] = true },
    },
    [927195704] = {
        ["english"] = { [1] = "My question to you is this, $c:$BWhich of the Aspects created by the titans became the nefarious creature known as Deathwing?" },
        ["text"] = "Моє питання до тебе, $c:$BЯкий з Аспектів, створених титанами, став лиховісною істотою, відомою як Смертекрил?",
        ["npcs"] = { [1] = 4489 },
        ["roles"] = { ["greeting"] = true },
    },
    [531362150] = {
        ["english"] = { [1] = "Oh good, reinforcements!" },
        ["text"] = "О, чудово, підкріплення!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [564556455] = {
        ["english"] = { [1] = "Skin, glorious skin. It holds your insides... in. You might've noticed my skin's not doing so well. To think I used to worry about my pores. Hardly any skin left to worry about these days. In a way, it's very freeing." },
        ["text"] = "Шкіра, славна шкіра. Вона тримає твої нутрощі... всередині. Може, ти помітив, що моя шкіра не в найкращому стані. А колись я переживав через пори. Тепер шкіри лишилося так мало, що й переживати нема про що. У певному сенсі це навіть звільняє.",
        ["npcs"] = { [1] = 223, [2] = 3549 },
        ["roles"] = { ["greeting"] = true },
    },
    [1045931152] = {
        ["english"] = { [1] = "It's here!  The Darkmoon Faire is now open for business!  Be sure to see the most exciting show on all of Azeroth!" },
        ["text"] = "Воно тут!  Ярмарок Темного Місяця вже відкрито!  Не пропусти найзахопливіше видовище в усьому Азероті!",
        ["npcs"] = { [1] = 14842 },
        ["roles"] = { ["greeting"] = true },
    },
    [3311295442] = {
        ["english"] = { [1] = "Please share your wisdom with me, Warchief." },
        ["text"] = "Поділися зі мною своєю мудрістю, Вождю.",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["reply"] = true },
    },
    [3864101648] = {
        ["english"] = { [1] = "Please respect the laws of Dalaran while you are here, stranger.$B$BWere you lost? Is there something I might help you find?" },
        ["text"] = "Будь ласка, поважай закони Даларана, поки перебуваєш тут, незнайомцю.$B$BТи заблукав? Може, допомогти тобі щось знайти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1218408955] = {
        ["english"] = { [1] = "No, no, you'll need FAR more training before you're ready to learn from me! Go talk to that uptight dabbler Malcomb Wynn. He's the one buried in books over there." },
        ["text"] = "Ні-ні, тобі потрібно НАБАГАТО більше тренувань, перш ніж ти зможеш навчатися в мене! Іди до того манірного дилетанта Малкома Вінна. Це він он там зарився в книжки.",
        ["npcs"] = { [1] = 4616 },
        ["roles"] = { ["greeting"] = true },
    },
    [2665677746] = {
        ["english"] = { [1] = "Oh, hello there!  I'm Hol'anyee, the chief scientist and biologist of Marshal Expeditions.  My brother and I, along with our companions, travel Azeroth exploring the wild and untamed majesty.  It is exciting... but, um... I think we got ourselves into a little too much excitement this time!" },
        ["text"] = "О, привіт!  Я Гол’ані, головна науковиця й біологиня експедицій Маршалла.  Ми з братом і нашими супутниками мандруємо Азеротом, досліджуючи дику й неприборкану велич природи.  Це захопливо... але, е-е... схоже, цього разу пригод стало трохи забагато!",
        ["npcs"] = { [1] = 9271 },
        ["roles"] = { ["greeting"] = true },
    },
    [2625200554] = {
        ["english"] = { [1] = "Please leave me to my sadness." },
        ["text"] = "Будь ласка, залиш мене наодинці з моїм смутком.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2813527846] = {
        ["english"] = { [1] = "Let's see what you have." },
        ["text"] = "Подивімося, що в тебе є.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2353485385] = {
        ["english"] = { [1] = "Of course I will help!" },
        ["text"] = "Звісно, я допоможу!",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["reply"] = true },
    },
    [2250300876] = {
        ["english"] = { [1] = "Look at what you have done, death knight! You have brought glory to the Scourge!" },
        ["text"] = "Поглянь, що ти накоїв, лицарю смерті! Ти приніс славу Батогу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3219709999] = {
        ["english"] = { [1] = "Kiss me." },
        ["text"] = "Поцілуй мене.",
        ["npcs"] = { [1] = 14866 },
        ["roles"] = { ["greeting"] = true },
    },
    [1512019858] = {
        ["english"] = { [1] = "Look at the wisdom and knowledge of the beast, and you will see yourself. Observe as the owl does, learn cleverness from the sabercat, embody the mighty spirit of the wolf." },
        ["text"] = "Поглянь на мудрість і знання звіра — і побачиш себе. Спостерігай, як сова, вчися хитрості в шаблезуба, втілюй могутній дух вовка.",
        ["npcs"] = { [1] = 5515, [2] = 5516, [3] = 5517 },
        ["roles"] = { ["greeting"] = true },
    },
    [3147596574] = {
        ["english"] = { [1] = "Please continue." },
        ["text"] = "Продовжуй.",
        ["npcs"] = { [1] = 7783, [2] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [3953598950] = {
        ["english"] = { [1] = "Please continue, Zamael." },
        ["text"] = "Продовжуй, будь ласка, Замаелю.",
        ["npcs"] = { [1] = 8436 },
        ["roles"] = { ["reply"] = true },
    },
    [1199410832] = {
        ["english"] = { [1] = "My vicious teromoths will avenge me!" },
        ["text"] = "Мої люті теромолі помстяться за мене!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4178528007] = {
        ["english"] = { [1] = "Mawurrgggl, gurgl lur!" },
        ["text"] = "Мавуррґґґл, ґурґл лур!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2689137135] = {
        ["english"] = { [1] = "Please continue, Bodley." },
        ["text"] = "Продовжуй, будь ласка, Бодлі.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [820538619] = {
        ["english"] = { [1] = "Please allow me a few seconds of rest." },
        ["text"] = "Дай мені, будь ласка, кілька секунд відпочити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3991745732] = {
        ["english"] = { [1] = "Pilgrim's Bounty is a time to reflect upon one's good fortune and share with all around you.$B$BWe hope that all of our noble allies will join us in feasting and celebration." },
        ["text"] = "Щедрочастя — час згадати про свою удачу й поділитися нею з усіма довкола.$B$BСподіваємося, всі наші шляхетні союзники приєднаються до бенкету й святкування.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [388983076] = {
        ["english"] = { [1] = "Mr. Combs, the ship's engineer and quartermaster, can furnish you with whatever supplies you might require. He is a fair tinker, too, if your gear is in need of repair." },
        ["text"] = "Пан Комбс, корабельний інженер і квартирмейстер, забезпечить тебе всіма потрібними припасами. Він ще й непоганий майстер, якщо спорядження потребує ремонту.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3941403269] = {
        ["english"] = { [1] = "Pet families come in one of three types. Ferocious pets, like cats, can dish out damage but can't take it as well. Tenacious pets, like turtles, are more defensive and can occupy an enemy's attention while you stay at range. Cunning pets, like spiders, have a mix of offensive and defensive abilities and are particularly useful in Battlegrounds and Arenas.$b$bAs your pet gains more experience, it can learn new talents just like you can, but at a slower rate. If you ever want to change your pet's talents, just come back to me." },
        ["text"] = "Родини вихованців поділяються на три типи. Люті вихованці, як коти, завдають великої шкоди, але гірше її витримують. Витривалі вихованці, як черепахи, більш захисні й можуть утримувати увагу ворога, поки ти стоїш на відстані. Хитрі вихованці, як павуки, поєднують наступальні й захисні здібності та особливо корисні на Полях бою й Аренах.$b$bЗдобуваючи досвід, твій вихованець може вивчати нові таланти так само, як ти, але повільніше. Якщо захочеш змінити його таланти, просто повернися до мене.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [157706962] = {
        ["english"] = { [1] = "Once you start loosening the reins on the ram, you'll see his speed change. He starts off walking. Ease up on the reins a bit more and he'll start to trot. Give him more slack on the reins while he's trotting and he'll go into a canter. Give him even more slack while he's in a canter and you will send him into a gallop.$B$B" },
        ["text"] = "Коли почнеш послаблювати поводи барана, побачиш, як змінюється його швидкість. Спочатку він іде кроком. Трохи відпусти поводи — перейде на рись. Ще послаб — і з рисі перейде на легкий галоп. Відпусти ще більше під час легкого галопу — і він помчить повним галопом.$B$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1969282283] = {
        ["english"] = { [1] = "Perhaps you will tell me of your deeds, $N.  I would be honored to know them." },
        ["text"] = "Можливо, ти розповіси мені про свої подвиги, $N.  Для мене це буде честю.",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [3126973016] = {
        ["english"] = { [1] = "Sometimes I stand here, looking into the forest beyond the lake, and I see the land as it once was... green and full of life." },
        ["text"] = "Іноді я стою тут, дивлюся на ліс за озером і бачу цю землю такою, якою вона була колись... зеленою й повною життя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2791983483] = {
        ["english"] = { [1] = "May the light guide your path and aid you in your journeys. If you need any assistance browsing, I will be right over here." },
        ["text"] = "Нехай Світло освітлює твій шлях і допомагає в мандрах. Якщо потрібна допомога з вибором, я буду тут.",
        ["npcs"] = { [1] = 1350 },
        ["roles"] = { ["greeting"] = true },
    },
    [3825987895] = {
        ["english"] = { [1] = "Soon, Lokholar shall rise... Soon... Very, very soon..." },
        ["text"] = "Скоро Локголар підніметься... Скоро... Дуже, дуже скоро...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [324637573] = {
        ["english"] = { [1] = "Our storehouses have been depleted.  I have nothing to sell until we can get more supplies." },
        ["text"] = "Наші склади спорожніли.  Мені нічого продавати, доки ми не отримаємо нові припаси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2283654766] = {
        ["english"] = { [1] = "Paval Reethe." },
        ["text"] = "Павал Ріт.",
        ["npcs"] = { [1] = 4926 },
        ["roles"] = { ["reply"] = true },
    },
    [3646490328] = {
        ["english"] = { [1] = "Pardon the intrusion, Lady Prestor, but Highlord Bolvar suggested that I seek your advice." },
        ["text"] = "Перепрошую за втручання, леді Престор, але Верховний лорд Болвар порадив звернутися до вас.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1991871659] = {
        ["english"] = { [1] = "Smear the ash on my face like war paint!" },
        ["text"] = "Розмаж попіл мені по обличчю, наче бойову фарбу!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2059997322] = {
        ["english"] = { [1] = "Me versus fifty orcs? I'm no fool, $N. My pappy always told me, 'Discreditin is the better part of a cracker,' or something, and I knew what that meant." },
        ["text"] = "Я проти п’ятдесяти орків? Я не дурень, $N. Татко завжди казав: «Дискредитація — краща частина сухаря» чи щось таке, і я знав, що він мав на увазі.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [1578782215] = {
        ["english"] = { [1] = "Need gold? Here's 5,000 coins worth." },
        ["text"] = "Потрібне золото? Ось на 5000 монет.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [184535516] = {
        ["english"] = { [1] = "Long ago, my dryad sisters and I entered these caves to free the tortured spirit of my uncle, Zaetar. However, the corruption that had already spread through these caverns soon overcame us, and we too fell.$B$BWe were destined to wander these passages; the toxins poisoning our minds...$B$BAlthough my spirit may now be at rest, I know that I have failed in my mission. It is a great sadness I must bear..." },
        ["text"] = "Давним-давно ми з моїми сестрами-дріадами увійшли до цих печер, щоб звільнити змучений дух мого дядька Заєтара. Та скверна, що вже поширилася цими печерами, невдовзі здолала й нас.$B$BНам судилося блукати цими ходами, поки отрути затуманювали наш розум...$B$BХоч мій дух тепер, можливо, знайшов спокій, я знаю, що провалила свою місію. І цей великий смуток я нестиму з собою...",
        ["npcs"] = { [1] = 13716 },
        ["roles"] = { ["greeting"] = true },
    },
    [3668482731] = {
        ["english"] = { [1] = "Mushrooms always grow in damp places and so they look like umbrellas." },
        ["text"] = "Гриби завжди ростуть у вогких місцях, тому й схожі на парасольки.",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [3579539020] = {
        ["english"] = { [1] = "Lava? Pay no mind to all of that, friend. Look around you. Take in the joys that nature has to offer." },
        ["text"] = "Лава? Не зважай на це, друже. Озирнися довкола. Насолоджуйся дарами природи.",
        ["npcs"] = { [1] = 14529 },
        ["roles"] = { ["greeting"] = true },
    },
    [4027359317] = {
        ["english"] = { [1] = "May I have your report?" },
        ["text"] = "Можна ваш звіт?",
        ["npcs"] = { [1] = 15609, [2] = 15610, [3] = 15611 },
        ["roles"] = { ["reply"] = true },
    },
    [3510477315] = {
        ["english"] = { [1] = "Nature provides all that we need.  Speak to Komin Winterhoof at Holistic Herbalism on the middle rise." },
        ["text"] = "Природа дає нам усе необхідне.  Поговори з Коміном Зимове Копито з «Цілісного травництва» на середньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3737815537] = {
        ["english"] = { [1] = "Mmmmm food.  It's not too long of a run, but you need to head north to Orgrimmar and ask one of the grunts there." },
        ["text"] = "М-м-м, їжа.  Бігти недовго: вирушай на північ до Орґріммара й спитай одного з тамтешніх рубак.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [536278852] = {
        ["english"] = { [1] = "Paragons of Power are powerful mojo.  They are Gurubashi Empire mojo.  We Zandalar must get mojo.  The tribe will take mojo for our own.  The Blood God will not destroy us.$B$BThere are three kinds of Paragons in Zul'Gurub.  Seek coins.  Seek bijous.  Seek primal items.  These are the Paragons.$B$BGo to Zul'Gurub now.  Kill.  Take the Paragons of Power.  Bring them to the tribe.  Earn our respect.  Earn our battle gear.  Earn real power." },
        ["text"] = "Взірці Сили — могутнє моджо.  Це моджо імперії Ґурубаші.  Ми, зандалари, мусимо здобути моджо.  Плем’я забере моджо собі.  Бог Крові нас не знищить.$B$BУ Зул’Ґурубі є три види Взірців.  Шукай монети.  Шукай біжу.  Шукай первісні предмети.  Це і є Взірці.$B$BІди до Зул’Ґуруба.  Убивай.  Забирай Взірці Сили.  Принось їх племені.  Заслужи нашу повагу.  Заслужи наше бойове спорядження.  Заслужи справжню силу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3383867769] = {
        ["english"] = { [1] = "No doubt you are another inept simpleton sent from the Dark Lady to train under her champion.$B$B<Nathanos sighs.>$B$BI've sent every one of you back to her in pieces, I don't see why it will be any different this time.$B$BMine, however, is not to question why, but instead to do as the Dark Lady bids." },
        ["text"] = "Без сумніву, ти ще один нездарний телепень, якого Темна Пані прислала навчатися в її чемпіона.$B$B<Натанос зітхає.>$B$BЯ вже повернув їй кожного з вас шматками й не бачу причин, чому цього разу буде інакше.$B$BТа не мені питати чому — моє діло виконувати волю Темної Пані.",
        ["npcs"] = { [1] = 11878 },
        ["roles"] = { ["greeting"] = true },
    },
    [2179498054] = {
        ["english"] = { [1] = "Now, now, $n, just relax and take a deep breath. You really need to learn to trust me.$b$bYour lack of experience in these situations is causing you to panic, and panic always exaggerates the truth. So you see, there really is no crisis.$b$bNow that we've settled that, I must ask that you stop being so negative. It's not good for the crew's morale...." },
        ["text"] = "Ну-ну, $n, просто розслабся й глибоко вдихни. Тобі справді треба навчитися мені довіряти.$b$bЧерез брак досвіду в таких ситуаціях ти панікуєш, а паніка завжди перебільшує правду. Тож бачиш — ніякої кризи насправді немає.$b$bТепер, коли ми це з’ясували, прошу перестати бути таким песимістом. Це шкодить бойовому духові команди....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2974050902] = {
        ["english"] = { [1] = "Long have I waited for this day, hero. Are you and your allies prepared to bring the Lich King to justice? We charge on your command!" },
        ["text"] = "Я довго чекав цього дня, герою. Ти та твої союзники готові привести Короля-ліча до справедливості? Ми підемо в атаку за твоїм наказом!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1649469480] = {
        ["english"] = { [1] = "Ravenholdt Manor does not recognize you, $c." },
        ["text"] = "Маєток Рейвенгольдта тебе не визнає, $c.",
        ["npcs"] = { [1] = 6766 },
        ["roles"] = { ["greeting"] = true },
    },
    [3988668093] = {
        ["english"] = { [1] = "My mission is compete. I may have some spare supplies if you need any." },
        ["text"] = "Мою місію завершено. Якщо потрібно, у мене можуть знайтися зайві припаси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [165002366] = {
        ["english"] = { [1] = "Sayoc is the orc weapon master and is located in Orgrimmar's Valley of Honor.  He instructs in the use of bows, daggers, fist weapons, one and two-handed axes and thrown weapons.\010\010Hanashi, the troll weapon master in the Valley of Honor of Orgrimmar, can teach the use of bows, one and two-handed axes, staves and thrown weapons.\010\010Archibald, the undead weapon master in the War Quarter of the Undercity, can train the use of crossbows, daggers, one and two-handed swords and polearms.\010" },
        ["text"] = "Сайок — орк-майстер зброї в Долині Честі Орґріммара.  Він навчає володінню луками, кинджалами, кулачною зброєю, одноручними й дворучними сокирами та метальною зброєю.\010\010Ганаші, троль-майстер зброї в Долині Честі Орґріммара, навчає володінню луками, одноручними й дворучними сокирами, посохами та метальною зброєю.\010\010Арчибальд, невмерлий майстер зброї в Бойовому кварталі Підміста, навчає володінню арбалетами, кинджалами, одноручними й дворучними мечами та древковою зброєю.\010",
        ["npcs"] = { [1] = 11869 },
        ["roles"] = { ["greeting"] = true },
    },
    [643073796] = {
        ["english"] = { [1] = "It's true, even stranglekelp can be quite useful in building up what we need for the upcoming war at Ahn'Qiraj! It has so many uses, like making ice cream for hot days under the Silithus sun, as a salve for the effects of some icky plants, breathing underwater, hardening the skin, making you quick, regaining magic power; so many things I can't think of them all! Did I mention making ice cream?$B$BAnywhoodles, I've got about $2047w here, and I need a total of $2048w!" },
        ["text"] = "Це правда, навіть душник може бути дуже корисним для підготовки до майбутньої війни в Ан’Кіражі! Йому стільки застосувань: можна робити морозиво для спекотних днів під сонцем Силітуса, мазь від гидких рослин, дихати під водою, зміцнювати шкіру, ставати прудкішим, відновлювати магічну силу — стільки всього, що й не згадаю! Я вже казала про морозиво?$B$BКоротше кажучи, у мене тут приблизно $2047w, а потрібно загалом $2048w!",
        ["npcs"] = { [1] = 15434 },
        ["roles"] = { ["greeting"] = true },
    },
    [3888896278] = {
        ["english"] = { [1] = "My skill at creating potions is inferior to yours. You are ready to speak with Ainethil, just over there. She will understand that you are ready for further instruction." },
        ["text"] = "Ти вже вправніший у виготовленні зіль, ніж я. Тобі час поговорити з Айнетіль, он там. Вона зрозуміє, що ти готовий до подальшого навчання.",
        ["npcs"] = { [1] = 11042 },
        ["roles"] = { ["greeting"] = true },
    },
    [4160782058] = {
        ["english"] = { [1] = "Jenova Stoneshield over in the Dwarven District is the one you're looking for.  She tends to hunters' pets while they seek training from her father." },
        ["text"] = "Тобі потрібна Дженова Кам’яний Щит у Дворфійському районі.  Вона доглядає вихованців мисливців, поки ті навчаються в її батька.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3113242335] = {
        ["english"] = { [1] = "My Gizmotic Almanacotron says that we should beat the goblins by twenty seconds more than we did last time!" },
        ["text"] = "Мій Гізмотичний Альманахотрон каже, що цього разу ми маємо обігнати гоблінів ще на двадцять секунд більше, ніж минулого!",
        ["npcs"] = { [1] = 4430 },
        ["roles"] = { ["greeting"] = true },
    },
    [1892500528] = {
        ["english"] = { [1] = "Oh... do I know you?" },
        ["text"] = "О... ми знайомі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3883747523] = {
        ["english"] = { [1] = "Please, a moment, $N. Kindal is down below in the Grimtotem camp trying to free the faerie dragons from captivity. We were just lucky that help came along when it did. Who knows what those foul tauren would have done to them." },
        ["text"] = "Зачекай хвилинку, $N. Кіндал унизу в таборі Зловісного Тотема намагається звільнити чарівних дракончиків із полону. Нам просто пощастило, що допомога прийшла саме тоді. Хто знає, що ці мерзенні таурени могли з ними зробити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3723630804] = {
        ["english"] = { [1] = "Over a thousand years ago a group of troll priests known as the Atal'ai attempted to bring back an ancient blood god named Hakkar the Soulflayer. After the resulting civil war the priests were defeated and exiled to the Swamp of Sorrows. There they erected a temple to Hakkar to prepare for his arrival into the physical world. The dragon Aspect Ysera soon learned of the Atal'ai's plans and smashed the temple beneath the marshes. To this day, the temple's ruins are guarded by the mighty green dragons.\010" },
        ["text"] = "Понад тисячу років тому група трольських жерців, відомих як Атал’ай, намагалася повернути стародавнього бога крові на ім’я Гаккар Душошкур. Після громадянської війни жерців перемогли й вигнали на Болото Скорботи. Там вони звели храм Гаккару, готуючись до його приходу у фізичний світ. Дракониця-Аспект Ісера невдовзі дізналася про плани Атал’ай і розтрощила храм, поховавши його під болотами. До сьогодні руїни храму охороняють могутні зелені дракони.\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2225216959] = {
        ["english"] = { [1] = "Mmm, mmm, mmm. Can you smell that?! That's good eatin' right there, $c. Rainbow Fin Albacore hits the spot every time. Slicky Gastronome here, ace connoisseur of all things edible, especially fish. With the Ahn'Qiraj War looming, the Alliance thought it wise to bring in an expert for the war effort, so here I am, large and in charge.$B$BLooks like we're going to need $2093w of the fish, and we've got a pile that currently comes to $2092w." },
        ["text"] = "М-м-м. Чуєш цей запах?! Оце смакота, $c. Альбакор райдужного плавця завжди те, що треба. Я Слизький Гастроном, неперевершений знавець усього їстівного, особливо риби. Через наближення війни в Ан’Кіражі Альянс вирішив залучити до воєнних приготувань справжнього фахівця — тож ось я, великий і головний.$B$BСхоже, нам знадобиться $2093w цієї риби, а зараз у купі $2092w.",
        ["npcs"] = { [1] = 15455 },
        ["roles"] = { ["greeting"] = true },
    },
    [457238693] = {
        ["english"] = { [1] = "Och, there's nothing I can teach ye, $N. Have a word with Tally Berryfizz over there. She can hardly reach the tables, but when she starts brewing a potion, watch out!" },
        ["text"] = "Ох, мені більше нічого тебе вчити, $N. Поговори он із Таллі Берріфіз. Вона ледве дістає до столів, але коли починає варити зілля — краще дивись уважно!",
        ["npcs"] = { [1] = 1246 },
        ["roles"] = { ["greeting"] = true },
    },
    [4280991466] = {
        ["english"] = { [1] = "Outstanding! Killing a Pit Lord such as Azgalor is no small feat, my friend. If we had more time, I would love to hear the story of you and your companions. Archimonde will not give us that pause, however. My scouts have already reported that the Legion is amassing an immense force outside our camp, and Archimonde is very close to the World Tree. We are evacuating with the help of Lady Proudmoore. You should head to the World Tree at once. The fate of our world is still undecided." },
        ["text"] = "Видатно! Убити Володаря Ями на кшталт Азґалора — неабиякий подвиг, друже. Якби було більше часу, я із задоволенням вислухав би історію про тебе й твоїх супутників. Та Архімонд не дасть нам такої паузи. Розвідники вже доповіли, що Легіон збирає величезне військо біля нашого табору, а Архімонд дуже близько до Світового Дерева. Ми евакуюємося за допомогою леді Праудмур. Тобі слід негайно вирушити до Світового Дерева. Доля нашого світу ще не вирішена.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [9202546] = {
        ["english"] = { [1] = "Maces are a specialty of Buliwyf's! He's around this shop somewhere, grousing." },
        ["text"] = "Булави — спеціальність Булівіфа! Він десь у цій крамниці, бурчить собі під ніс.",
        ["npcs"] = { [1] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2475278060] = {
        ["english"] = { [1] = "Mining" },
        ["text"] = "Гірництво",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 5595, [30] = 5624, [31] = 5725, [32] = 5953, [33] = 6272, [34] = 6740, [35] = 8931, [36] = 12996, [37] = 13076, [38] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [2814105891] = {
        ["english"] = { [1] = "Neltharion is  my answer." },
        ["text"] = "Моя відповідь — Нелтаріон.",
        ["npcs"] = { [1] = 4489 },
        ["roles"] = { ["reply"] = true },
    },
    [804114469] = {
        ["english"] = { [1] = "Mrglmrgl Glrggl!" },
        ["text"] = "Мрґлмрґл Ґлрґґл!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [68537573] = {
        ["english"] = { [1] = "Kartak comes for big-tongue meat. Frenzyheart make sure plenty is ready." },
        ["text"] = "Картак прийти по м’ясо великоязика. Несамовите Серце подбати, щоб було багато.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3083868934] = {
        ["english"] = { [1] = "Outland just oozes with magical energy, it's in the very air.  Can you feel it, $N?  I can't think of a place better suited to our race.  Soon the sin'dorei shall have a new land to call our own!" },
        ["text"] = "Позамежжя просто сочиться магічною енергією — вона навіть у повітрі.  Відчуваєш, $N?  Не уявляю кращого місця для нашого народу.  Скоро сін’дорай матимуть нову землю, яку назвуть своєю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1590777943] = {
        ["english"] = { [1] = "So you have returned to help Kum'isha, $r? Do not worry, the pang that you feel in the pit of your stomach is merely your willpower collapsing.$B$BThankfully, you will not need willpower for this collection. I am certain that you will enjoy the trinkets I will have waiting for you upon your return with the item.\010" },
        ["text"] = "Отже, ти повернувся допомогти Кум’іші, $r? Не хвилюйся, біль у животі — це лише твоя сила волі руйнується.$B$BНа щастя, для цього збору сила волі тобі не знадобиться. Певен, тобі сподобаються дрібнички, які чекатимуть на тебе, коли повернешся з предметом.\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3524693972] = {
        ["english"] = { [1] = "James Van Brunt in War Quarter on inner ring." },
        ["text"] = "Джеймс Ван Брант у Бойовому кварталі, на внутрішньому кільці.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2677282847] = {
        ["english"] = { [1] = "Ours is a path for those with an iron will and unfaltering resolve. You seem to possess none of these traits, $c." },
        ["text"] = "Наш шлях — для тих, хто має залізну волю й непохитну рішучість. Схоже, тобі бракує і того, й іншого, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2881215773] = {
        ["english"] = { [1] = "Our work is done. Now we wait on the Alliance to finish theirs before shipping everything over to Silithus." },
        ["text"] = "Нашу роботу завершено. Тепер чекаємо, доки Альянс завершить свою, а тоді все відправлять у Силітус.",
        ["npcs"] = { [1] = 15459 },
        ["roles"] = { ["greeting"] = true },
    },
    [1281317378] = {
        ["english"] = { [1] = "Lady teach you make magic items.  She at inner ring of The Apothecarium." },
        ["text"] = "Пані навчить тебе робити магічні речі.  Вона на внутрішньому кільці Аптекаріуму.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2249514689] = {
        ["english"] = { [1] = "Many are the paths of the Earth Mother.  May your ancestors watch over you $c." },
        ["text"] = "Численні шляхи Матері-Землі.  Нехай предки оберігають тебе, $c.",
        ["npcs"] = { [1] = 2981, [2] = 3034, [3] = 3036, [4] = 3060, [5] = 8142 },
        ["roles"] = { ["greeting"] = true },
    },
    [2615281759] = {
        ["english"] = { [1] = "Mailbox in middle of city, Trade Quarter, upper ring... next to inn." },
        ["text"] = "Поштова скринька в центрі міста, Торговий квартал, верхнє кільце... поруч із заїздом.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3466515711] = {
        ["english"] = { [1] = "Our units are upgraded to Champions, but I can still collect more supplies." },
        ["text"] = "Наші підрозділи вже покращено до чемпіонів, але я все ще можу збирати додаткові припаси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1647209567] = {
        ["english"] = { [1] = "May the winds guide you, $N." },
        ["text"] = "Нехай вітри ведуть тебе, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4107293503] = {
        ["english"] = { [1] = "Many have fallen within Valhalas and their corpses are a testament to the strength of our ways.$B$BWill your bones litter this place of honor and battle as well, $N?" },
        ["text"] = "Багато хто поліг у Валгаласі, і їхні тіла свідчать про силу наших звичаїв.$B$BЧи й твої кістки вкриють це місце честі й битви, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2912332319] = {
        ["english"] = { [1] = "Just another day workin' the kitchen.  Sure gets dull after a while." },
        ["text"] = "Ще один день на кухні.  З часом це страшенно набридає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2849222427] = {
        ["english"] = { [1] = "Only a few spots to get any fishing done around here.  Paxton knows them all and probably a few he won't tell ya about.  Why don't ye go over to Iceflow Lake and see what he will tell ya." },
        ["text"] = "Тут лише кілька місць, де можна нормально порибалити.  Пакстон знає їх усі й, певно, ще кілька, про які не розкаже.  Іди до озера Крижаного Потоку й дізнайся, чим він поділиться.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2078837956] = {
        ["english"] = { [1] = "Nice to see a friendly face. I don't get much chitchat from Apothecary Johaan unless he wants something. He's been out of the grave too long. Someday I'll be like that, I hear. Creepy. Maybe by then I won't care." },
        ["text"] = "Приємно бачити дружнє обличчя. Від аптекаря Джоґаана балачок не дочекаєшся, хіба йому щось треба. Він уже надто довго поза могилою. Кажуть, я теж колись стану таким. Моторошно. Може, тоді мені вже буде байдуже.",
        ["npcs"] = { [1] = 2132 },
        ["roles"] = { ["greeting"] = true },
    },
    [3682153121] = {
        ["english"] = { [1] = "Nice try, but you'll need some more experience before training with me! Back to the trenches!" },
        ["text"] = "Непогана спроба, але тобі треба ще набратися досвіду, перш ніж тренуватися зі мною! Назад у траншеї!",
        ["npcs"] = { [1] = 11017 },
        ["roles"] = { ["greeting"] = true },
    },
    [2074586370] = {
        ["english"] = { [1] = "My troll bruddas be in for some real fun today, mon!" },
        ["text"] = "Моїх трольських братів сьогодні чекають справжні веселощі, друже!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3469646356] = {
        ["english"] = { [1] = "Kael'thas and his felbloods be damned! All we've worked for is gone, but they're fools to think we won't fight back. Already, Lady Liadrin seeks a new source of power for our order. We will not be destroyed so easily." },
        ["text"] = "Прокляття Кель’тасу та його сквернокровним! Усе, заради чого ми працювали, втрачено, але вони дурні, якщо думають, що ми не дамо відсіч. Леді Ліадрін уже шукає нове джерело сили для нашого ордену. Нас не знищити так легко.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1290110075] = {
        ["english"] = { [1] = "Old Town is where you should go if you want to find rogues. It's in the northeast corner of Stormwind." },
        ["text"] = "Якщо шукаєш розбійників, тобі в Старе місто. Воно в північно-східному кутку Штормовію.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2895577632] = {
        ["english"] = { [1] = "Perhaps I should tell you why I am here.$B$BDo you know of the Aspect, Deathwing? Or of his progeny, Nefarian and Onyxia?" },
        ["text"] = "Мабуть, варто пояснити, чому я тут.$B$BТи знаєш про Аспекта Смертекрила? Або про його нащадків Нефаріана й Оніксію?",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [66412345] = {
        ["english"] = { [1] = "Our steady progress in our fight against the Qiraji can be attributed to the diverse help we received from nearly every corner of Kalimdor.$B$BYou need more than just soldiers to fight a war, $N.  Many of the war's unsung heroes are the traders and craftsmen that keep our forces supplied with the resources they need." },
        ["text"] = "Наш сталий поступ у війні проти кіражів став можливим завдяки різноманітній допомозі майже з усіх куточків Калімдору.$B$BДля війни потрібні не лише солдати, $N.  Серед непомітних героїв війни — торговці й ремісники, які постачають нашим силам необхідні ресурси.",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["greeting"] = true },
    },
    [4192619897] = {
        ["english"] = { [1] = "No, you aren't hearing things. I actually do have the voice of a young orc woman. But you listen here, $g boy:girl;, time travel does strange things to a body.$B$BBy the way, it's 250 years." },
        ["text"] = "Ні, тобі не вчувається. У мене справді голос молодої орчині. Але слухай сюди, $g хлопче:дівчино;, подорожі в часі дивно впливають на тіло.$B$BДо речі, це було 250 років тому.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1978559540] = {
        ["english"] = { [1] = "Our Skyguard Aether-tech and her escort is studying the Bash'ir crystal forge.  She needs help!  Go to Bash'ir Landing, find the aether-tech and keep her safe!" },
        ["text"] = "Наш ефіротехнік Небесної Варти та її супровід досліджують кришталеву кузню Баш’іра.  Їй потрібна допомога!  Іди до табору Баш’іра, знайди ефіротехніка й захисти її!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2604947428] = {
        ["english"] = { [1] = "Listen, $r.$b$bIf you're lookin' for a shredder to ride, you'll need to head up into the hills just north there.$b$bThis one's out of commission." },
        ["text"] = "Слухай, $r.$b$bЯкщо шукаєш кришильника, на якому можна покататися, піднімайся на пагорби трохи північніше.$b$bЦей уже не працює.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3180520988] = {
        ["english"] = { [1] = "Rough audience, but you'll win them over. Ready for another shot?" },
        ["text"] = "Публіка сувора, але ти їх підкориш. Готовий спробувати ще раз?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2942894457] = {
        ["english"] = { [1] = "Need some supplies?" },
        ["text"] = "Потрібні припаси?",
        ["npcs"] = { [1] = 9544 },
        ["roles"] = { ["greeting"] = true },
    },
    [357557605] = {
        ["english"] = { [1] = "Maraudon is one of the most sacred sites within Desolace. The great temple/cavern is the burial place of Zaetar, one of two immortal sons born to the demigod, Cenarius. Legend holds that Zaetar and the earth elemental princess, Theradras, sired the misbegotten centaur race. It is said that upon their emergence, the barbaric centaur turned on their father and killed him. Some believe that Theradras, in her grief, trapped Zaetar's spirit within the winding cavern - used its energies for some malign purpose. " },
        ["text"] = "Мародон — одне з найсвятіших місць Спустошища. Великий храм-печера є місцем поховання Заєтара, одного з двох безсмертних синів напівбога Кенарія. За легендою, Заєтар і принцеса-елементаль землі Терадрас породили проклятий рід кентаврів. Кажуть, щойно варварські кентаври з’явилися на світ, вони обернулися проти батька й убили його. Дехто вважає, що Терадрас у своєму горі ув’язнила дух Заєтара в звивистій печері та використовує його енергію для якоїсь лихої мети. ",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1702439995] = {
        ["english"] = { [1] = "Och!  Ye should be careful what ye get enchanted $glad : lass;.  I had me mug enchanted so it wouldn't spill a drop, but now I can't drink from it!  Such a tragedy.  \010\010You be sure to heed me advice when ye see Gimble.  He'll be in his shop right by the Gryphon Master at The Great Forge." },
        ["text"] = "Ох!  Обережніше з тим, що зачаровуєш, $gхлопче : дівчино;.  Я зачарував кухоль, щоб не проливав ні краплі, а тепер не можу з нього пити!  Яка трагедія.  \010\010Не забудь моєї поради, коли побачиш Ґімбла.  Він у своїй крамниці просто біля майстра грифонів на Великому Горні.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [45796311] = {
        ["english"] = { [1] = "Legend claims that in places of extreme conflict, across what is now known as the Plaguelands; clean and holy springs may erupt from the ground. The water from those springs has been named 'Blood of Heroes,' by artisans and commonfolk alike - in honor of those that fell in the war against the Scourge." },
        ["text"] = "Легенда каже, що в місцях особливо жорстоких битв, на землях, які нині звуть Чумозем’ям, із землі можуть пробиватися чисті й святі джерела. Воду з них ремісники й простолюд назвали «Кров’ю героїв» — на честь тих, хто загинув у війні проти Батога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2085998971] = {
        ["english"] = { [1] = "Now that you're attuned to Mount Hyjal, I can teleport you to the Caverns of Time. Just let me know when you are ready." },
        ["text"] = "Тепер, коли ти налаштований на гору Гіджал, я можу телепортувати тебе до Печер Часу. Лише скажи, коли будеш готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2442387064] = {
        ["english"] = { [1] = "Our paths through life intersect only briefly and now is the time for ours to part ways. I consider myself blessed to have spent this time teaching you and now send you along to join paths with your next mentor. Seek out Saru Steelfury of Orgrimmar, he will teach what you need to learn." },
        ["text"] = "Наші життєві шляхи перетинаються лише ненадовго, і тепер настав час розійтися. Для мене було благословенням навчати тебе, а тепер я відправляю тебе до наступного наставника. Шукай Сару Сталеву Лють в Орґріммарі — він навчить тебе потрібного.",
        ["npcs"] = { [1] = 3478 },
        ["roles"] = { ["greeting"] = true },
    },
    [4219629153] = {
        ["english"] = { [1] = "Red security card insertion successful.  Dispensing security level delta data card.\010\01000111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110" },
        ["text"] = "Червону картку безпеки вставлено успішно.  Видача картки даних рівня безпеки «дельта».\010\01000111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4068456352] = {
        ["english"] = { [1] = "Please unlock the courtyard door." },
        ["text"] = "Відімкни, будь ласка, двері у двір.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3275103477] = {
        ["english"] = { [1] = "Oh, hello there.. um, what's your name?$B$BNo matter, what brings you to my home-away-from-home here out in the beautiful countryside?" },
        ["text"] = "О, привіт... е-е, як тебе звати?$B$BНеважливо, що привело тебе до мого другого дому тут, серед цієї прекрасної природи?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [348234788] = {
        ["english"] = { [1] = "Our lord Hydraxis speaks highly of you.  My water is your water, friend." },
        ["text"] = "Наш володар Гідраксіс добре про тебе відгукується.  Моя вода — твоя вода, друже.",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [2932854351] = {
        ["english"] = { [1] = "Our leader, Doom'rel, has ears for the challenge." },
        ["text"] = "Наш ватажок, Дум’рел, почув виклик.",
        ["npcs"] = { [1] = 9035, [2] = 9036 },
        ["roles"] = { ["greeting"] = true },
    },
    [2757988241] = {
        ["english"] = { [1] = "Milk me, John." },
        ["text"] = "Подій мене, Джоне.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [805339569] = {
        ["english"] = { [1] = "Our gunnery instructor is Ansekhwa, the tauren weapon master on the lower central rise of Thunder Bluff." },
        ["text"] = "Наш наставник зі стрілецької зброї — Ансеква, таурен-майстер зброї на нижньому центральному виступі Громового Бескиду.",
        ["npcs"] = { [1] = 11868, [2] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [1315850821] = {
        ["english"] = { [1] = "Metzen's eyes light up with reindeer joy as you sprinkle the dust on him.  He shakes his antlers at you and breathes out a heavy sigh of what sounds like relief.$B$BAround you, magical energy begins to swell.  It would seem that something's about to happen!" },
        ["text"] = "Очі Метцена сяють оленячою радістю, коли ти посипаєш його пилом.  Він трусить рогами й видихає з важким зітханням, схожим на полегшення.$B$BНавколо тебе починає наростати магічна енергія.  Схоже, зараз щось станеться!",
        ["npcs"] = { [1] = 15664 },
        ["roles"] = { ["greeting"] = true },
    },
    [1287374594] = {
        ["english"] = { [1] = "So long as you stay here with us, you da king.  You take off, and some other ogre will take your place.  That's da way of da Gordok!" },
        ["text"] = "Поки ти лишатися тут із нами — ти король.  Підеш — інший огр зайняти твоє місце.  Такий шлях Ґордока!",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [3099923949] = {
        ["english"] = { [1] = "Shoot straight to the northwest section of the Valley of Honor.  There you will find the Hunter's Hall." },
        ["text"] = "Прямуй просто до північно-західної частини Долини Честі.  Там знайдеш Залу мисливців.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [438168349] = {
        ["english"] = { [1] = "Listen to what I have to tell you about our enemy before we start. You don't want to be unprepared while we're out smashing Scourge in the field." },
        ["text"] = "Перш ніж рушимо, вислухай, що я знаю про нашого ворога. Не хочеш же опинитися непідготовленим, коли ми підемо трощити Батіг у полі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2778048570] = {
        ["english"] = { [1] = "Our fate is the doom of all who face the Great Fire." },
        ["text"] = "Наша доля — погибель усіх, хто постає перед Великим Вогнем.",
        ["npcs"] = { [1] = 9039 },
        ["roles"] = { ["greeting"] = true },
    },
    [368239788] = {
        ["english"] = { [1] = "My apologies, $N, but I do not offer instruction to novices. Instead, talk to Milla Fairancora in the Craftsmen's Terrace of Darnassus. She can help you make up for lost time." },
        ["text"] = "Перепрошую, $N, але я не навчаю новачків. Поговори краще з Міллою Фейранкорою на Терасі Ремісників у Дарнасі. Вона допоможе тобі надолужити згаяне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2381319649] = {
        ["english"] = { [1] = "Knowing a little magic comes in handy in this line of work.  Illusions can't always fool everyone, but they're usually good enough to get the job done." },
        ["text"] = "Трохи магії в цій справі ніколи не завадить.  Ілюзіями не завжди вдається обдурити всіх, але зазвичай їх достатньо, щоб зробити свою справу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [205481109] = {
        ["english"] = { [1] = "My plucky companion Bixi Wobblebonk here can train ye in crossbows. If ye're looking for other trainers, though, ye might want to try Woo Ping in Weller's Arsenal within Stormwind." },
        ["text"] = "Моя жвава супутниця Біксі Вобблбонк може навчити тебе користуватися арбалетами. А якщо шукаєш інших наставників, спробуй Ву Пінґа в Арсеналі Веллера у Штормовії.",
        ["npcs"] = { [1] = 11865 },
        ["roles"] = { ["greeting"] = true },
    },
    [257144037] = {
        ["english"] = { [1] = "Looking for some training, eh? I could train you better then anyone in Stormwind but the guard prohibits it. I guess you will have to settle for one of those has beens hanging out around the Barracks or at the Pig and Whistle Tavern in Old Town." },
        ["text"] = "Шукаєш навчання, еге? Я міг би навчити тебе краще за будь-кого в Штормовії, але варта забороняє. Доведеться задовольнитися кимось із тих колишніх мастаків біля казарм або в таверні «Свиня і Свисток» у Старому місті.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1644339199] = {
        ["english"] = { [1] = "Some of us get to avoid military duty.  A good fisherman's always handy... even generals need to eat." },
        ["text"] = "Декому з нас удається уникнути військової служби.  Добрий рибалка завжди корисний... навіть генералам треба їсти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [357465390] = {
        ["english"] = { [1] = "Our caravans go out 'bout twice a day, but I'll be damned if the Scourge haven't gone out of their way to stop Didier and his mules from getting shipments to the front lines. Craziest thing I've ever seen. If only we had the heroic adventurin' types to help protect the shipments..." },
        ["text"] = "Наші каравани виходять десь двічі на день, але клятий Батіг аж зі шкури пнеться, щоб Дідьє та його мули не довозили вантажі на передову. Найбожевільніше, що я бачив. От якби знайшлися героїчні шукачі пригод, які могли б захищати каравани...",
        ["npcs"] = { [1] = 16283 },
        ["roles"] = { ["greeting"] = true },
    },
    [527727816] = {
        ["english"] = { [1] = "Our ancestors teach us that while the individual must be strong, there is safety in numbers.  Do you wish to defend the honor of Thunder Bluff by organizing a guild?" },
        ["text"] = "Наші предки вчать: людина має бути сильною, але в гурті безпечніше.  Хочеш захищати честь Громового Бескиду, створивши гільдію?",
        ["npcs"] = { [1] = 5054 },
        ["roles"] = { ["greeting"] = true },
    },
    [2733932410] = {
        ["english"] = { [1] = "So good of you to speak with me.  Please, help the Alliance in any way that you can." },
        ["text"] = "Дуже добре, що ти зі мною заговорив.  Будь ласка, допомагай Альянсу всім, чим зможеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [776344163] = {
        ["english"] = { [1] = "Look no further than the Lion's Pride Inn in Goldshire.  With a wide selection of ales and soft down beds you, couldn't ask for a better place to rest." },
        ["text"] = "Кращого місця за таверну «Гордість Лева» в Золотозем’ї не знайти.  Широкий вибір елів і м’які пухові ліжка — що ще треба для доброго відпочинку?",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3290240769] = {
        ["english"] = { [1] = "Oh hi! My name's Sarah. What can I do for you?" },
        ["text"] = "О, привіт! Мене звати Сара. Чим можу допомогти?",
        ["npcs"] = { [1] = 7868 },
        ["roles"] = { ["greeting"] = true },
    },
    [3427071178] = {
        ["english"] = { [1] = "It's simple really. Allow me to summarize...\010" },
        ["text"] = "Усе просто. Дозволь підсумувати...\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3483120456] = {
        ["english"] = { [1] = "Only this book survived the cataclysm that destroyed their world.  Those proud and foolish men who thought to control a cosmic being of untold power.$B$BWould you, the possessor of the codex, do the same?$B$BHave you devised a foolproof method to summon forth Murmur, or any of the other entities cautiously whispered of in these unhallowed pages?$B$BWe shall see." },
        ["text"] = "Лише ця книга пережила катаклізм, що знищив їхній світ.  Ті горді й нерозумні люди думали, що здатні контролювати космічну істоту незбагненної сили.$B$BЧи вчиниш ти, власник кодексу, так само?$B$BЧи вигадав безпомилковий спосіб прикликати Мурмура або будь-яку іншу сутність, про яку пошепки згадують ці нечестиві сторінки?$B$BПобачимо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3907209069] = {
        ["english"] = { [1] = "Of course I do not have the shard. That would be asinine. I walk amongst savages in this cursed land! I cannot take five steps without some crazed orc or human trying to thrust a sharp stick into my hide. At any given time you could very well be speaking to my ghostly spirit.$B$BAnyhow... I hid it.$B$BGo on... ask me where." },
        ["text"] = "Звісно, уламка в мене немає. Це було б ідіотизмом. Я ходжу серед дикунів у цій проклятій землі! Не можу пройти й п’яти кроків, щоб якийсь навіжений орк чи людина не спробували встромити в мене гостру палицю. Цілком можливо, що будь-якої миті ти вже говоритимеш із моїм примарним духом.$B$BТак чи інакше... я його сховав.$B$BНу ж бо... спитай де.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [834122185] = {
        ["english"] = { [1] = "Of the $1998w copper bars that we'll need, we have $2018w. The number for tin bar collections sits at $2005w out of $2006w needed. And, there have been $2008w of $2009w mithril bars smelted for the cause." },
        ["text"] = "Із потрібних нам $1998w мідних зливків ми маємо $2018w. Олов’яних зливків зібрано $2005w із потрібних $2006w. А для справи вже виплавлено $2008w із $2009w мітрилових зливків.",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [1761790862] = {
        ["english"] = { [1] = "My answer - Nozdormu." },
        ["text"] = "Моя відповідь — Ноздорму.",
        ["npcs"] = { [1] = 4489 },
        ["roles"] = { ["reply"] = true },
    },
    [2918395124] = {
        ["english"] = { [1] = "Only the renowned Doctor Gregory Victor can improve your skill now.  He can be found in Arathi Highlands at Hammerfall." },
        ["text"] = "Тепер твою майстерність може підвищити лише знаний доктор Ґреґорі Віктор.  Знайдеш його в Павшому Молоті у Верховинах Араті.",
        ["npcs"] = { [1] = 2798, [2] = 3373, [3] = 4591, [4] = 5759, [5] = 5939, [6] = 5943 },
        ["roles"] = { ["greeting"] = true },
    },
    [359166817] = {
        ["english"] = { [1] = "No, I'm the intellectual one, and I am not to be taken lightly.  I could brew a healing potion from dishwater and dandelions, although that's not something I'll show you!$b$bAnyhow, if you'd like to make a purchase, please speak with Patricia." },
        ["text"] = "Ні, я тут інтелектуал, і мене не варто недооцінювати.  Я можу зварити цілюще зілля з помиїв і кульбаб, хоча цього тобі не покажу!$b$bЯкщо хочеш щось купити, поговори з Патрісією.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [871012592] = {
        ["english"] = { [1] = "Need your blade sharpened, or perhaps a new weapon? Better safe than sorry..." },
        ["text"] = "Заточити клинок чи, може, потрібна нова зброя? Краще перестрахуватися...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3818242857] = {
        ["english"] = { [1] = "Maraudon is located in the middle of the western coast of Desolace, in the Valley of Spears." },
        ["text"] = "Мародон розташований посеред західного узбережжя Спустошища, у Долині Списів.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [3740492812] = {
        ["english"] = { [1] = "So what did Ragnaros do next?" },
        ["text"] = "І що Раґнарос зробив далі?",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["reply"] = true },
    },
    [3314228221] = {
        ["english"] = { [1] = "Let me out of here, $r!" },
        ["text"] = "Випусти мене звідси, $r!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4121756730] = {
        ["english"] = { [1] = "Let's find out." },
        ["text"] = "Зараз дізнаємося.",
        ["npcs"] = { [1] = 15471 },
        ["roles"] = { ["reply"] = true },
    },
    [3959871073] = {
        ["english"] = { [1] = "My purpose is to regulate access to the Uldum complex for the Creators.  I allow entry into the compound only when the solicitor exhibits for access the proper sequencing discs.$B$BYour disc set currently does not contain the Plates of Uldum, the primary prerequisite for entry.  Access is not granted unless the Plates of Uldum are present." },
        ["text"] = "Моє призначення — регулювати доступ Творців до комплексу Ульдум.  Я дозволяю вхід лише тоді, коли прохач демонструє належні диски послідовності.$B$BУ твоєму наборі дисків наразі немає Плит Ульдуму — головної передумови для входу.  Без Плит Ульдуму доступ не надається.",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["greeting"] = true },
    },
    [3807290168] = {
        ["english"] = { [1] = "My scepter... After so many years... You have recovered it! You shall truly be the savior of this place...$B$BPlease listen to me carefully, $N. The head and the rod of the scepter may only be reunited into one at the Stone of Maraudon." },
        ["text"] = "Мій скіпетр... Через стільки років... Ти повернув його! Ти справді станеш спасителем цього місця...$B$BБудь ласка, слухай уважно, $N. Голову й древко скіпетра можна з’єднати воєдино лише біля Каменя Мародона.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [389624011] = {
        ["english"] = { [1] = "Only champions of Orgrimmar may purchase what I have to offer." },
        ["text"] = "Лише чемпіони Орґріммара можуть купувати мої товари.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2614076725] = {
        ["english"] = { [1] = "Leather skins? Yes, I just received some information on that. It would appear that of $2067w heavy leather needed, the Horde has collected $2066w. Also, $2070w out of $2071w thick leather and $2073w out of $2074w rugged leather have been gathered." },
        ["text"] = "Шкіри? Так, я щойно отримав свіжі відомості. Схоже, з потрібних $2067w важкої шкіри Орда зібрала $2066w. Також зібрано $2070w із $2071w щільної шкіри та $2073w із $2074w грубої шкіри.",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [2428698896] = {
        ["english"] = { [1] = "Rogues in building on outer ring of Rogues' Quarter." },
        ["text"] = "Розбійники в будівлі на зовнішньому кільці Кварталу розбійників.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [455764626] = {
        ["english"] = { [1] = "Oh, a fellow Physician. I would be glad to teach you anything that would aid your journeys." },
        ["text"] = "О, колега-лікар. Я охоче навчу тебе всього, що допоможе у мандрах.",
        ["npcs"] = { [1] = 2327 },
        ["roles"] = { ["greeting"] = true },
    },
    [4239782293] = {
        ["english"] = { [1] = "It's my job to ensure that this whole assault runs like clockwork.$B$BHigh Tinker Mekkatorque is out in the field now, but he's scheduled to come back to get some more troops any time now.  $B$BHe's never late, so just stick around and he'll be here." },
        ["text"] = "Моє завдання — простежити, щоб увесь цей наступ працював як годинник.$B$BВерховний механік Меккаторк зараз у полі, але незабаром має повернутися по нові війська.  $B$BВін ніколи не запізнюється, тож просто зачекай — він скоро буде.",
        ["npcs"] = { [1] = 11390 },
        ["roles"] = { ["greeting"] = true },
    },
    [3068764424] = {
        ["english"] = { [1] = "Lemme outta here, mon!" },
        ["text"] = "Випусти мене звідси, друже!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1254410499] = {
        ["english"] = { [1] = "On behalf of all of Ogri'la, we give you thanks for your efforts, $N.$B$B<Chu'a'lor's left head nods while his right head smiles at you.>$B$BAnd do not forget that by helping us here you are also helping to protect our brethren down below whom you have become like a $g king : queen; to." },
        ["text"] = "Від імені всієї Оґріл’ли дякуємо тобі за твої зусилля, $N.$B$B<Ліва голова Чу’а’лора киває, а права усміхається тобі.>$B$BІ не забувай: допомагаючи нам тут, ти також захищаєш наших братів унизу, для яких ти став наче $g король : королева;.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1006740154] = {
        ["english"] = { [1] = "Oh my gosh! Keep your voice down, $N! What? Are you trying to get us killed?!$B$BOf course I know who you are! Who in the Alliance doesn't know the name, $N?!$B$BSay, what do you think of my jumpbot? She's based off of the mechagnome design. Sleek and aerodynamic!" },
        ["text"] = "О боже! Тихіше, $N! Що, хочеш нас убити?!$B$BЗвісно, я знаю, хто ти! Хто в Альянсі не знає імені $N?!$B$BДо речі, як тобі мій стрибобот? Вона створена за конструкцією механогнома. Струнка й аеродинамічна!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4131839429] = {
        ["english"] = { [1] = "Scarlet Monastery" },
        ["text"] = "Багряний монастир",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [4099437951] = {
        ["english"] = { [1] = "Perhaps. Go now, young one. Seek council with the Warchief. He will surely wish to know of your discovery." },
        ["text"] = "Можливо. Іди, юначе. Порадься з Вождем. Він напевно захоче знати про твоє відкриття.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [438438082] = {
        ["english"] = { [1] = "Life is a struggle, and the saying that which does not kill you makes you stronger is not always true.  Sometimes wounds act slowly, which is why we have bandages.  Pand Stonebinder of the Spirit Rise can teach you the art of First Aid." },
        ["text"] = "Життя — це боротьба, і приказка «що нас не вбиває, робить нас сильнішими» не завжди правдива.  Деякі рани діють повільно, тому й існують бинти.  Панд Каменев’яз із Виступу духів може навчити тебе мистецтва Першої допомоги.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [37875272] = {
        ["english"] = { [1] = "Look for Tarshaw Jaggedscar in the barracks on the east side of town." },
        ["text"] = "Шукай Таршоу Рваний Шрам у казармах на східному боці міста.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3916358805] = {
        ["english"] = { [1] = "Let Marshal Windsor know that I am ready." },
        ["text"] = "Передай маршалу Віндзору, що я готовий.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1920061261] = {
        ["english"] = { [1] = "Perhaps one day, your contributions to the Alliance will be as great as the heroes you have seen this day. Honor them, $N." },
        ["text"] = "Можливо, одного дня твій внесок в Альянс буде таким самим великим, як внесок героїв, яких ти сьогодні бачив. Вшануй їх, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2585796403] = {
        ["english"] = { [1] = "Once you have built the device, you simply activate the device to be whisked away to lovely Gadgetzan!    Nearly everyone who has used the device has arrived on the pad here looking just the way they did when they began!    There have been some reported problems with transportees being replaced by their evil selves from an alternate universe, but I'm sure we will have that worked out soon..." },
        ["text"] = "Коли збудуєш пристрій, просто активуй його — і тебе миттю перенесе до чарівного Пристробляску!    Майже всі, хто ним користувався, прибули на платформу тут у тому самому вигляді, в якому вирушили!    Були, щоправда, повідомлення, що деяких мандрівників замінили їхні злі двійники з альтернативного всесвіту, але ми точно скоро це виправимо...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1900939617] = {
        ["english"] = { [1] = "Most of my brethren are disdainful of the Horde's \"barbaric\" ways, and I once counted myself among them. When I was first ordered to this somewhat humid and... fragrant place, I cursed my lot in life.$b$bDuring my studies, however, I grew to appreciate my surroundings. It has a certain charm, don't you think?$b$b...you wouldn't be interested in my studies, of course, not being a mage yourself." },
        ["text"] = "Більшість моїх побратимів зневажає «варварські» звичаї Орди, і я колись був серед них. Коли мене вперше відрядили в це трохи вологе й... пахуче місце, я проклинав свою долю.$b$bТа в процесі досліджень я навчився цінувати ці околиці. Є в них певний шарм, хіба ні?$b$b...звісно, мої дослідження тобі навряд чи цікаві, адже ти не маг.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4187685329] = {
        ["english"] = { [1] = "Once the capital city of the Dark Iron dwarves, this volcanic labyrinth now serves as the seat of power for Ragnaros the Firelord. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain. Obsessed with defeating Nefarian and his draconic minions, Ragnaros will go to any extreme to achieve final victory.  \010" },
        ["text"] = "Колись столиця дворфів Темного Заліза, цей вулканічний лабіринт тепер є осередком влади Раґнароса Володаря Вогню. Раґнарос розкрив таємницю створення життя з каменю й планує збудувати армію невпинних големів, щоб завоювати всю Чорнокамінну гору. Одержимий перемогою над Нефаріаном і його драконячими прислужниками, Раґнарос піде на все заради остаточної перемоги.  ",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2118359] = {
        ["english"] = { [1] = "Oh, goody, something else to do while I wait! You're a real life-saver, $N!" },
        ["text"] = "О, чудово, ще одна справа, поки я чекаю! Ти справжній рятівник, $N!",
        ["npcs"] = { [1] = 1466 },
        ["roles"] = { ["greeting"] = true },
    },
    [1499354791] = {
        ["english"] = { [1] = "Once I welcomed darkness, for it was the sister of night. Now it is dark all the time, even during the day, and the forests cry out for sustenance. Unless we act soon, this spreading blight will cover the world." },
        ["text"] = "Колись я вітав темряву, бо вона була сестрою ночі. Тепер темно постійно, навіть удень, а ліси волають про поживу. Якщо ми не діятимемо негайно, ця пошесть накриє весь світ.",
        ["npcs"] = { [1] = 7948 },
        ["roles"] = { ["greeting"] = true },
    },
    [627294121] = {
        ["english"] = { [1] = "Make it quick, $c - we've got a war to fight here, or hadn't you noticed?" },
        ["text"] = "Швидше, $c — тут війна йде, якщо ти не помітив!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2850341663] = {
        ["english"] = { [1] = "Make it quick, $r. I am weary and have no time for pleasantries.." },
        ["text"] = "Швидше, $r. Я виснажений і не маю часу на люб’язності..",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4248202287] = {
        ["english"] = { [1] = "Once a great city of the night elves, the Highborne once ruled there, practicing great and powerful arcane magics. They are cursed now, haunting the lands, and their ruined city has been victimized by the Spitelash naga. I understand that the naga search the ruins for powerful Highborne artifacts." },
        ["text"] = "Колись це було величне місто нічних ельфів, де правили Високородні й практикували могутню арканічну магію. Тепер вони прокляті й блукають цими землями, а їхнє зруйноване місто стало здобиччю наґів Злобного Батога. Кажуть, наґи шукають у руїнах могутні артефакти Високородних.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["greeting"] = true },
    },
    [3530675539] = {
        ["english"] = { [1] = "Look for the eastern Zeppelin Landing Tower outside of the city to the southeast." },
        ["text"] = "Шукай східну вежу причалу дирижаблів за містом, на південний схід.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2844647648] = {
        ["english"] = { [1] = "Look for Sayoc and Hanashi at the Valley of Honor inside Arms of Legend.  Watch your tongue around them or Sayoc may decide to give a piece of you as a snack to Grinning Dog." },
        ["text"] = "Шукай Сайока й Ганаші в «Зброї легенд» у Долині Честі.  Стеж за язиком поруч із ними, бо Сайок іще вирішить згодувати шматок тебе Вишкіреному Псові.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [185854281] = {
        ["english"] = { [1] = "Keep your voice down, stranger. You do not want to disrupt the Master's meditations." },
        ["text"] = "Говори тихіше, незнайомцю. Не варто переривати медитацію Майстра.",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [1729072959] = {
        ["english"] = { [1] = "Lucan Cordell has a small shop on the canal by the Stockade. I am sure he will be able to teach you the art of enchanting." },
        ["text"] = "Лукан Корделл має невеличку крамницю біля каналу поруч із В’язницею. Упевнений, він зможе навчити тебе мистецтва зачарування.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [206396937] = {
        ["english"] = { [1] = "On the east side of Razor Hill, behind the barracks is where you will find Dhugru Gorelust." },
        ["text"] = "На східному боці Колючого Пагорба, за казармами, знайдеш Дуґру Кровожада.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [4070684272] = {
        ["english"] = { [1] = "On the cooked goods front it would appear that we've managed to collect and store away $2092w rainbow fin albacore, out of $2093w requested. Additionally, right now we have in $2098w of $2099w roast raptor and $2101w out of $2103w spotted yellowtail in cold storage." },
        ["text"] = "Щодо готових припасів: схоже, ми зібрали й склали $2092w альбакора райдужного плавця з потрібних $2093w. Крім того, у холодильниках зараз $2098w із $2099w смаженого раптора та $2101w із $2103w плямистого жовтохвоста.",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [224651781] = {
        ["english"] = { [1] = "On duty. GO. AWAY." },
        ["text"] = "Я на службі. ІДИ. ГЕТЬ.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1769018396] = {
        ["english"] = { [1] = "So... the Earthen were made out of stone?" },
        ["text"] = "Отже... земельників зробили з каменю?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [2123076651] = {
        ["english"] = { [1] = "Nothing quite like the feel of something dead rubbing up against you.  You can find Shelene Rhobart by heading southeast on the road out of town, and then going east at the intersection.  She's at a small camp there not too far along the road." },
        ["text"] = "Ніщо не зрівняється з відчуттям, коли щось мертве треться об тебе.  Щоб знайти Шелену Робарт, іди дорогою на південний схід від міста, а на перехресті поверни на схід.  Вона в невеликому таборі неподалік дороги.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [589158080] = {
        ["english"] = { [1] = "Omarion, I am not a craftsman. Can you still help me?" },
        ["text"] = "Омаріоне, я не ремісник. Ти все одно можеш мені допомогти?",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [1377795578] = {
        ["english"] = { [1] = "Mau'ari know why you seek her out...$B$BBring me da E'ko you find in the world, an' I can transform it for you." },
        ["text"] = "Мау’арі знати, чому ти її шукати...$B$BПринось мені е’ко, що знайдеш у світі, і я перетворю його для тебе.",
        ["npcs"] = { [1] = 10307 },
        ["roles"] = { ["greeting"] = true },
    },
    [503276868] = {
        ["english"] = { [1] = "Look for Innkeeper Pala in the building just south of the Thunder Bluff Bank on the lower rise." },
        ["text"] = "Шукай господиню заїзду Палу в будівлі трохи південніше банку Громового Бескиду на нижньому виступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1694285182] = {
        ["english"] = { [1] = "My teachings would be too advanced for you at this stage. If you wish to learn more of potions, speak with Tel'Athir here instead." },
        ["text"] = "На цьому етапі мої уроки були б для тебе надто складними. Якщо хочеш дізнатися більше про зілля, поговори тут із Тел’Атіром.",
        ["npcs"] = { [1] = 5499 },
        ["roles"] = { ["greeting"] = true },
    },
    [3925258928] = {
        ["english"] = { [1] = "May Cenarius watch over you, $g brother : sister;.$B$BI am Tajarri, and I am a sworn protector of this shrine.  It is my honor to serve Keeper Remulos as a warden of this sacred land." },
        ["text"] = "Нехай Кенарій оберігає тебе, $g брате : сестро;.$B$BЯ Таджаррі, присягла захищати це святилище.  Для мене честь служити хранителю Ремулу й охороняти цю священну землю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1246919100] = {
        ["english"] = { [1] = "See, the Venture Company's new shredder is better than my latest, from the interchangeable hands to the control grips! My boss has given me a pretty strict deadline, but my boys and I couldn't come up with anything.$b$bNothing was working, so we decided to \"borrow\" one of their prototypes. I sent Wizzlecrank to the Sludge Fen to steal one, but he hasn't gotten back yet!" },
        ["text"] = "Бачиш, новий кришильник Торгової Компанії кращий за мою останню модель — від змінних рук до руків’їв керування! Бос поставив мені жорсткий термін, але ми з хлопцями нічого не змогли вигадати.$b$bНічого не працювало, тож ми вирішили «позичити» один із їхніх прототипів. Я послав Віззлкранка до Мулової Трясовини поцупити один, але він досі не повернувся!",
        ["npcs"] = { [1] = 3442 },
        ["roles"] = { ["greeting"] = true },
    },
    [30296914] = {
        ["english"] = { [1] = "Kalaran, I have misplaced my torch. I require another." },
        ["text"] = "Каларане, я десь загубив свій смолоскип. Мені потрібен інший.",
        ["npcs"] = { [1] = 8479 },
        ["roles"] = { ["reply"] = true },
    },
    [1450027568] = {
        ["english"] = { [1] = "Lemme give you some advice: Never trust a gnome." },
        ["text"] = "Дам тобі пораду: ніколи не довіряй гному.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3687216] = {
        ["english"] = { [1] = "Okay, well... don't get cocky! Since you have demonstrated  your competence though, we may now begin!" },
        ["text"] = "Гаразд... тільки не зазнавайся! Та раз ти вже довів свою вправність, можемо починати!",
        ["npcs"] = { [1] = 5157 },
        ["roles"] = { ["greeting"] = true },
    },
    [3706116988] = {
        ["english"] = { [1] = "Maybe you do better at getting back prized Gordok relic from creepy Highborne prince than da old boss did!" },
        ["text"] = "Може, ти краще за старого боса повернути цінну реліквію Ґордока від моторошного принца Високородних!",
        ["npcs"] = { [1] = 14325 },
        ["roles"] = { ["greeting"] = true },
    },
    [4051574009] = {
        ["english"] = { [1] = "Ok, let me get this straight. You put the scepter shard entrusted to your Flight by Anachronos on a minnow of your own making and now you expect me to build an... an arcanite buoy or something... to force your minnow out of hiding? AND potentially incur the wrath of an Elemental Lord? Did I miss anything? Perhaps I am to do this without any clothes on, during a solar eclipse, on a leap year?", [2] = "Ok, let me get this straight. You put the scepter shard entrusted to your Flight by Anachronos on a minnow of your own making and now you expect me to build an... an arcanite buoy or something... to force your minnow out of hiding? AND potentially incur the wrath of an Elemental Lord? Did I miss anything? Perhaps I am to do this without any clothes on, during a solar eclipse, on a leap year?\010" },
        ["text"] = "Гаразд, перевіримо, чи я правильно зрозумів. Ти поклав уламок скіпетра, довірений твоїй Зграї Анахроносом, на власноруч створеного малька, а тепер чекаєш, що я збудую... е-е, арканітовий буй чи щось таке... щоб виманити твого малька зі схованки? І при цьому, можливо, накличу гнів Володаря Стихій? Я нічого не пропустив? Може, ще треба зробити це голяка, під час сонячного затемнення, у високосний рік?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [3538153689] = {
        ["english"] = { [1] = "Kel'Thuzad has put forth considerable effort in attempting to reform the staff. The pieces were once scattered across this world, from Kalimdor to the South Seas. I myself held twenty of the pieces at one point in time - until they were stolen from me by Kel'Thuzad's minions. It is why I am here." },
        ["text"] = "Кел’Тузад доклав чимало зусиль, намагаючись відновити посох. Колись його частини були розкидані по всьому світу — від Калімдору до Південних морів. У певний час я сам зберігав двадцять частин, доки їх не викрали в мене прислужники Кел’Тузада. Саме тому я тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2887755178] = {
        ["english"] = { [1] = "Ok!" },
        ["text"] = "Гаразд!",
        ["npcs"] = { [1] = 10637 },
        ["roles"] = { ["reply"] = true },
    },
    [864695618] = {
        ["english"] = { [1] = "Let me train you in the ways of the hunter." },
        ["text"] = "Дозволь навчити тебе мистецтва мисливця.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1906541325] = {
        ["english"] = { [1] = "Look for Yelmak's Alchemy and Potions.  Find it in the middle of The Drag, west of the huge tree." },
        ["text"] = "Шукай «Алхімію та зілля Єлмака».  Вона посеред Хитрого провулка, на захід від величезного дерева.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [4122848320] = {
        ["english"] = { [1] = "Members only, scrub!\010" },
        ["text"] = "Лише для членів, салаго!\010",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["greeting"] = true },
    },
    [3958562705] = {
        ["english"] = { [1] = "Please tell me more about the hippogryphs." },
        ["text"] = "Розкажи мені більше про гіпогрифів.",
        ["npcs"] = { [1] = 7763 },
        ["roles"] = { ["reply"] = true },
    },
    [1713369261] = {
        ["english"] = { [1] = "John, honey, where are you?" },
        ["text"] = "Джоне, любий, де ти?",
        ["npcs"] = { [1] = 10778 },
        ["roles"] = { ["greeting"] = true },
    },
    [4049381578] = {
        ["english"] = { [1] = "Mudskunks are a particularly smelly breed of fish that likes tropical waters.  The Zulian Mudskunk - the smelliest of them all, can only be found in the steamy waters of Zul'Gurub.$B$BThe Zulian Mudskunks are what I believe attracted Gahz'ranka to the place, though trolls will probably tell you he's one of their gods...$B$BBelieve what you like, but mark me - fill one of my lures with Zulian Mudskunks and that old boy will come, for sure!" },
        ["text"] = "Мулоскунси — особливо смердючий вид риби, що полюбляє тропічні води.  Зулійський мулоскунс — найсмердючіший з усіх — водиться лише в парких водах Зул’Ґуруба.$B$BЯ вважаю, що саме зулійські мулоскунси привабили сюди Ґаз’ранку, хоча тролі, певно, скажуть, що він один із їхніх богів...$B$BВір у що хочеш, але запам’ятай: наповни одну з моїх принад зулійськими мулоскунсами — і цей старий точно припливе!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [733564836] = {
        ["english"] = { [1] = "Ohh, that. See, there's been nuthin' but orc grog around camp lately.$b$bOrc grog doesn't seem to agree with me, if ya know what I mean...." },
        ["text"] = "О, це. Розумієш, останнім часом у таборі немає нічого, крім орчого ґроґу.$b$bА орчий ґроґ мені, схоже, не дуже підходить, якщо розумієш, про що я....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [326973066] = {
        ["english"] = { [1] = "Lots to do, lots to do! The Union's given us deadlines and they're not the sort you want to miss!" },
        ["text"] = "Справ багато, дуже багато! Профспілка встановила строки, а їх краще не пропускати!",
        ["npcs"] = { [1] = 3442 },
        ["roles"] = { ["greeting"] = true },
    },
    [1862345123] = {
        ["english"] = { [1] = "My father was slain by the filth that inhabits the cauldron. My pleas for assistance to the Stormwind magistrate fell on deaf ears. Nay, they want not to admit that this part of the world even exists, let alone send their precious military in to administer justice.$B$BI seek vengeance, $r, plain and simple. Is there a more passionate cause in this world?" },
        ["text"] = "Мого батька вбила погань, що живе біля казана. Мої прохання про допомогу магістрат Штормовію проігнорував. Ні, вони навіть визнавати не хочуть, що ця частина світу існує, не те що послати своє дорогоцінне військо вершити правосуддя.$B$BЯ прагну помсти, $r, простої й чистої. Хіба є у світі палкіша мета?",
        ["npcs"] = { [1] = 8479 },
        ["roles"] = { ["greeting"] = true },
    },
    [2404337225] = {
        ["english"] = { [1] = "Moa'ki Harbor is blessed with two great sea turtles: Walker of Waves and Green Island. They swim between Unu'pe and Kamagua." },
        ["text"] = "Гавань Моа’кі благословенна двома великими морськими черепахами: Ходаком Хвиль і Зеленим Островом. Вони плавають між Уну’пе та Камагуа.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2280115155] = {
        ["english"] = { [1] = "Mace" },
        ["text"] = "Булава",
        ["npcs"] = { [1] = 2704, [2] = 11866, [3] = 11867, [4] = 11868, [5] = 11870, [6] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [2353448092] = {
        ["english"] = { [1] = "It's only a matter of time before the plague overtakes New Avalon." },
        ["text"] = "Лише питання часу, коли чума поглине Новий Авалон.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3417188045] = {
        ["english"] = { [1] = "Just a small songbook that I thought you might like to have.  It contains the lyrics to a song known as the Lament of the Highborne; the one that Lady Sylvanas glamoured from the air." },
        ["text"] = "Невеличкий пісенник, який, гадаю, тобі сподобається.  У ньому записані слова пісні, відомої як «Плач Високородних», — тієї самої, яку леді Сильвана начарувала просто з повітря.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1539160985] = {
        ["english"] = { [1] = "Oh, no!  My Fei Fei would never take someone else's things!  He's a good dog... he just needs attention sometimes.  If you give him a treat, then you see!" },
        ["text"] = "О ні!  Мій Фей-Фей ніколи не візьме чужого!  Він хороший пес... просто іноді йому бракує уваги.  Дай йому ласощі — сам побачиш!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [642246477] = {
        ["english"] = { [1] = "Oh, you mean Johnson?  I heard he's in hiding." },
        ["text"] = "О, ти про Джонсона?  Чув, він ховається.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3038229974] = {
        ["english"] = { [1] = "Old king got dead?  That's unpossible!" },
        ["text"] = "Старий король помер?  Так не буває!",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [2315757128] = {
        ["english"] = { [1] = "Kel'Thuzad" },
        ["text"] = "Кел’Тузад",
        ["npcs"] = { [1] = 4488 },
        ["roles"] = { ["reply"] = true },
    },
    [709396467] = {
        ["english"] = { [1] = "Oh, the tram, the tram...  everyone wants to ride the tram.  What happened to the good ol' days of flying on the back of a gryphon, gripping the saddle for dear life as you flew up high in the sky above?  \010\010Bah!  You go take the tram then... it's over in Tinker Town with the rest of the gnomish contraptions." },
        ["text"] = "О, трамвай, трамвай... усі хочуть їхати трамваєм.  Куди поділися старі добрі часи, коли літали на спині грифона, вчепившись у сідло щосили, високо-високо над землею?  \010\010Ех!  Ну їдь уже трамваєм... він у Місті Механіків разом з іншими гномськими штукенціями.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [562825703] = {
        ["english"] = { [1] = "Oh, thank you!  I have been trapped in this nightmare for so long..." },
        ["text"] = "О, дякую!  Я так довго був ув’язнений у цьому кошмарі...",
        ["npcs"] = { [1] = 11064 },
        ["roles"] = { ["greeting"] = true },
    },
    [1247490984] = {
        ["english"] = { [1] = "Oh, you're looking for Springspindle Fizzlegear then.  Why that little gnome and his gadgets...  Let me tell you, if you're going to his shop in Tinker Town, keep your hands to yourself and don't pet any of his mechanical sheep!  \010\010Exploding sheep... now why would you even make such a thing!?" },
        ["text"] = "О, тоді ти шукаєш Спрінґспіндла Фіззлґіра.  Ох, цей маленький гном і його пристрої...  Якщо підеш до його крамниці в Місті Механіків, тримай руки при собі й не гладь механічних овець!  \010\010Вибухові вівці... навіщо взагалі таке створювати!?",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1651850983] = {
        ["english"] = { [1] = "Oh, most excellent!  That was great fun, was it not?  Little by little I've been cursing more of those disgusting Lost Ones.  Soon enough I'll be ready to try it on the draenei!" },
        ["text"] = "О, чудово!  Було весело, правда?  Потроху я проклинаю дедалі більше цих огидних Загублених.  Скоро буду готовий випробувати це на дренеях!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3057661865] = {
        ["english"] = { [1] = "Make it quick... the fighting here is grim. I need to stay sharp." },
        ["text"] = "Швидше... тут точаться жорстокі бої. Я мушу залишатися напоготові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3530517018] = {
        ["english"] = { [1] = "Polar Gloves." },
        ["text"] = "Полярні рукавиці.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [4091499529] = {
        ["english"] = { [1] = "Leave it to the dwarves to send a mining specialist from Ironforge to tell us how to mine.  How hard is it to take a pick and chip away at some rock?  Well, since he's here, he's probably the one you should see anyhow.  His name is Gelman and he resides over in the Dwarven District." },
        ["text"] = "Звісно ж, дворфи прислали зі Залізогарта фахівця з гірництва, щоб навчити нас видобувати руду.  Невже так важко взяти кайло й відколювати камінь?  Та раз він уже тут, мабуть, тобі варто звернутися саме до нього.  Його звати Ґелман, він мешкає у Дворфійському районі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3751421594] = {
        ["english"] = { [1] = "Lee Brown spends the whole day fishing up by Crystal Lake.  He's probably got some stories to tell and some tips he could teach you." },
        ["text"] = "Лі Браун цілими днями рибалить біля Кришталевого озера.  Напевно, має кілька історій і порад, якими міг би з тобою поділитися.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [461871798] = {
        ["english"] = { [1] = "Oh, if I only had a tree branch to hold up in front of me. The guards would never see me then." },
        ["text"] = "О, якби ж у мене була гілка дерева, щоб тримати перед собою. Варта тоді точно мене не побачила б.",
        ["npcs"] = { [1] = 7766 },
        ["roles"] = { ["greeting"] = true },
    },
    [2254010843] = {
        ["english"] = { [1] = "Oh, I'm sorry, but you know more about leather than I do at this point. Talk to Faldron over there if you wish to learn more." },
        ["text"] = "О, вибач, але на цьому етапі ти вже знаєш про шкіру більше за мене. Якщо хочеш вчитися далі, поговори он із Фалдроном.",
        ["npcs"] = { [1] = 11083 },
        ["roles"] = { ["greeting"] = true },
    },
    [3166432346] = {
        ["english"] = { [1] = "Sorta busy." },
        ["text"] = "Трохи зайнятий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3598435017] = {
        ["english"] = { [1] = "Our master Malfurion remains lost in the Dreaming, $c.  His is the light of a beacon that shows the way for us, and we must do everything in our power to preserve that light." },
        ["text"] = "Наш володар Малфуріон досі загублений у Сновидінні, $c.  Він — світло маяка, що вказує нам шлях, і ми мусимо зробити все можливе, щоб зберегти це світло.",
        ["npcs"] = { [1] = 3602, [2] = 9465 },
        ["roles"] = { ["greeting"] = true },
    },
    [1872930688] = {
        ["english"] = { [1] = "Nope, still not done with these repairs.  Shouldn't be long though." },
        ["text"] = "Ні, ремонт іще не завершено.  Але вже недовго.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1320665870] = {
        ["english"] = { [1] = "Oh, a priest is it?  Well good ol' Maxan is sure to be found having a drink in the Thunderbrew Distillery if ye need a bit of training." },
        ["text"] = "О, жрець, еге?  Старого добрягу Максана напевно знайдеш за кухлем у Ґуральні Громоварів, якщо потрібне навчання.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1554395867] = {
        ["english"] = { [1] = "Oh it's just so horrible, $g sir:miss;. The house Barov was once full of life... full of splendor. The manor was the Barov's primary residence amidst their far reaching empire.$B$BLucien and I noticed that as the days progressed, the Barovs became depressed. Despondent. Paranoia and rage often overcame the master and missus. At night, we could hear the Barovs arguing in their chambers. From what we understood, their greed had 'broken the dam,' so to speak. " },
        ["text"] = "О, це просто жахливо, $g пане:панно;. Дім Барових колись кипів життям... і розкішшю. Маєток був головною резиденцією Барових у їхніх величезних володіннях.$B$BМи з Люсьєном помітили, що з кожним днем Барови ставали дедалі пригніченішими. Понурими. Господаря й пані часто охоплювали параноя та лють. Уночі ми чули, як Барови сварилися у своїх покоях. Наскільки ми зрозуміли, їхня жадібність, так би мовити, «прорвала греблю». ",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [2904343843] = {
        ["english"] = { [1] = "No, unfortunately we have not yet taken the harbor. However, reports indicate that we are $3238w percent of the way towards doing so.$B$B$N, if you want to help out, look for Magister Ilastar and Vindicator Kaalan at the Sun's Reach Armory on the Isle of Quel'Danas." },
        ["text"] = "Ні, на жаль, гавань ми ще не захопили. Проте за звітами ми виконали вже $3238w відсотків завдання.$B$B$N, якщо хочеш допомогти, шукай магістра Іластара й поборника Каалана біля Зброярні Сонячного Краю на острові Квел’Данас.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2247691765] = {
        ["english"] = { [1] = "Oh that's simple! You use it like anything else you might activate. Don't worry, I'll take care of lighting the fuse. Once you're up in the air you'll notice that you'll seem to \"float,\" but that won't last forever. What you're aiming for is a target on the lake way over yonder. Make sure that you begin your descent by detaching your \"wings\" at the right time to land in the water, or, well, I don't sell life insurance." },
        ["text"] = "О, це просто! Користуйся ним, як будь-якою іншою річчю, яку можна активувати. Не хвилюйся, ґніт я підпалю сам. Коли опинишся в повітрі, відчуєш, ніби «пливеш», але це ненадовго. Твоя ціль — мішень на озері ген там. Головне — вчасно почати спуск, від’єднавши «крила», щоб упасти у воду, інакше... ну, страхування життя я не продаю.",
        ["npcs"] = { [1] = 15303 },
        ["roles"] = { ["greeting"] = true },
    },
    [3282973086] = {
        ["english"] = { [1] = "Oh no, not you again!  Go away!" },
        ["text"] = "О ні, знову ти!  Іди геть!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [775179061] = {
        ["english"] = { [1] = "OH YEA! You want a taste of these guns, maggot? Step on in!" },
        ["text"] = "О ТАК! Хочеш скуштувати цих гармат, хробаче? Заходь!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2197608389] = {
        ["english"] = { [1] = "Oooh, an Inn is it?  Well, ye just can't beat the Thunderbrew Distillery.  Rest if ye must, but be sure to have an ale or two while ye're there." },
        ["text"] = "О-о, заїзд?  Ну, кращого за Ґуральню Громоварів не знайти.  Відпочинь, якщо мусиш, але не забудь випити там кухоль-другий елю.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2236745531] = {
        ["english"] = { [1] = "Oh good, you're here to rescue me. Now let me out of here!" },
        ["text"] = "О, добре, ти прийшов мене рятувати. Тепер випусти звідси!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2648216471] = {
        ["english"] = { [1] = "Oh dear, I am running dangerously low on supplies! What is taking that blasted goblin so long?" },
        ["text"] = "Ой лишенько, мої запаси небезпечно вичерпуються! Чого той клятий гоблін так довго?",
        ["npcs"] = { [1] = 15179 },
        ["roles"] = { ["greeting"] = true },
    },
    [1255624877] = {
        ["english"] = { [1] = "Men -- can't live with them, can't live without them.  Well, you can... but it's just really boring." },
        ["text"] = "Чоловіки — з ними нестерпно, а без них ніяк.  Ну, можна й без них... але тоді страшенно нудно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1110785469] = {
        ["english"] = { [1] = "Kael's lackeys are about to be taught a lesson in humility.  We will crush the Dawnblade army and take Sun's Reach Harbor from them.$B$BWe are $3238w percent done with our goal." },
        ["text"] = "Посіпаки Келя ось-ось отримають урок смирення.  Ми розтрощимо військо Світанкового Клинка й відберемо в них гавань Сонячного Краю.$B$BНаша мета виконана на $3238w відсотків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1930372235] = {
        ["english"] = { [1] = "Official business, John. I need some information about Marshal Windsor. Tell me about the last time you saw him." },
        ["text"] = "Офіційна справа, Джоне. Мені потрібні відомості про маршала Віндзора. Розкажи, коли ти востаннє його бачив.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [2266354099] = {
        ["english"] = { [1] = "Of course. I found it on the corpse of a dwarf nearby." },
        ["text"] = "Звісно. Я знайшов це на тілі дворфа неподалік.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1396466323] = {
        ["english"] = { [1] = "Of course, Warchief!" },
        ["text"] = "Звісно, Вождю!",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["reply"] = true },
    },
    [2060825113] = {
        ["english"] = { [1] = "My shift's almost over.  Can't wait to catch some shut-eye, know what I mean?" },
        ["text"] = "Моя зміна майже скінчилася.  Не можу дочекатися, коли трохи посплю, розумієш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1043320670] = {
        ["english"] = { [1] = "My sight is filled with visions of events taking place throughout the world and ones that may yet happen. Many of them are grim, but we needn't believe they are incapable of changing." },
        ["text"] = "Мій зір сповнений видінь подій, що відбуваються по всьому світу, й тих, які ще можуть статися. Багато з них похмурі, але це не означає, що їх не можна змінити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [384823755] = {
        ["english"] = { [1] = "Kergul Bloodaxe on the Hunter Rise stands ready to help you get to Warsong Gulch." },
        ["text"] = "Керґул Кривава Сокира на Виступі мисливців готовий допомогти тобі дістатися до Ущелини Пісні Війни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1623913069] = {
        ["english"] = { [1] = "Knowledge is power - TRUE power, my young friend.  You'll be wise to acquire as much of it as you can, and pay proper heed to those who have already done so.$B$BBefore the razing of the Sunwell, we fooled ourselves into thinking we had neared the apex of our civilization.  It took the Scourge to bring us to our knees... and in a way, back to reality." },
        ["text"] = "Знання — це сила, СПРАВЖНЯ сила, мій юний друже.  Буде мудро здобути якомога більше знань і належно шанувати тих, хто вже це зробив.$B$BДо знищення Сонячного Колодязя ми обманювали себе, вважаючи, що майже досягли вершини нашої цивілізації.  Лише Батіг змусив нас упасти на коліна... і, певною мірою, повернув до реальності.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3962056295] = {
        ["english"] = { [1] = "Remember, all things are connected. If the beasts were gone from the land, our kind would die from a great loneliness of spirit, for whatever happens to the beasts also happens to the Tauren. Whatever befalls Azeroth befalls all those that inhabit it. \010" },
        ["text"] = "Пам’ятай: усе пов’язане. Якби звірі зникли з землі, наш народ помер би від великої самотності духу, бо все, що стається зі звірами, стається й з тауренами. Усе, що спіткає Азерот, спіткає й усіх його мешканців. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [767708427] = {
        ["english"] = { [1] = "My master, Plugger Spazzring, is a good boss.  And he makes a lot of money.  His pockets are bursting!" },
        ["text"] = "Мій господар, Плагґер Спаззрінґ, хороший бос.  І заробляє купу грошей.  Кишені тріщать!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [130375015] = {
        ["english"] = { [1] = "Notify me when you are ready to listen to the story." },
        ["text"] = "Повідом мене, коли будеш готовий вислухати історію.",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["greeting"] = true },
    },
    [590750591] = {
        ["english"] = { [1] = "Should you desire sustenance, Galley Chief Grace can tend to your needs." },
        ["text"] = "Якщо потрібна їжа, начальниця камбуза Ґрейс подбає про твої потреби.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [967285179] = {
        ["english"] = { [1] = "Love tokens are small messages of affection you can give to amorous town and city folk.  Such people will reward you with a gift of adoration.$B$BOr, if you are already adored by another, then at the least they'll give you a gift of friendship." },
        ["text"] = "Знаки кохання — це маленькі послання прихильності, які можна дарувати закоханим мешканцям міст і селищ.  У відповідь вони дадуть тобі дарунок обожнювання.$B$BА якщо тебе вже хтось обожнює, то принаймні отримаєш дарунок дружби.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1841559394] = {
        ["english"] = { [1] = "May I help you taste?" },
        ["text"] = "Можна допомогти тобі зі смакуванням?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [551279162] = {
        ["english"] = { [1] = "Let's finish this!" },
        ["text"] = "Закінчімо це!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3153557919] = {
        ["english"] = { [1] = "Mark my words!  You won't find faster gryphons anywhere in the Eastern Kingdoms than the ones right here in Thelsamar!" },
        ["text"] = "Запам’ятай мої слова!  Ніде в Східних Королівствах не знайдеш швидших грифонів, ніж тут, у Телсамарі!",
        ["npcs"] = { [1] = 1572 },
        ["roles"] = { ["greeting"] = true },
    },
    [3848614810] = {
        ["english"] = { [1] = "My wind riders are trained to fly quickly through the hot Barrens air." },
        ["text"] = "Мої вершники вітру навчені швидко літати крізь гаряче повітря Степів.",
        ["npcs"] = { [1] = 3615 },
        ["roles"] = { ["greeting"] = true },
    },
    [2852596365] = {
        ["english"] = { [1] = "Och!  Now ye're talkin'!  I bet Granis Swiftaxe could show ye a thing or two about swinging steel.  He's over in the Thunderbrew Distillery in Kharanos at the moment." },
        ["text"] = "Ох!  Оце інша справа!  Закладаюся, Ґраніс Швидкосокира покаже тобі пару прийомів зі сталлю.  Зараз він у Ґуральні Громоварів у Караносі.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [4233807048] = {
        ["english"] = { [1] = "It's so lovely to see you again, $N! I really can't thank you enough for delivering that message to my dear little gnome.$B$BWould you like to hear a song? It will make traveling in the rough seas much easier!" },
        ["text"] = "Як же чудово знову тебе бачити, $N! Я й справді не знаю, як віддячити за те, що ти доставив те повідомлення моєму любому маленькому гномові.$B$BХочеш почути пісню? З нею мандрівка бурхливим морем стане значно легшою!",
        ["npcs"] = { [1] = 15526 },
        ["roles"] = { ["greeting"] = true },
    },
    [2121952447] = {
        ["english"] = { [1] = "Please hurry, $N. I am in a great deal of pain and time is running out." },
        ["text"] = "Будь ласка, поквапся, $N. Мені дуже боляче, а часу майже не лишилося.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2461258019] = {
        ["english"] = { [1] = "Our people gunna kill every last one o' you Scourge!" },
        ["text"] = "Наші люди вбити кожного останнього з вас, Батіг!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2445167013] = {
        ["english"] = { [1] = "Och!  That Daryl Riknussun is a brilliant cook!  He makes a chilli so hot ye could temper steel with it!  I don't think he'll teach ye the recipe, but he'll certainly help ye to become a good cook.  Ye'll find him at the Bronze Kettle o'er on the northeastern side of The Great Forge." },
        ["text"] = "Ох!  Той Деріл Рікнуссун — геніальний кухар!  Він готує таке гостре чилі, що ним можна гартувати сталь!  Рецепту, думаю, не дасть, але точно допоможе стати добрим кухарем.  Знайдеш його в «Бронзовому Казанку» на північно-східному боці Великого Горна.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2357244496] = {
        ["english"] = { [1] = "Of course I've got a job for you! We're always looking for hunters. Hopefully you'll fare better than the draenei we had to send back to the Exodar -- for burial.$B$B<Acteon laughs.>$B$BI'm joking! You should have seen the look on your face. They got sent back to the Exodar for treatment of minor wounds. Nothin' that they won't recover from..." },
        ["text"] = "Звісно, у мене є для тебе робота! Нам завжди потрібні мисливці. Сподіваюся, ти впораєшся краще за того дренея, якого довелося відправити назад до Екзодара — на поховання.$B$B<Актеон сміється.>$B$BЖартую! Треба було бачити твоє обличчя. Його відправили до Екзодара лікувати незначні рани. Нічого такого, від чого він не оговтається...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1374487271] = {
        ["english"] = { [1] = "Might not be snowy out there, but the nights here can freeze your nose right off. The bunks are in the back - just don't make a nuisance of yourself." },
        ["text"] = "Снігу там, може, й нема, але тутешні ночі можуть відморозити тобі носа. Нари ззаду — тільки не заважай іншим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4171339731] = {
        ["english"] = { [1] = "Och!  Now that's a skill worth knowing.  Tognus beats the anvil with a fury ye don't see often.  Why don't ye go talk him up and see what he can teach ye?" },
        ["text"] = "Ох!  Оце справді корисна навичка.  Тоґнус лупить по ковадлу з такою люттю, якої нечасто побачиш.  Піди поговори з ним і дізнайся, чого він може навчити.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2123103375] = {
        ["english"] = { [1] = "Nuttin' says luvin' like a little tap on da noggin." },
        ["text"] = "Ніщо так не каже про любов, як легенький стусан по макітрі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1130304690] = {
        ["english"] = { [1] = "Nuaar, are you feeling well?  You don't look like yourself today." },
        ["text"] = "Нуааре, ти добре почуваєшся?  Сьогодні ти сам на себе не схожий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3931182174] = {
        ["english"] = { [1] = "Look alive, soldier! Stormpike Intelligence has reported that a master goblin engineer has been taken prisoner by the Winterax trolls. The Frostwolf dogs are actively trying to rescue him so that they may use his engineered gadgets to destroy us! Do not let that happen." },
        ["text"] = "Не спи, солдате! Розвідка Грозової Вершини повідомила, що тролі Зимової Сокири захопили в полон майстра-гобліна інженера. Пси Морозних Вовків уже намагаються його визволити, щоб використати його винаходи й знищити нас! Не дай цьому статися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1832032766] = {
        ["english"] = { [1] = "Now, answer me this, $N:$BWhich creature became the Lich King before spreading the plague across Lordaeron?" },
        ["text"] = "А тепер відповідай, $N:$BЯка істота стала Королем-лічем, перш ніж поширити чуму Лордероном?",
        ["npcs"] = { [1] = 4488 },
        ["roles"] = { ["greeting"] = true },
    },
    [1416635900] = {
        ["english"] = { [1] = "Oh, looking for some arcane enlightenment are you? No place better then then Wizard's Sanctum in the Mage Quarter." },
        ["text"] = "О, шукаєш арканічного просвітлення? Немає кращого місця за Святилище чарівників у Кварталі Магів.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1666020182] = {
        ["english"] = { [1] = "Now you are ready to learn the finer points of kodo hide tanning. Let us begin..." },
        ["text"] = "Тепер ти готовий пізнати тонкощі дублення шкур кодо. Почнімо...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [912314293] = {
        ["english"] = { [1] = "Karazhan is more than a mere building, $N.  If you traced the ley-lines traversing Azeroth you would find that they all converge right about there.$B$B<Alturus points at an invisible spot below the tower.>$B$BFascinating, isn't it?" },
        ["text"] = "Каражан — це значно більше, ніж просто будівля, $N.  Якби простежити лей-лінії, що перетинають Азерот, виявилося б, що всі вони сходяться приблизно отам.$B$B<Альтурус указує на невидиму точку під вежею.>$B$BЗахопливо, правда?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1399598861] = {
        ["english"] = { [1] = "Our newest attraction, and at no cost to you I might add, these miniature tanks, or Tonks as we've cleverly named them, can be controlled from any of the Tonk Control Consoles spread throughout the faire.$B$BAll that you have to do is activate an available control console. Each tonk will come equipped with a stock set of devices, and a random special power to unleash upon your enemy!$B$BHold epic battles with your friends, cruise around, or just cause wild mayhem... the choice is yours!" },
        ["text"] = "Наша найновіша розвага — і, додам, абсолютно безкоштовна — це мініатюрні танки, або «тонки», як ми їх дотепно назвали. Керувати ними можна з будь-якої консолі керування тонками на ярмарку.$B$BПросто активуй вільну консоль. Кожен тонк оснащений стандартним набором пристроїв і випадковою особливою здібністю проти ворогів!$B$BВлаштовуй епічні бої з друзями, катайся навколо або просто сій шалений хаос... вибір за тобою!",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [499966524] = {
        ["english"] = { [1] = "Naralex sleeps again!$b$bLong ago, Naralex journeyed to this cavern with the honorable goal of entering the Emerald Dream and regrowing the Barrens into a lush forest. His focus waned and his thoughts became tainted by serpentine visions.$b$bNow, reptilian beasts seep from his dreams to the land. He must be awoken from the nightmare or he will be forever lost, and a great evil unleashed.$b$bOnly after his corrupted servants, the Fanglords, have been slain can I perform the awakening ritual.\010\010" },
        ["text"] = "Наралекс знову спить!$b$bДавним-давно Наралекс прийшов до цієї печери з благородною метою: увійти до Смарагдового Сну й перетворити Степи на пишний ліс. Та його зосередженість ослабла, а думки отруїли зміїні видіння.$b$bТепер із його снів у наш світ просочуються плазуноподібні звірі. Його треба пробудити від кошмару, інакше він буде втрачений навіки, а велике зло вирветься на волю.$b$bЛише після загибелі його осквернених слуг, Володарів Ікла, я зможу провести ритуал пробудження.\010\010",
        ["npcs"] = { [1] = 3678, [2] = 3679 },
        ["roles"] = { ["greeting"] = true },
    },
    [2980603420] = {
        ["english"] = { [1] = "Oh?" },
        ["text"] = "О?",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["reply"] = true },
    },
    [1533995980] = {
        ["english"] = { [1] = "Now that you have your Black Temple key (Medallion of Karabor), I can teleport you directly to the Black Temple. Just tell me when you are ready." },
        ["text"] = "Тепер, коли в тебе є ключ до Чорного Храму — Медальйон Карабора, — я можу телепортувати тебе просто до Чорного Храму. Скажи, коли будеш готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3966870133] = {
        ["english"] = { [1] = "Now that you have bested me, test your skills against each other!  Take control of either king to begin play." },
        ["text"] = "Тепер, коли ви мене здолали, випробуйте свої навички один проти одного!  Візьміть під контроль будь-якого короля, щоб почати гру.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3640390179] = {
        ["english"] = { [1] = "Now that the war is in full swing, we've had no shortage of able-bodied combatants from the Horde and Alliance.$B$BIf only we could keep them off of each other's throats..." },
        ["text"] = "Тепер, коли війна розгорілася на повну, нам не бракує боєздатних вояків Орди й Альянсу.$B$BЯкби ж тільки вони перестали хапати одне одного за горло...",
        ["npcs"] = { [1] = 15540 },
        ["roles"] = { ["greeting"] = true },
    },
    [808985787] = {
        ["english"] = { [1] = "Now that the rude interruption is over, as I was saying, Quagmirran is nearby!$B$BAs promised, I can fortify you with a magical boon that should aid you in your fight with him." },
        ["text"] = "Тепер, коли це грубе переривання скінчилося: як я й казав, Кваґмірран зовсім поруч!$B$BЯк і обіцяв, я можу зміцнити тебе магічним даром, що допоможе в бою з ним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1823873796] = {
        ["english"] = { [1] = "Let's see how competent you are, shall we? If you perform this task to my liking, I'll spend the time to teach you!" },
        ["text"] = "Подивімося, наскільки ти вправний, гаразд? Якщо виконаєш завдання так, як мені сподобається, я витрачу час і навчу тебе!",
        ["npcs"] = { [1] = 11031 },
        ["roles"] = { ["greeting"] = true },
    },
    [2188739607] = {
        ["english"] = { [1] = "Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake." },
        ["text"] = "Настав час, коли рік молодий, а місяць сяє яскраво.$B$BЦе наш час... коли пробуджуються древні.",
        ["npcs"] = { [1] = 15549, [2] = 15556, [3] = 15557, [4] = 15558, [5] = 15559, [6] = 15560, [7] = 15561, [8] = 15562, [9] = 15563, [10] = 15564, [11] = 15565, [12] = 15566, [13] = 15567, [14] = 15568, [15] = 15569, [16] = 15570, [17] = 15871 },
        ["roles"] = { ["greeting"] = true },
    },
    [2147471617] = {
        ["english"] = { [1] = "Now if I were Innkeeper Renee where might I be?  Hmmm?  Oh, perhaps inside the Gallows' End Tavern.  Yes, that's it, I'm sure of it.  Try the southeast end of Brill... think you can find that?" },
        ["text"] = "Якби я був господинею заїзду Рене, де б я був?  Гм?  Може, всередині таверни «Кінець Шибениці».  Так, точно.  Спробуй на південно-східній околиці Брілля... знайдеш?",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2203424190] = {
        ["english"] = { [1] = "Leave off. I don't have anything for the likes of you." },
        ["text"] = "Відчепися. Для таких, як ти, у мене нічого немає.",
        ["npcs"] = { [1] = 5698 },
        ["roles"] = { ["greeting"] = true },
    },
    [2448028177] = {
        ["english"] = { [1] = "Now I'm the one who feels rough around the edges, I honestly don't think there's anything left I can teach you. But you know who can? Bengus Deepforge in Ironforge, now there's a dwarf that knows his steel. Go look him up in The Great Forge of Ironforge, see if he's up to having a new trainee under him." },
        ["text"] = "Тепер уже я сам почуваюся неотесаним — щиро кажучи, мені більше нічого тебе вчити. Але знаєш хто може? Бенґус Глибококов у Залізогарті — ось дворф, який знає сталь. Шукай його біля Великого Горна Залізогарта й спитай, чи візьме нового учня.",
        ["npcs"] = { [1] = 3136 },
        ["roles"] = { ["greeting"] = true },
    },
    [85907285] = {
        ["english"] = { [1] = "Now that's a piece of steel worth wearing. Form and function lad/lass, I am impressed. Only ever seen it's match once, a Master in the Great Forge named Grumnus Steelshaper. I bet he has learned a few things since then, could probably teach some to ye." },
        ["text"] = "Оце сталь, яку варто носити. Форма й функція, хлопче/дівчино, я вражений. Лише раз бачив щось рівноцінне — в майстра на Великому Горні на ім’я Ґрумнус Сталеформ. Закладаюся, відтоді він багато чого навчився й, певно, зможе навчити й тебе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [553439219] = {
        ["english"] = { [1] = "Nothing like spending a day down at Crystal Lake fishing. Arnold Leland is the man that taught me. You can usually find him out on the dock in the Canal District just fishing the day away. \010\010Oh, and don't believe any of the stories he tells you about monsters in the canals either." },
        ["text"] = "Ніщо не зрівняється з днем риболовлі на Кришталевому озері. Арнольд Леланд навчив мене всього. Зазвичай його можна знайти на причалі в Районі Каналів, де він цілими днями рибалить. \010\010І не вір жодній його байці про чудовиськ у каналах.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [4028126087] = {
        ["english"] = { [1] = "Not too clever are you?  Hmm, if I were a stable master perhaps I might be in the vicinity of say, the stable?  Look for Morganus over there." },
        ["text"] = "Не надто кмітливий, еге?  Гм, якби я був доглядачем стайні, то, мабуть, перебував би десь поблизу... стайні?  Шукай там Моргануса.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2754698281] = {
        ["english"] = { [1] = "Not that I'm quite sure that you could ever possibly in a gazillion years have enough stranglekelp, what with all the ice cream one needs, but we seem to have enough. Or that's what I'm told anyway. It looks like some of the others here might need help with whatever it is that they're collecting. Understandable really when you consider that theirs just couldn't possibly be as fun as collecting stranglekelp." },
        ["text"] = "Не те щоб я вірив, що душника взагалі може колись бути достатньо — з огляду на те, скільки морозива потрібно, — але, кажуть, нам уже вистачає. Схоже, декому з інших тут іще потрібна допомога зі збором їхніх речей. Воно й зрозуміло: їхня робота просто не може бути такою веселою, як збирання душника.",
        ["npcs"] = { [1] = 15434 },
        ["roles"] = { ["greeting"] = true },
    },
    [3028324338] = {
        ["english"] = { [1] = "Pardon me, $r, but I am on official business and cannot be disturbed.$b$bPlease excuse me." },
        ["text"] = "Перепрошую, $r, але я у службових справах і не можу відволікатися.$b$bПрошу вибачити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2640088678] = {
        ["english"] = { [1] = "Snarl calls me simple because I am too slow. I just want to do the job right, and that takes time." },
        ["text"] = "Снарл називає мене простаком, бо я надто повільний. Я просто хочу зробити роботу як слід, а для цього потрібен час.",
        ["npcs"] = { [1] = 10266 },
        ["roles"] = { ["greeting"] = true },
    },
    [3824643342] = {
        ["english"] = { [1] = "Not bad... I suppose training you is not out of the question. Very well! Let's begin..." },
        ["text"] = "Непогано... Гадаю, навчати тебе не така вже й погана ідея. Гаразд! Почнімо...",
        ["npcs"] = { [1] = 5695 },
        ["roles"] = { ["greeting"] = true },
    },
    [956897631] = {
        ["english"] = { [1] = "Lyria's the one you should talk to if you need some training.  She can usually be found out behind the smithy waiting for some armor or weapon to be finished." },
        ["text"] = "Якщо тобі потрібне навчання, поговори з Лірією.  Зазвичай вона стоїть за кузнею й чекає, доки завершать якийсь обладунок чи зброю.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3970743655] = {
        ["english"] = { [1] = "My knowledge of Jewelcrafting I will share with you." },
        ["text"] = "Я поділюся з тобою своїми знаннями ювелірної справи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2534692685] = {
        ["english"] = { [1] = "Not all Tauren despise your kind, $r. Alas, I am forbidden to offer you my services." },
        ["text"] = "Не всі таурени зневажають таких, як ти, $r. Та, на жаль, мені заборонено надавати тобі свої послуги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1741608172] = {
        ["english"] = { [1] = "Not all Forsaken are driven by Sylvanas' will, $N. Some of us are driven by true power--power we earn for ourselves." },
        ["text"] = "Не всі Відречені керуються волею Сильвани, $N. Декого з нас веде справжня сила — сила, яку ми здобуваємо самі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1329823123] = {
        ["english"] = { [1] = "So Kel'Thuzad holds all of the pieces?" },
        ["text"] = "То всі частини у Кел’Тузада?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4263653111] = {
        ["english"] = { [1] = "No greater freedom than to soar through the skies, $c. What can I do for you today?" },
        ["text"] = "Немає більшої свободи, ніж ширяти небесами, $c. Чим можу допомогти сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3693142154] = {
        ["english"] = { [1] = "Lookin' to be an engineer, eh? Well, by Muradin, ye've come to the right place!" },
        ["text"] = "Хочеш стати інженером, га? Клянусь Мурадіном, ти прийшов куди треба!",
        ["npcs"] = { [1] = 1702 },
        ["roles"] = { ["greeting"] = true },
    },
    [3572261308] = {
        ["english"] = { [1] = "Nope, no alchemists out here in Dun Morogh.  Ye best take a look in Ironforge for them... try the gnomes in Tinker Town." },
        ["text"] = "Ні, тут у Дун-Морозі алхіміків немає.  Шукай їх краще в Залізогарті... спробуй у гномів у Місті Механіків.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [866369345] = {
        ["english"] = { [1] = "Speak quickly; I don't have time to waste on idle chatter. The Forsaken have become a force to be reckoned with, but there is still much to do in a given day. This city doesn't run itself.$b$bWhat do you want?" },
        ["text"] = "Говори швидко; у мене немає часу на порожні балачки. Відречені стали силою, з якою доводиться рахуватися, але щодня роботи все одно по горло. Це місто саме себе не керує.$b$bЧого тобі?",
        ["npcs"] = { [1] = 10181 },
        ["roles"] = { ["greeting"] = true },
    },
    [2219672517] = {
        ["english"] = { [1] = "It's good to visit with friends and family again, celebrating and sharing stories of old." },
        ["text"] = "Так приємно знову зустрітися з друзями та родиною, разом святкувати й згадувати давні історії.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2769327349] = {
        ["english"] = { [1] = "No matter how much one learns, there is always more to know." },
        ["text"] = "Скільки б не вчився, завжди лишається щось нове.",
        ["npcs"] = { [1] = 3041, [2] = 3042, [3] = 3043, [4] = 3059, [5] = 3063, [6] = 4089 },
        ["roles"] = { ["greeting"] = true },
    },
    [1602484151] = {
        ["english"] = { [1] = "No... you can't sit on my lap." },
        ["text"] = "Ні... на коліна до мене сісти не можна.",
        ["npcs"] = { [1] = 13444, [2] = 13445 },
        ["roles"] = { ["greeting"] = true },
    },
    [3579510615] = {
        ["english"] = { [1] = "Khit'rix the Dark Master skitters into Valhalas from the southeast!" },
        ["text"] = "Кіт’рікс Темний Майстер пробирається у Валгалас із південного сходу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1491134887] = {
        ["english"] = { [1] = "Maybe Saru Steelfury will teach you to make an axe as good as mine some day.  Find him at The Burning Anvil in the Valley of Honor down the path to the right past Red Canyon Mining." },
        ["text"] = "Може, колись Сару Сталева Лють навчить тебе кувати сокири не гірші за мою.  Знайдеш його в «Палаючому ковадлі» в Долині Честі: йди стежкою праворуч за копальнею Червоного каньйону.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [966258140] = {
        ["english"] = { [1] = "Praise the Light, one has finally answered the calling." },
        ["text"] = "Хвала Світлу, нарешті хтось відгукнувся на поклик.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1026671406] = {
        ["english"] = { [1] = "Just outside the city's main gate is a signpost.  It will point you toward the zeppelin tower.  Speak to Zeppelin Master Frezza at the top of the tower." },
        ["text"] = "Одразу за головною брамою міста стоїть дороговказ.  Він покаже шлях до вежі дирижаблів.  Поговори з майстром дирижаблів Фреззою нагорі вежі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3407257879] = {
        ["english"] = { [1] = "No restraints? Just in a circle?" },
        ["text"] = "Без пут? Просто в колі?",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [1760799737] = {
        ["english"] = { [1] = "My money's on the goblins!  And if you have any sense then yours is too!" },
        ["text"] = "Я ставлю на гоблінів!  І якщо в тебе є хоч трохи розуму, ти теж!",
        ["npcs"] = { [1] = 4429 },
        ["roles"] = { ["greeting"] = true },
    },
    [4087015541] = {
        ["english"] = { [1] = "No, I'm not, but lots of others are looking for love.  You should buy my love tokens, put on some cologne or perfume, and then pass them around!" },
        ["text"] = "Ні, я не шукаю, але багато інших шукають кохання.  Купи в мене знаки кохання, скористайся одеколоном чи парфумами й роздавай їх!",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1768466677] = {
        ["english"] = { [1] = "No, don't feel bad.  I get that a lot.$B$B<Taela looks both amused and annoyed.>$B$BI'm a HIGH elf, not a blood elf.  Don't worry, I'm not going to suck all of the magic out of you." },
        ["text"] = "Ні, не засмучуйся.  Таке зі мною часто буває.$B$B<Таела водночас усміхається й дратується.>$B$BЯ ВИСОКА ельфійка, а не ельфійка крові.  Не хвилюйся, я не висмокчу з тебе всю магію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3198655907] = {
        ["english"] = { [1] = "Kelstrum is a loudmouth and a braggart... and if that weren't enough he's also one of the most skilled warriors ye'll ever meet!  \010\010I tell ye, if ye're looking to be trained in the ways of a warrior, that's who ye should be talking to.  I'm sure he can be found over in the Hall of Arms east of the Gates of Ironforge." },
        ["text"] = "Келструм — горлопан і хвалько... а якби цього було замало, то він ще й один із найвправніших воїнів, яких тобі доведеться зустріти!  \010\010Кажу тобі, якщо хочеш навчитися воїнського ремесла, говорити треба саме з ним.  Упевнений, він у Залі зброї на схід від брам Залізогарта.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2799706368] = {
        ["english"] = { [1] = "Look at them... all they care about is outdoing each other." },
        ["text"] = "Поглянь на них... їх хвилює лише те, як перевершити одне одного.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1065736713] = {
        ["english"] = { [1] = "May I have another Dawn's Gambit, Betina?  I want to test it again..." },
        ["text"] = "Можна мені ще один «Гамбіт Світанку», Бетіно?  Хочу випробувати його ще раз...",
        ["npcs"] = { [1] = 11035 },
        ["roles"] = { ["reply"] = true },
    },
    [2424183752] = {
        ["english"] = { [1] = "No other race on Azeroth has suffered as much as our people, $c. To laugh in the face of death has become second nature for all of us." },
        ["text"] = "Жодна інша раса Азероту не зазнала стільки страждань, як наш народ, $c. Сміятися смерті в обличчя стало для нас другою натурою.",
        ["npcs"] = { [1] = 1569 },
        ["roles"] = { ["greeting"] = true },
    },
    [1981206117] = {
        ["english"] = { [1] = "So, you've been around a lot, but we seem to keep missing each other for getting together after work.$B$BIs it me?$B$B<Khatie purposely cheers up.>$B$BAnyway, I just wanted to say that I... we really appreciate everything that you've been doing for the Skyguard!" },
        ["text"] = "Отже, ти багато де побував, але ми постійно розминаємося й ніяк не можемо зустрітися після роботи.$B$BЦе через мене?$B$B<Каті навмисне підбадьорюється.>$B$BТак чи інакше, я просто хотіла сказати, що я... ми дуже цінуємо все, що ти робиш для Небесної Варти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [761585049] = {
        ["english"] = { [1] = "No more tin bars! Even my arms hurt from stacking them. We have all that we need, so go ask one of the others if they need you to collect anything." },
        ["text"] = "Більше ніяких олов’яних зливків! Навіть руки болять від їх складання. У нас уже є все потрібне, тож спитай інших, чи не треба їм щось назбирати.",
        ["npcs"] = { [1] = 15460 },
        ["roles"] = { ["greeting"] = true },
    },
    [3028506923] = {
        ["english"] = { [1] = "New this year: the PX-238 Winter Wondervolt.  Step on up and don't be shy!$B$BAnd sign these forms before you try it, we're still working a few bugs out of this thing..." },
        ["text"] = "Новинка цього року: PX-238 «Зимовий Дивовольт».  Підходьте, не соромтеся!$B$BІ підпишіть ці папери, перш ніж випробувати — ми ще усуваємо кілька неполадок...",
        ["npcs"] = { [1] = 15732 },
        ["roles"] = { ["greeting"] = true },
    },
    [3741374805] = {
        ["english"] = { [1] = "Oh, you've got oodles of things to learn still. I would teach you everything if I could, but I'm still learning too! Why don't you talk to Trixie Quickswitch in Ironforge, she'll help you further your education!" },
        ["text"] = "О, тобі ще купу всього треба вивчити. Я б навчила тебе всього, якби могла, але й сама ще вчуся! Поговори з Тріксі Швидкоперемикач у Залізогарті, вона допоможе продовжити навчання!",
        ["npcs"] = { [1] = 11037 },
        ["roles"] = { ["greeting"] = true },
    },
    [120594181] = {
        ["english"] = { [1] = "My son could design a faster car than that clunky goblin junk heap!", [2] = "My son could design a faster car than that clunky goblin junk heap! " },
        ["text"] = "Мій син спроєктував би швидшу машину за цю незграбну гоблінську купу мотлоху!",
        ["npcs"] = { [1] = 4430 },
        ["roles"] = { ["greeting"] = true },
    },
    [3390164039] = {
        ["english"] = { [1] = "Look at these samples! What does it mean? What does it mean? I'm going to need time, time to look at all this information. And I'll need more information. Information I can't get... damn! Think, Laris, think!$B$BWhat are you going to do? What?!$B$BThere has to be a solution!" },
        ["text"] = "Поглянь на ці зразки! Що це означає? Що це означає? Мені потрібен час, час, щоб вивчити всі ці дані. І ще більше даних. Даних, яких я не можу дістати... прокляття! Думай, Ларісе, думай!$B$BЩо ти робитимеш? Що?!$B$BМусить бути рішення!",
        ["npcs"] = { [1] = 9616 },
        ["roles"] = { ["greeting"] = true },
    },
    [1796668176] = {
        ["english"] = { [1] = "Our Sanctums syphon arcane power from ley-line currents that traverse our lands invisible to the naked eye.$B$BWith the Sunwell gone, they provide us with a steady and reliable source of energy." },
        ["text"] = "Наші Святилища висмоктують арканічну силу з потоків лей-ліній, що невидимо перетинають наші землі.$B$BПісля втрати Сонячного Колодязя вони забезпечують нас стабільним і надійним джерелом енергії.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2153510982] = {
        ["english"] = { [1] = "Neither you nor I could possibly imagine the pain an individual suffers when their soul is ripped from their body. They are not dead and by no means are they alive. Instead, they walk the land, servants of those that bind them to this world.$B$BLord Razelikh, demonic overlord of these lands, enslaved them all. Nine he took for his own, placing stones of binding near the Dark Portal. The remaining nine were divided up between his subordinates." },
        ["text"] = "Ні ти, ні я не здатні уявити біль того, чию душу виривають із тіла. Вони не мертві, але й аж ніяк не живі. Вони блукають землею, служачи тим, хто прив’язав їх до цього світу.$B$BЛорд Разеліх, демонічний володар цих земель, поневолив їх усіх. Дев’ятьох він забрав собі й поставив камені поневолення біля Темного порталу. Решту дев’ятьох розділив між своїми підлеглими.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [1862077775] = {
        ["english"] = { [1] = "Kraz should never have come to this cursed place... should have known not to trust the human. A blind fool I was, $c, as are you if you follow his counsel.$b$bMy son, lost for two moons, was last seen with the human, Budd. He told me I could find him behind the walls of Zul'Aman....$b$bI followed his people here, and was captured with the rest. Without your help, I was doomed to die.$b$bThank you, stranger." },
        ["text"] = "Краз не мав приходити в це прокляте місце... мав знати, що людині не можна довіряти. Я був сліпим дурнем, $c, і ти такий самий, якщо слухатимеш його порад.$b$bМого сина, зниклого два місяці тому, востаннє бачили з людиною на ім’я Бадд. Він сказав, що я знайду його за мурами Зул’Амана....$b$bЯ пішов сюди за його людьми й потрапив у полон разом з іншими. Без твоєї допомоги я був приречений померти.$b$bДякую тобі, незнайомцю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3660062663] = {
        ["english"] = { [1] = "Nefarian had ordered that unsuitable subjects be destroyed immediately, but these retched beasts would not do so without first inflicting an 'ample' amount of torture.$B$BWhen we were thoroughly 'broken,' they would round up what remained and throw us to these thugs. Our bodies used as instruments in their sick game: thrown into the lava or worse; to the open and waiting arms of the bloodthirsty legion below." },
        ["text"] = "Нефаріан наказав негайно знищувати непридатних піддослідних, але ці жалюгідні тварюки не робили цього, доки не завдадуть «достатньо» мук.$B$BКоли нас остаточно «ламали», вони збирали те, що від нас лишилося, й кидали цим головорізам. Наші тіла ставали знаряддями їхньої хворої гри: нас жбурляли в лаву або ще гірше — просто в розкриті обійми кровожерного легіону внизу.",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["greeting"] = true },
    },
    [403558033] = {
        ["english"] = { [1] = "So how did he break the deal?" },
        ["text"] = "І як він порушив угоду?",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["reply"] = true },
    },
    [343234793] = {
        ["english"] = { [1] = "Marshal Windsor has been expecting you, $N. Unfortunately, he is currently indisposed. He should be returning shortly." },
        ["text"] = "Маршал Віндзор чекав на тебе, $N. На жаль, зараз він зайнятий. Незабаром має повернутися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1800360189] = {
        ["english"] = { [1] = "Looks like there be only one more day left to fish until all this here war materiel is shipped over to the Silithus desert mon. Then they's gonna be getting' it all ready, and someone is gonna have to ring that gong down south of Cenarion Hold there to open them gates and be startin' the war." },
        ["text"] = "Схоже, лишився тільки один день рибалити, перш ніж усі ці воєнні припаси повезуть у пустелю Силітуса, друже. Потім усе підготують, і комусь доведеться вдарити в той гонг на південь від Кенарійської цитаделі, щоб відчинити брами й почати війну.",
        ["npcs"] = { [1] = 15534 },
        ["roles"] = { ["greeting"] = true },
    },
    [3240366703] = {
        ["english"] = { [1] = "Keep your voice low and your eyes open, $N. We're surrounded by enemies out here." },
        ["text"] = "Говори тихо й не втрачай пильності, $N. Тут нас оточують вороги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [759084294] = {
        ["english"] = { [1] = "Many locked boxes of supplies were sunk by the orcs in Lake Everstill in Redridge." },
        ["text"] = "Орки затопили чимало замкнених скринь із припасами в Безхвильному озері в Красногір’ї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2928519494] = {
        ["english"] = { [1] = "Naive fool. The Burning Blade IS the Shadow Council! There are many cults and organizations under the Council's rule, but all of them are just extensions of their will. I may lead the Burning Blade, but I am still just as much a pawn to the Council as you are to me!$B$BLook at the Searing Blade--most of them think they are becoming the next rising group of powerful warlocks that they will replace the Shadow Council." },
        ["text"] = "Наївний дурень. Палаючий Клинок І Є Радою Тіней! Під владою Ради безліч культів і організацій, але всі вони лише продовження її волі. Я можу очолювати Палаючий Клинок, але для Ради я така сама пішак, як ти для мене!$B$BПоглянь на Пекучий Клинок — більшість із них думає, що їхня група могутніх чорнокнижників зросте й одного дня замінить Раду Тіней.",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["greeting"] = true },
    },
    [3245431773] = {
        ["english"] = { [1] = "Myranda, do you have enough eyeballs to make another amulet? I have lost the old one." },
        ["text"] = "Мірандо, у тебе вистачить очних яблук на ще один амулет? Я загубив старий.",
        ["npcs"] = { [1] = 11872 },
        ["roles"] = { ["reply"] = true },
    },
    [3634308989] = {
        ["english"] = { [1] = "My wisdom is yours, as is my knowledge. What can I do for you, $N?" },
        ["text"] = "Моя мудрість і знання до твоїх послуг. Чим можу допомогти, $N?",
        ["npcs"] = { [1] = 3595, [2] = 3600, [3] = 4090, [4] = 4091, [5] = 4092, [6] = 11397, [7] = 11401 },
        ["roles"] = { ["greeting"] = true },
    },
    [3584313630] = {
        ["english"] = { [1] = "Slow down! I was getting to that!$B$BSo there he was, standing tall with all the blood and guts dripping off him when who shows up?$B$BThe Dark Irons! Didn't you hear a word I said??$B$BWell, the Dark Irons are a little craftier than those Blackrock orcs. They came prepared. By prepared I mean there were about 300 of em... *hic* 'scuse me." },
        ["text"] = "Повільніше! Я саме до цього й підходив!$B$BОтже, стоїть він там на весь зріст, увесь у крові й нутрощах, і хто раптом з’являється?$B$BТемне Залізо! Ти взагалі слухав, що я казав??$B$BНу, дворфи Темного Заліза хитріші за тих орків Чорного Каменю. Вони прийшли підготовленими. А під «підготовленими» я маю на увазі, що їх було десь триста... *гик* перепрошую.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [1500094854] = {
        ["english"] = { [1] = "My warmages are inbound and will arrive presently.$b$bSpeak to me again when they have returned," },
        ["text"] = "Мої бойові маги вже в дорозі й скоро прибудуть.$b$bПоговори зі мною знову, коли вони повернуться,",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3985347023] = {
        ["english"] = { [1] = "Rut'theran Ferry" },
        ["text"] = "Пором Рут’терана",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["reply"] = true },
    },
    [3237659853] = {
        ["english"] = { [1] = "Our freedom would have meant nothing if C'Thun had survived. You are truly a champion of prophecy." },
        ["text"] = "Наша свобода нічого б не важила, якби К’Тун вижив. Ти справжній чемпіон пророцтва.",
        ["npcs"] = { [1] = 15379 },
        ["roles"] = { ["greeting"] = true },
    },
    [3186571234] = {
        ["english"] = { [1] = "Only champions of the Exodar may purchase what I have to offer." },
        ["text"] = "Лише чемпіони Екзодара можуть купувати мої товари.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2798287493] = {
        ["english"] = { [1] = "My charge at Agmar's Hammer extends far beyond the care of the animals at the stables." },
        ["text"] = "Мої обов’язки в Молоті Аґмара далеко не обмежуються доглядом за тваринами в стайнях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [180381390] = {
        ["english"] = { [1] = "My loathing of interruptions is overshadowed only by my hatred of Gruul the Dragonkiller and his seven sons!" },
        ["text"] = "Мою відразу до переривань перевершує лише ненависть до Ґруула Драконовбивці та його сімох синів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4064928244] = {
        ["english"] = { [1] = "Maces are taught by Ansekhwa, found on the lower central rise of Thunder Bluff." },
        ["text"] = "Володінню булавами навчає Ансеква на нижньому центральному виступі Громового Бескиду.",
        ["npcs"] = { [1] = 11868, [2] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [240401825] = {
        ["english"] = { [1] = "Please teleport me to the final chamber." },
        ["text"] = "Телепортуй мене, будь ласка, до останньої зали.",
        ["npcs"] = { [1] = 15502 },
        ["roles"] = { ["reply"] = true },
    },
    [4272707730] = {
        ["english"] = { [1] = "My axe has seen many battles, and I like to keep it handy. Enemy forces have fought their way into our capital several times now, but have no fear: we have always driven them back." },
        ["text"] = "Моя сокира пережила чимало битв, і я люблю тримати її напохваті. Ворожі сили вже не раз проривалися в нашу столицю, але не бійся: ми завжди їх відбивали.",
        ["npcs"] = { [1] = 11084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1662785119] = {
        ["english"] = { [1] = "Master Woo Ping has mastered nearly every weapon known to man.  He is especially deadly with his sword techniques.  He spends a good deal of time over in the Weller's Arsenal waiting on new shipments of weapons to arrive if you need some training." },
        ["text"] = "Майстер Ву Пінґ опанував майже всю зброю, відому людям.  Особливо смертоносні його прийоми з мечем.  Якщо тобі потрібне навчання, він часто буває в Арсеналі Веллера й чекає на нові поставки зброї.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2526617573] = {
        ["english"] = { [1] = "Listen carefully, $N, for I have much knowledge to impart." },
        ["text"] = "Слухай уважно, $N, бо я маю передати тобі чимало знань.",
        ["npcs"] = { [1] = 5499 },
        ["roles"] = { ["greeting"] = true },
    },
    [3812847750] = {
        ["english"] = { [1] = "May the light guide your path and aid you in your journies. If you need any assistance browsing, I will be right over here." },
        ["text"] = "Нехай Світло освітлює твій шлях і допомагає в мандрах. Якщо потрібна допомога з вибором, я буду тут.",
        ["npcs"] = { [1] = 1212, [2] = 1348, [3] = 1349, [4] = 1351, [5] = 1444, [6] = 1646, [7] = 4960, [8] = 6171, [9] = 6173, [10] = 7798, [11] = 7917, [12] = 12336, [13] = 16106 },
        ["roles"] = { ["greeting"] = true },
    },
    [1433118553] = {
        ["english"] = { [1] = "Karn says we need to listen to the spirits of the forge and of the steel, that they will guide us. I hear nothing but a ringing in my ears. Here, take a hammer and let us try to hear the spirits together." },
        ["text"] = "Карн каже, що треба слухати духів горна й сталі, і вони вкажуть нам шлях. А я чую лише дзвін у вухах. Ось, бери молот — спробуймо разом почути духів.",
        ["npcs"] = { [1] = 10278 },
        ["roles"] = { ["greeting"] = true },
    },
    [2206019606] = {
        ["english"] = { [1] = "Jobs/Lost & Found/Wanted:" },
        ["text"] = "Робота/Загублене й знайдене/Розшукується:",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [95649921] = {
        ["english"] = { [1] = "My programming will not allow me to lower the cost of any items." },
        ["text"] = "Моя програма не дозволяє мені знижувати вартість будь-яких предметів.",
        ["npcs"] = { [1] = 12245 },
        ["roles"] = { ["greeting"] = true },
    },
    [2206366405] = {
        ["english"] = { [1] = "Our Expedition made it safely through the Portal and set up a new base called Thrallmar. Yet as you can see, the Burning Legion moved in and cut us off from our brothers. Clearly, the demons hope to retake the Dark Portal and prevent us from gathering reinforcements from Azeroth." },
        ["text"] = "Наша експедиція безпечно пройшла крізь Портал і заснувала нову базу — Траллмар. Та, як бачиш, Палаючий Легіон зайняв позиції й відрізав нас від братів. Очевидно, демони прагнуть знову захопити Темний портал і не дати нам отримати підкріплення з Азероту.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3667216816] = {
        ["english"] = { [1] = "My orders are to create a distraction at the Dead Scar so our forces can take the Sun's Reach Armory.  It might not be as glamorous as killing demons face to face, but if it wins us this battle then I'm all for it.$B$BWe are $3233w percent done with our goal." },
        ["text"] = "Мій наказ — відволікти ворога біля Мертвого Шраму, щоб наші сили захопили Зброярню Сонячного Краю.  Може, це не так славно, як убивати демонів віч-на-віч, але якщо це принесе нам перемогу — я за.$B$BМи виконали $3233w відсотків мети.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1970104557] = {
        ["english"] = { [1] = "Move along. Nothing to see here." },
        ["text"] = "Проходь далі. Тут немає на що дивитися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [565023908] = {
        ["english"] = { [1] = "My mouth waters just to think on it.  Pyall Silentstride is the finest cook in Bloodhoof Village.  You will find him in the great tent at the northwest corner of the village." },
        ["text"] = "У мене слина тече від самої думки.  Паялл Тихий Крок — найкращий кухар у селищі Криваве Копито.  Знайдеш його у великому наметі в північно-західному кутку селища.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1764833471] = {
        ["english"] = { [1] = "Paladin" },
        ["text"] = "Паладин",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 5595, [18] = 5624, [19] = 5725, [20] = 6272, [21] = 6740, [22] = 8931, [23] = 12996, [24] = 13076, [25] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [2048022378] = {
        ["english"] = { [1] = "Long have we toiled to see our land returned to its former glory, $c. Ever shall we remain vigilant against those who have invaded and defiled Quel'thalas. We will not rest until they are driven from our sight.$B$BLet none exist who stand in the way of the sin'dorei!" },
        ["text"] = "Ми довго працювали, щоб повернути нашій землі колишню велич, $c. Ми завжди пильнуватимемо тих, хто вторгся й осквернив Квел’Талас. Не спочинемо, доки не проженемо їх геть.$B$BНехай не залишиться нікого, хто стане на шляху сін’дорай!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2064029260] = {
        ["english"] = { [1] = "Of course there's no danger in everything catching flames and exploding like a huge helium bomb. This baby will get you to Undercity faster and safer than any boat, and the view is truly breathtaking. Speaking of breath, smoking is not allowed while on board the zeppelin" },
        ["text"] = "Звісно, жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить тебе до Підміста швидше й безпечніше за будь-який корабель, а краєвид просто перехоплює подих. До речі про подих: на борту дирижабля не можна курити",
        ["npcs"] = { [1] = 9564, [2] = 12137 },
        ["roles"] = { ["greeting"] = true },
    },
    [1999716320] = {
        ["english"] = { [1] = "My father told me there'd be days like this, where a stranger would talk to me and I'd have to restrain myself from killing $ghim:her;." },
        ["text"] = "Батько казав, що будуть такі дні, коли незнайомець заговорить зі мною, а мені доведеться стримуватися, щоб не вбити $gйого:її;.",
        ["npcs"] = { [1] = 9547 },
        ["roles"] = { ["greeting"] = true },
    },
    [447183956] = {
        ["english"] = { [1] = "My life and spirit has been filled with memories of the insufferable Horde. Times of sorrow, desperation, and sacrifice have come to pass. The rage of battle could never leave my heart!" },
        ["text"] = "Моє життя й дух сповнені спогадів про нестерпну Орду. Часи скорботи, відчаю та жертв минули, але лють битви ніколи не залишала мого серця!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3647484928] = {
        ["english"] = { [1] = "My knowledge of night elf lore is limited, but it is said long ago--back when the night elves still held sacred the art of arcane spell casting--that Azshara was the greatest of their kind. A beautiful woman they named queen. Sadly, it was her addiction to the arcane that would one day be the catalyst for the most devastating events in this world's history." },
        ["text"] = "Мої знання про перекази нічних ельфів обмежені, але кажуть, що давним-давно — коли нічні ельфи ще вважали мистецтво арканічної магії священним — Азшара була найвеличнішою серед них. Вродлива жінка, яку вони нарекли королевою. На жаль, її залежність від аркани одного дня стала причиною найспустошливіших подій в історії цього світу.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["greeting"] = true },
    },
    [3511701116] = {
        ["english"] = { [1] = "My education is ongoing, and your knowledge surpasses mine. If you wish to learn more you must speak to Me'lynn. She will guide you." },
        ["text"] = "Я ще продовжую навчатися, а твої знання вже перевершують мої. Якщо хочеш дізнатися більше, поговори з Ме’лінн. Вона тебе наставить.",
        ["npcs"] = { [1] = 11050 },
        ["roles"] = { ["greeting"] = true },
    },
    [3247520662] = {
        ["english"] = { [1] = "Mon, da west wastes of dis place be full o' baddies. Stay away from dis here area if ya want to live!" },
        ["text"] = "Друже, західні пустки цього місця кишать лиходіями. Тримайся звідси подалі, якщо хочеш жити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3176346373] = {
        ["english"] = { [1] = "My brother said we could make great money with this trade route, but he didn't tell me I would be the one living on this side. If you come back this way on the Zeppelin, could you bring me something to eat? They sell some of the finest meat in Orgrimmar, and I sure could use something that didn't die weeks before it stopped moving." },
        ["text"] = "Брат казав, що на цьому торговому маршруті можна добре заробити, але не сказав, що саме я житиму на цьому боці. Якщо повернешся сюди дирижаблем, принесеш мені щось поїсти? В Орґріммарі продають чудове м’ясо, а я б не відмовився від чогось, що померло не за кілька тижнів до того, як перестало рухатися.",
        ["npcs"] = { [1] = 3149, [2] = 9566 },
        ["roles"] = { ["greeting"] = true },
    },
    [613116551] = {
        ["english"] = { [1] = "My brothers and sisters have gone insane! Do you think you could help me get out of here?" },
        ["text"] = "Мої брати й сестри збожеволіли! Допоможеш мені вибратися звідси?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3722890263] = {
        ["english"] = { [1] = "Looks like the last of the goods we've collected are shipping out to Silithus over the next $2113w days. And once that's done, someone will have to come along and ring the gong on the Scarab Dais, outside of Ahn'Qiraj, to open the gates. That's when our bandages will come in handy." },
        ["text"] = "Схоже, останні зібрані припаси відправлять у Силітус протягом наступних $2113w днів. Коли це завершиться, хтось має прийти й ударити в гонг на Помості Скарабея біля Ан’Кіражу, щоб відчинити брами. Ось тоді наші бинти й знадобляться.",
        ["npcs"] = { [1] = 15452 },
        ["roles"] = { ["greeting"] = true },
    },
    [2412843507] = {
        ["english"] = { [1] = "My job consists of one task and one task only: ensuring that the West Sanctum runs smoothly.$B$BYou'll have to excuse my temper but, as you can see, the situation here is a bit out of hand." },
        ["text"] = "Моя робота має лише одне завдання: стежити, щоб Західне Святилище працювало без збоїв.$B$BПробач за мій характер, але, як бачиш, ситуація тут трохи вийшла з-під контролю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2411785018] = {
        ["english"] = { [1] = "My great hammer, Ironfel, was handed down to the new chief architect, Fineous Darkvire: A man of despicable motive and little talent.$B$BThis is where you come in, $N. I want him stopped. He is too inept to harness the true power of Ironfel, but should one come after him with the aptitude to use Ironfel to its full potential, the destruction they could cause with their creations would be disastrous to this world.\010" },
        ["text"] = "Мій великий молот, Залізозгуб, передали новому головному архітектору Фінеусу Темножилу — людині з огидними намірами й мізерним талантом.$B$BОсь тут у справу вступаєш ти, $N. Я хочу, щоб ти його зупинив. Він надто нездарний, щоб опанувати справжню силу Залізозгуба, але якщо після нього з’явиться хтось, здатний розкрити весь потенціал молота, руйнування від його творінь можуть стати катастрофою для цього світу.",
        ["npcs"] = { [1] = 8888 },
        ["roles"] = { ["greeting"] = true },
    },
    [1972470771] = {
        ["english"] = { [1] = "Lard keep peace here. Lard also sell fish. Want fish?" },
        ["text"] = "Лард тут порядок тримати. Лард ще рибу продавати. Хочеш риби?",
        ["npcs"] = { [1] = 14731 },
        ["roles"] = { ["greeting"] = true },
    },
    [1159060966] = {
        ["english"] = { [1] = "Now don't you be thinkin' about tryin' to make off with me baby murlocs! I got the eyes of a hawk and ears like... ears like... like somethin' with mighty powerful ears!" },
        ["text"] = "І не думай поцупити моїх малюків-мурлоків! У мене очі як у яструба й вуха як... як... як у чогось із неймовірно гострим слухом!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1494795493] = {
        ["english"] = { [1] = "My family was slaughtered without mercy. Even the young." },
        ["text"] = "Мою родину вирізали без жалю. Навіть дітей.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2723376303] = {
        ["english"] = { [1] = "My sisters and I have come down from the Stonetalon Mountains to put to rest a tragedy from ages past. Unfortunately, we are not powerful enough to accomplish our goals on our own and now seek mortals such as yourself to aid us.$B$BIf you are powerful enough, then we have much to discuss, $c. If you are not, then, for your safety, I will leave the details of my mission out of our conversation." },
        ["text"] = "Ми з сестрами спустилися з Кам’янистих гір, щоб покласти край трагедії далекого минулого. На жаль, самотужки нам бракує сили, тому тепер ми шукаємо допомоги смертних, таких як ти.$B$BЯкщо ти достатньо могутній, нам є про що поговорити, $c. Якщо ні — заради твоєї безпеки я не розкриватиму подробиць своєї місії.",
        ["npcs"] = { [1] = 13699 },
        ["roles"] = { ["greeting"] = true },
    },
    [1102026851] = {
        ["english"] = { [1] = "My brother and I have dedicated ourselves to Sylvanas. She is our beacon of light when times were darkest. We sacrifice ourselves day in and day out to ensure our kind overcome the destiny that's chosen us.$B$BWe will not remain weak. We will take that which is owed to us. We will return tenfold, the pain that was done to us. And we shall do so with smiles on our faces." },
        ["text"] = "Ми з братом присвятили себе Сильвані. В найтемніші часи вона була нашим маяком. День у день ми жертвуємо собою, щоб наш народ здолав долю, яка його спіткала.$B$BМи не залишимося слабкими. Ми заберемо те, що нам належить. Ми повернемо вдесятеро весь біль, якого нам завдали. І робитимемо це з усмішками на обличчях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1939919939] = {
        ["english"] = { [1] = "Several sets of the Plates of Uldum have been synthesized by the Creators for their expressed use.  The Creators control the distribution of said discs for all complexes on this world.  As such, Azeroth has been rescheduled for visitation, and therefore future discs may enter circulation at that time.$B$BExisting discs have been fully distributed to those parties with appropriate security clearance." },
        ["text"] = "Творці синтезували кілька наборів Плит Ульдуму для власного використання.  Творці контролюють розподіл цих дисків для всіх комплексів цього світу.  Відвідування Азероту перенесено на інший час, тому в майбутньому нові диски можуть знову потрапити в обіг.$B$BНаявні диски вже повністю розподілено між сторонами з відповідним рівнем допуску.",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["greeting"] = true },
    },
    [3273530329] = {
        ["english"] = { [1] = "My apologies, Pebblebitty." },
        ["text"] = "Перепрошую, Пебблбітті.",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["reply"] = true },
    },
    [3750996175] = {
        ["english"] = { [1] = "Our food should satisfy even the mightiest of hungers." },
        ["text"] = "Наша їжа втамує навіть наймогутніший голод.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [830212323] = {
        ["english"] = { [1] = "Most of my brethren are disdainful of the Horde's \"barbaric\" ways, and I once counted myself among them. When I was first ordered to this somewhat humid and... fragrant place, I cursed my lot in life.$b$bDuring my studies, however, I grew to appreciate my surroundings. It has a certain charm, don't you think?$b$bAh, and my studies, of course, were to allow other mages to return here with a spell. Shall I teach you?" },
        ["text"] = "Більшість моїх побратимів зневажає «варварські» звичаї Орди, і я колись був серед них. Коли мене вперше відрядили в це трохи вологе й... пахуче місце, я проклинав свою долю.$b$bТа в процесі досліджень я навчився цінувати ці околиці. Є в них певний шарм, хіба ні?$b$bА, і мої дослідження, звісно, були присвячені тому, щоб інші маги могли повертатися сюди за допомогою закляття. Навчити тебе?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3931737771] = {
        ["english"] = { [1] = "Once the greatest gold production center in the human lands, the Dead Mines are now inhabited by the Defias Brotherhood, who have turned the dark tunnels into their private sanctum. It is rumored that the thieves have conscripted the clever goblins to help them build something terrible at the bottom of the mines - but what that may be is still uncertain. Rumor has it that the way into the Deadmines lies through the quiet, unassuming village of Moonbrook.$b" },
        ["text"] = "Колись найбільший центр видобутку золота в людських землях, Мертві копальні тепер захоплені Братством Непокірних, яке перетворило темні тунелі на власне святилище. Подейкують, злодії залучили кмітливих гоблінів до будівництва чогось жахливого на дні шахт — але чого саме, невідомо. Кажуть, шлях до Мертвих копалень лежить через тихе й непримітне селище Місячне Селище.$b",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [3362746195] = {
        ["english"] = { [1] = "Samamba tinkin' joo be at da wrong quartermaster!$B$BWhat she got only for de Sen'jin champions..." },
        ["text"] = "Самамба думати, ти прийти не до того квартирмейстера!$B$BЇї товари лише для чемпіонів Сен’джина...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2162199431] = {
        ["english"] = { [1] = "Let me browse your seasonal fare." },
        ["text"] = "Дозволь поглянути на твої сезонні товари.",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["reply"] = true },
    },
    [2883676320] = {
        ["english"] = { [1] = "My job is to care for these poor souls.  I accept the help of any willing to lend a hand, be they Aldor or Scryer.$B$BWe are so understaffed, I wouldn't turn an ogre away if they knew how to apply a tourniquet.  The politics of the city are of little matter to me. " },
        ["text"] = "Моя справа — доглядати цих бідолашних.  Я прийму допомогу будь-кого, хто готовий підставити плече, чи то Алдор, чи Провидець.$B$BНам так бракує людей, що я не прогнав би навіть огра, якби той умів накладати джгут.  Міська політика мене мало хвилює. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2248360397] = {
        ["english"] = { [1] = "Mograine?" },
        ["text"] = "Моґрейн?",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [1275248204] = {
        ["english"] = { [1] = "Never fear, Bodley is on the job! Let's see here, ah yes... there it is. Let me just summon it... and, presto!$B$BTry not to lose it again, $N." },
        ["text"] = "Не бійся, Бодлі за справою! Подивімося... ага, ось воно. Зараз лише прикличу... і готово!$B$BПостарайся більше не губити, $N.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [576299389] = {
        ["english"] = { [1] = "Mennet said I should ask you for a set of thieves' tools." },
        ["text"] = "Меннет сказав, що я маю попросити в тебе набір злодійських інструментів.",
        ["npcs"] = { [1] = 6566 },
        ["roles"] = { ["reply"] = true },
    },
    [1843933470] = {
        ["english"] = { [1] = "Maybe this wasn't the best place for a shop after all..." },
        ["text"] = "Може, це все-таки було не найкраще місце для крамниці...",
        ["npcs"] = { [1] = 14637 },
        ["roles"] = { ["greeting"] = true },
    },
    [1864832774] = {
        ["english"] = { [1] = "Looking to learn how to use a new weapon?  Find Sayoc and Hanashi inside Arms of Legend in the Valley of Honor." },
        ["text"] = "Хочеш навчитися користуватися новою зброєю?  Знайди Сайока й Ганаші в «Зброї легенд» у Долині Честі.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1645479069] = {
        ["english"] = { [1] = "Our units are not upgraded, and I don't have enough supplies to upgrade them." },
        ["text"] = "Наші підрозділи не покращено, а припасів для покращення бракує.",
        ["npcs"] = { [1] = 13176, [2] = 13257 },
        ["roles"] = { ["greeting"] = true },
    },
    [3923928199] = {
        ["english"] = { [1] = "Just swinging a hammer at an anvil doesn't make you a smith. Give me that and let me teach you something before you embarrass us all." },
        ["text"] = "Від того, що ти махаєш молотом біля ковадла, ковалем не станеш. Дай-но сюди й дозволь мене тебе дечого навчити, перш ніж ти зганьбиш нас усіх.",
        ["npcs"] = { [1] = 3174 },
        ["roles"] = { ["greeting"] = true },
    },
    [962416749] = {
        ["english"] = { [1] = "Marion Call is keeping Dark Cleric Beryl company in the reading room upstairs at the Gallows' End Tavern on the southeast edge of Brill.  I'm just dying to see who wins that staring contest." },
        ["text"] = "Маріон Колл складає компанію Темному клірику Берилу в читальні на другому поверсі таверни «Кінець Шибениці» на південно-східній околиці Брілля.  Помираю від цікавості, хто переможе в їхньому змаганні поглядів.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2628964674] = {
        ["english"] = { [1] = "Rokkaram, is that you?$B$BForgive me for questioning you, my son. My sight isn't what it once was, but the raven has blessed me with a long life. Soon it will be time for you to take my place. I have taught you all I know. $B$BMy only regret is that I didn't prove worthy enough to recover our sacred Book of the Raven.The true believers have lived in shame since the day our treacherous cousins in Skettis stole the book from us, shattered its tablet, and buried the fragments in their wretched city!$B$BPray that the raven will choose you to restore it, my son. Be faithful and remember always the prophecy, \"From the dreams of his enemies shall the raven spring forth into the world.\"" },
        ["text"] = "Роккараме, це ти?$B$BПробач, що сумніваюся, сину. Зір у мене вже не той, що колись, та ворон благословив мене довгим життям. Скоро настане час тобі посісти моє місце. Я навчив тебе всього, що знаю. $B$BЄдине, про що шкодую: я виявився недостатньо гідним, щоб повернути нашу священну Книгу Ворона. Істинні віряни жили в ганьбі відтоді, як наші підступні родичі зі Скеттіса викрали книгу, розбили її табличку й поховали уламки у своєму жалюгідному місті!$B$BМолися, щоб ворон обрав тебе відновити її, сину. Будь вірним і завжди пам’ятай пророцтво: «Із снів своїх ворогів ворон вирветься у світ». ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2554326595] = {
        ["english"] = { [1] = "No part of the animals we hunt is wasted. " },
        ["text"] = "Жодна частина впольованої тварини не пропадає даремно. ",
        ["npcs"] = { [1] = 11051 },
        ["roles"] = { ["greeting"] = true },
    },
    [2214622055] = {
        ["english"] = { [1] = "Something plagues this tower. I've fallen ill and the other Venture Co. employees that work near or in the tower have also become sick.$B$BJust last week, two of our patrollers died, only to instantly come back to life as mindless drones!$B$BThe lifeforce is draining from my body. I can feel myself losing control. Urges taking over... Bad urges... *Fizzule slaps himself in the face* Not yet... Listen... Mine is a position of power. This position privies me to some sensitive information. " },
        ["text"] = "Щось уразило цю вежу. Я захворів, і інші працівники Торгової Компанії, які працюють біля вежі чи всередині, теж занедужали.$B$BЛише минулого тижня двоє наших патрульних померли, а потім миттєво повернулися до життя бездумними слугами!$B$BЖиттєва сила покидає моє тіло. Я відчуваю, як втрачаю контроль. Пориви беруть гору... Погані пориви... *Фіззул ляскає себе по обличчю* Ще ні... Слухай... Я займаю впливову посаду. А це дає мені доступ до деякої чутливої інформації. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2111012616] = {
        ["english"] = { [1] = "Listen, $r. Listen well...$B$BThe dragon riders came in the night, mounted atop the black flight. They struck fast and with deadly precision, taking young whelps - such as me - and escaping under the veil of darkness.$B$BI watched in horror as they used my brothers and sisters in their experiments. From our essence would be created the chromatic flight." },
        ["text"] = "Слухай, $r. Слухай уважно...$B$BВершники на драконах прийшли вночі, осідлавши чорну зграю. Вони діяли швидко й смертоносно точно, викрадали молодих дракончиків — таких, як я, — і зникали під покровом темряви.$B$BЯ з жахом дивився, як вони проводили досліди над моїми братами й сестрами. З нашої сутності вони створили хроматичну зграю.",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["greeting"] = true },
    },
    [1221755545] = {
        ["english"] = { [1] = "Profession Trainer" },
        ["text"] = "Наставник професії",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3571, [7] = 4262, [8] = 5595, [9] = 6272, [10] = 6740, [11] = 8931, [12] = 12996, [13] = 13076, [14] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [3924099421] = {
        ["english"] = { [1] = "Marlgen... One of the jailors. He has the key to my bonds." },
        ["text"] = "Марлґен... Один із тюремників. У нього ключ від моїх пут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1477635468] = {
        ["english"] = { [1] = "May the spirits guide you, $r." },
        ["text"] = "Нехай духи ведуть тебе, $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1558463722] = {
        ["english"] = { [1] = "Let me at 'em, $N! Just give the word and I'll mount up and attack their bridge!" },
        ["text"] = "Пусти мене до них, $N! Лише скажи слово — я сяду верхи й атакую їхній міст!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [829575424] = {
        ["english"] = { [1] = "Maraudon" },
        ["text"] = "Мародон",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2963916366] = {
        ["english"] = { [1] = "Kodo beasts, my friend!  Trained from a young age and raised on the Golden Plains of Mulgore, these fine animals will make even finer steeds!  Please, browse my selection, and see for yourself why we taurens have come to rely on these magnificant creatures!" },
        ["text"] = "Кодо, друже!  Їх тренують змалечку й вирощують на Золотих рівнинах Мулґору — ці чудові тварини стають іще кращими скакунами!  Поглянь на мій вибір і сам переконайся, чому ми, таурени, так покладаємося на цих величних створінь!",
        ["npcs"] = { [1] = 3685 },
        ["roles"] = { ["greeting"] = true },
    },
    [3124607161] = {
        ["english"] = { [1] = "Just remember that you can only pick one gathering job to do per day. Aside from that, we're always looking for more crystals. Any worthless peon can bring those back to the base camp." },
        ["text"] = "Пам’ятай, що за день можна взяти лише одне завдання на збір. А крім того, нам завжди потрібні додаткові кристали. Будь-який нікчемний наймит може притягти їх назад до опорного табору.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [23805161] = {
        ["english"] = { [1] = "Natalia?" },
        ["text"] = "Наталія?",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [1602228459] = {
        ["english"] = { [1] = "Many have been lost to the seas.  I, and the wisps, are charged with looking for those souls.", [2] = "Many have been lost to the seas.  I, and the wisps, are charged with looking for those souls.  " },
        ["text"] = "Море забрало багатьох.  Нам із вогниками доручено шукати їхні душі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2313974062] = {
        ["english"] = { [1] = "Many are the rare and precious objects that my clientele seek.$B$BYou could be the one to bring them to me, $c. In return I offer that which you covet.$B$BShall we speak more on that which I look to procure today?" },
        ["text"] = "Мої клієнти шукають безліч рідкісних і коштовних речей.$B$BСаме ти можеш приносити їх мені, $c. Натомість я пропоную те, чого прагнеш ти.$B$BПоговоримо докладніше про те, що я хочу придбати сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2622409304] = {
        ["english"] = { [1] = "Our units are upgraded to Seasoned, but I don't have enough supplies to upgrade them to Veteran." },
        ["text"] = "Наші підрозділи вже загартовані, але припасів, щоб зробити їх ветеранами, бракує.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3090929071] = {
        ["english"] = { [1] = "Listen to your elders, $N. If you are strong of will and dedicated, there is no power you cannot control." },
        ["text"] = "Слухай старших, $N. Якщо твоя воля міцна, а рішучість непохитна, немає сили, яку ти не зможеш опанувати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2775170827] = {
        ["english"] = { [1] = "Last I knew, Elder Starsong was in the Sunken Temple of the Swamp of Sorrows." },
        ["text"] = "Наскільки мені відомо, старійшина Зорепісня був у Затонулому храмі на Болоті Скорботи.",
        ["npcs"] = { [1] = 15563, [2] = 15565, [3] = 15576, [4] = 15577, [5] = 15596 },
        ["roles"] = { ["greeting"] = true },
    },
    [2690921582] = {
        ["english"] = { [1] = "Malygos is my answer." },
        ["text"] = "Моя відповідь — Маліґос.",
        ["npcs"] = { [1] = 4489 },
        ["roles"] = { ["reply"] = true },
    },
    [545103462] = {
        ["english"] = { [1] = "Lok'tar, $r. I am General Zog, ambassador of the Horde. I am here to keep you apprised of the progress that the mighty Horde is making in their efforts toward the Ahn'Qiraj War. What is it that you want to know?" },
        ["text"] = "Лок’тар, $r. Я генерал Зоґ, посол Орди. Я тут, щоб повідомляти тобі про успіхи могутньої Орди в підготовці до війни в Ан’Кіражі. Що хочеш знати?",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [2958123291] = {
        ["english"] = { [1] = "Malorne somehow manages to pick the most delicate herbs without damaging them.  Certainly he is the one you should learn from.  He lives just east of the Inn in Dolanaar." },
        ["text"] = "Малорн якимось дивом збирає навіть найніжніші трави, не пошкоджуючи їх.  Безперечно, вчитися слід саме в нього.  Він живе трохи східніше заїзду в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1942149092] = {
        ["english"] = { [1] = "Pleased to meet you! I'm Gidge, the resident spellfire tailoring expert here in Shattrath. Not that there's any competition, but if you're interested in learning to be a spellfire tailor and haven't settled on a specialization, I can help." },
        ["text"] = "Рада знайомству! Я Ґідж, місцева фахівчиня з кравецтва чаротканини тут, у Шаттраті. Не те щоб тут була конкуренція, але якщо хочеш стати кравцем чаротканини й ще не обрав спеціалізацію, я допоможу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1435344152] = {
        ["english"] = { [1] = "Make it quick, $r." },
        ["text"] = "Швидше, $r.",
        ["npcs"] = { [1] = 5395 },
        ["roles"] = { ["greeting"] = true },
    },
    [3043344145] = {
        ["english"] = { [1] = "Keep your voice down, $c!" },
        ["text"] = "Говори тихіше, $c!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [243027658] = {
        ["english"] = { [1] = "Made by the finest craftsmen in all of Teldrassil, carried by hand from Kalimdor to Azeroth as a sign of the growing alliance between the people of the Great Tree and the humans of this land. If there is anything you require, you have but to ask." },
        ["text"] = "Виготовлено найкращими майстрами всього Тельдрассілу й вручну доставлено з Калімдору до Азероту як знак зміцнення союзу між народом Великого Дерева та людьми цих земель. Якщо тобі щось потрібно — лише попроси.",
        ["npcs"] = { [1] = 5503 },
        ["roles"] = { ["greeting"] = true },
    },
    [3069763122] = {
        ["english"] = { [1] = "Now's our chance! Let me out of this cage!" },
        ["text"] = "Ось наш шанс! Випусти мене з цієї клітки!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2575892482] = {
        ["english"] = { [1] = "NEVER say that name around me! Consider this your one and only warning!" },
        ["text"] = "НІКОЛИ не вимовляй це ім’я при мені! Вважай це першим і останнім попередженням!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3469410350] = {
        ["english"] = { [1] = "Jungle Fever" },
        ["text"] = "Тропічна лихоманка",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["reply"] = true },
    },
    [2456629098] = {
        ["english"] = { [1] = "Not bad... for an amateur! Still, you know about as much as I do. If you wanna' learn more you're gonna' have to talk to Josef Gregorian in Undercity." },
        ["text"] = "Непогано... як для любителя! Та ти вже знаєш приблизно стільки ж, скільки й я. Якщо хочеш вчитися далі, доведеться поговорити з Йозефом Ґреґоріаном у Підмісті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1928041930] = {
        ["english"] = { [1] = "On the northern dock, you can board a ship that will carry you to Rut'theran Village and Darnassus.  From the southern dock, you can find passage across the Great Sea to Menethil Harbor on Khaz Modan.  Safe journeys to you!", [2] = "On the northern dock, you can board a ship that will carry you to Rut'theran Village and Darnassus. From the southern dock, you can find passage across the Great Sea to Menethil Harbor on Khaz Modan. Safe journeys to you!" },
        ["text"] = "На північному причалі можна сісти на корабель до селища Рут’теран і Дарнаса.  З південного причалу можна переплисти Велике море до гавані Менетілів у Каз-Модані.  Щасливої дороги!",
        ["npcs"] = { [1] = 12656 },
        ["roles"] = { ["greeting"] = true },
    },
    [2173172558] = {
        ["english"] = { [1] = "Low spirits" },
        ["text"] = "Занепалий дух",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["reply"] = true },
    },
    [2280667352] = {
        ["english"] = { [1] = "Lots to do! Haven't been this busy since my cousin accidentally vaporized all the cloth and leather in Gnomeregan. My, it was drafty for a while! Ah, $N, those were the days...." },
        ["text"] = "Справ по горло! Такого завалу не було відтоді, як мій кузен випадково випарував усю тканину й шкіру в Гномреґані. Ох і протяги тоді були! А, $N, от були часи....",
        ["npcs"] = { [1] = 5127 },
        ["roles"] = { ["greeting"] = true },
    },
    [2130905384] = {
        ["english"] = { [1] = "Lost it? What do you mean?" },
        ["text"] = "Загубив? Що ти маєш на увазі?",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [4005964981] = {
        ["english"] = { [1] = "Looks like the last of the goods we've collected is going to be shipped out to Silithus sometime in the next day. And once that's done, someone will have to come along and ring the gong on the Scarab Dais, outside of Ahn'Qiraj, to open the gates. That's when our bandages will come in handy." },
        ["text"] = "Схоже, останні зібрані припаси відправлять у Силітус десь протягом наступного дня. Коли це завершиться, хтось має прийти й ударити в гонг на Помості Скарабея біля Ан’Кіражу, щоб відчинити брами. Ось тоді наші бинти й знадобляться.",
        ["npcs"] = { [1] = 15452 },
        ["roles"] = { ["greeting"] = true },
    },
    [501077866] = {
        ["english"] = { [1] = "Looking to learn how to work an anvil and hammer, eh?  Karn Stonehoof can teach you how.  He has a smithy set up on the lower rise by the pond." },
        ["text"] = "Хочеш навчитися працювати з ковадлом і молотом, еге?  Карн Кам’яне Копито може тебе навчити.  Його кузня стоїть на нижньому виступі біля ставка.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2962327700] = {
        ["english"] = { [1] = "Looking for an Arena Battlemaster? You can find them on the road between towns, or in the capitals.$B$BYou can bind here, at me. I can also teleport you to one of the capitals." },
        ["text"] = "Шукаєш розпорядника арени? Їх можна знайти на дорогах між містами або в столицях.$B$BМожеш прив’язатися тут, у мене. Я також можу телепортувати тебе до однієї зі столиць.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3356776013] = {
        ["english"] = { [1] = "Normally it would not be my place to speak with you directly; rather, you would seek an audience with milady. However, I did give you a task directly, so what is it that we need to discuss?" },
        ["text"] = "Зазвичай мені не годилося б говорити з тобою напряму — ти мав би просити аудієнції в моєї пані. Та завдання я дав тобі особисто, тож про що нам треба поговорити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3852224121] = {
        ["english"] = { [1] = "Keep your voice down, $c. I'm in disguise and spying for Venomspite." },
        ["text"] = "Говори тихіше, $c. Я під прикриттям і шпигую для Отруйної Злоби.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [108032331] = {
        ["english"] = { [1] = "Look for Nogg's Machine Shop in the Valley of Honor northeast of Red Canyon Mining." },
        ["text"] = "Шукай майстерню Ноґґа в Долині Честі, на північний схід від копальні Червоного каньйону.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2934556124] = {
        ["english"] = { [1] = "Look behind you, $r. The hive stirs as the land that surrounds us shudders and shakes.$B$BThe time has come for me to fulfill a promise I made a thousand years past. The sands shift once more as the Qiraji plan for war." },
        ["text"] = "Озирнися, $r. Вулик прокидається, а земля довкола здригається й тремтить.$B$BНастав час виконати обіцянку, яку я дав тисячу років тому. Піски знову ворушаться, бо кіражі готуються до війни.",
        ["npcs"] = { [1] = 15180 },
        ["roles"] = { ["greeting"] = true },
    },
    [3448300758] = {
        ["english"] = { [1] = "Never leave home without ample supplies of flash powder, especially when working with others. I guarantee someone will run out every time.$B$BWhen the choice comes down to handing out materials or letting the poor sap die, I help... most of the time." },
        ["text"] = "Ніколи не виходь із дому без доброго запасу сліпучого порошку, особливо коли працюєш з іншими. Гарантую, що хтось обов’язково все витратить.$B$BКоли доводиться вибирати між тим, щоб поділитися матеріалами, або дозволити бідоласі померти, я допомагаю... здебільшого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4263658357] = {
        ["english"] = { [1] = "Join a group going to this dungeon.    <This choice will place you in a meetingstone queue>    ", [2] = "Join a group going to this dungeon.    <This choice will place you in a meetingstone queue>    \010", [3] = "Join a group going to this dungeon.    <This choice will place you in a meetingstone queue>                              " },
        ["text"] = "Приєднатися до групи, що прямує в це підземелля.    <Цей вибір поставить вас у чергу каменя зустрічей>    ",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2278612790] = {
        ["english"] = { [1] = "It's so exciting to be here in Darnassus, surrounded by talented people! I just know I'm going to make my family proud. Maybe if I'm really lucky, the Sentinels will ask me to join their forces on the front!" },
        ["text"] = "Так захопливо бути тут, у Дарнасі, серед стількох талановитих людей! Я просто знаю, що моя родина мною пишатиметься. Можливо, якщо мені дуже пощастить, Вартові покличуть мене до своїх лав на передову!",
        ["npcs"] = { [1] = 11083 },
        ["roles"] = { ["greeting"] = true },
    },
    [1437803976] = {
        ["english"] = { [1] = "Please do." },
        ["text"] = "Будь ласка.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3107450416] = {
        ["english"] = { [1] = "Leaving Kael'thas was the best thing any of us ever did.  His followers are too blind or too scared to realize where he's leading them.$B$BWe, however, are not." },
        ["text"] = "Покинути Кель’таса було найкращим рішенням, яке будь-хто з нас коли-небудь ухвалював.  Його послідовники надто сліпі або надто налякані, щоб зрозуміти, куди він їх веде.$B$BА ми — ні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1060454899] = {
        ["english"] = { [1] = "Long ago, before the last great war, my father ran the Northridge Lumber Mill. It was his life, and he was committed to it. Then the war came, and as much as it pained him, we had to flee to Stormwind.$B$BWe lost a number of friends and family in the those days, and it pains me to know that the Scarlet Crusade has taken the mill for their own ends.$B$BThat's why I've returned." },
        ["text"] = "Давним-давно, ще до останньої великої війни, мій батько керував Нортріджською лісопильнею. Вона була його життям, він віддавав їй усього себе. Потім прийшла війна, і хоч як йому було боляче, нам довелося тікати до Штормовію.$B$BТоді ми втратили чимало друзів і рідних, і мені боляче знати, що Багряний Похід захопив лісопильню заради власних цілей.$B$BСаме тому я повернувся.",
        ["npcs"] = { [1] = 11616 },
        ["roles"] = { ["greeting"] = true },
    },
    [3097410741] = {
        ["english"] = { [1] = "Seek out Turak Runetotem in the Hall of Elders on the Elder Rise." },
        ["text"] = "Шукай Турака Рунічного Тотема в Залі Старійшин на Верхів’ї старійшин.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3218607412] = {
        ["english"] = { [1] = "Located in Dun Morogh, Gnomeregan has been the gnomes' capital city for generations, though it was recently infested by mutant troggs. In a desperate attempt to retaliate, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Though the troggs became irradiated, their siege continued unabated and the gnomes were forced to seek refuge in the dwarven city of Ironforge, where the High Tinker now enlists brave souls to help his people reclaim their beloved city. \010" },
        ["text"] = "Розташований у Дун-Морозі, Гномреґан поколіннями був столицею гномів, доки нещодавно його не заполонили мутовані троґґи. У відчайдушній спробі відбитися Верховний механік Меккаторк наказав аварійно випустити в місто вміст резервуарів із радіоактивними відходами. Та навіть опромінені троґґи не припинили облоги, і гномам довелося шукати прихистку в дворфійському Залізогарті. Тепер Верховний механік набирає хоробрих добровольців, щоб допомогти його народові повернути улюблене місто. \010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [7071986] = {
        ["english"] = { [1] = "Manaforge Duro is the closest facility to Tempest Keep, so it handles most of the load.$B$BAs you should know, overloading these manaforges causes leaks in the pipelines.  The emanating energy attracts unwanted mana creatures.  We've had mana creature infestations at many leak locations; Manaforge Duro is being hit the hardest at the moment." },
        ["text"] = "Манакузня Дуро — найближчий до Буревійної фортеці об’єкт, тому на неї припадає основне навантаження.$B$BЯк тобі має бути відомо, перевантаження цих манакузень спричиняє витоки в трубопроводах.  Енергія, що виривається назовні, приваблює небажаних манових істот.  У багатьох місцях витоків уже завелися манові створіння; зараз найбільше потерпає манакузня Дуро.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [18051846] = {
        ["english"] = { [1] = "Mourn the great loss." },
        ["text"] = "Оплакуй велику втрату.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1038464680] = {
        ["english"] = { [1] = "Sightless I may be, but vision I have.$B$BMy primary dealings are with hunters and rogues, $r." },
        ["text"] = "Я можу бути сліпим, але бачу більше за багатьох.$B$BПереважно я маю справу з мисливцями й розбійниками, $r.",
        ["npcs"] = { [1] = 14905 },
        ["roles"] = { ["greeting"] = true },
    },
    [2237097413] = {
        ["english"] = { [1] = "Ragefire Chasm consists of a network of volcanic caverns that lie below the orcs' new capital city of Orgrimmar. Recently, rumors have spread that a cult loyal to the demonic Shadow Council has taken up residence within the Chasm's fiery depths. This cult, known as the Burning Blade, threatens the very sovereignty of Durotar. Many believe that the orc Warchief, Thrall, is aware of the Blade's existence and has chosen not to destroy it in the hopes that its members might lead him straight to the Shadow Council. Either way, the dark powers emanating from Ragefire Chasm could undo all that the orcs have fought to attain." },
        ["text"] = "Ущелина Люті Вогню — це мережа вулканічних печер під новою столицею орків, Орґріммаром. Нещодавно поширилися чутки, що в її палаючих глибинах оселився культ, відданий демонічній Раді Тіней. Цей культ, відомий як Палаючий Клинок, загрожує самій владі Орди над Дуротаром. Багато хто вважає, що Вождь орків Тралл знає про існування Клинка й свідомо не знищує його, сподіваючись, що члени культу приведуть його просто до Ради Тіней. Так чи інакше, темні сили, що виходять з Ущелини Люті Вогню, можуть зруйнувати все, за що боролися орки.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1496646158] = {
        ["english"] = { [1] = "Let me take a look at what you have to offer." },
        ["text"] = "Дай-но погляну, що ти маєш запропонувати.",
        ["npcs"] = { [1] = 12246 },
        ["roles"] = { ["reply"] = true },
    },
    [1532264737] = {
        ["english"] = { [1] = "Only the Horde can save us now." },
        ["text"] = "Тепер лише Орда може нас урятувати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3931980287] = {
        ["english"] = { [1] = "No one's ever stolen anything out of here. Not in the whole history of... the whole history!" },
        ["text"] = "Звідси ще ніколи нічого не крали. За всю історію... за всю історію!",
        ["npcs"] = { [1] = 2455, [2] = 2456, [3] = 2457 },
        ["roles"] = { ["greeting"] = true },
    },
    [3106290390] = {
        ["english"] = { [1] = "Leatherworking" },
        ["text"] = "Шкірництво",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [40] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [3555382276] = {
        ["english"] = { [1] = "Long ago, in a dimension of the cosmos unfathomable to mortal minds, there was born - if such a term can be used for it - a being of such unbelievable power that its very entrance into existence shattered all reality around it.$B$BKnown only as Murmur, it was the essence of sound, and to hear it speak was to know death eternal!" },
        ["text"] = "Давним-давно, у вимірі космосу, незбагненному для смертного розуму, народилася — якщо це слово взагалі доречне — істота такої неймовірної сили, що сама її поява розтрощила всю реальність довкола.$B$BЇї знали лише як Мурмур. Вона була самою сутністю звуку, а почути її голос означало пізнати вічну смерть!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1732904398] = {
        ["english"] = { [1] = "Kyra Windblade wields her blade with great skill.  She should be able to provide you with some training.  You'll find her at the Inn in Dolanaar." },
        ["text"] = "Кайра Вітроклинок майстерно володіє клинком.  Вона зможе трохи тебе навчити.  Знайдеш її в заїзді Доланаара.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [732641703] = {
        ["english"] = { [1] = "Ku ovah yonder, matey!  Dat scurvy bobo be all up inne quashie's face.  Dat hard-eared swab gonnna get salt, mon... gonna get keelhauled and gonna be made into a duppy, mon." },
        ["text"] = "Глянь-но он туди, друже!  Той цинготний бовдур лізе просто Кваші в лице.  Цього гостровухого сухопутного щура зараз добре просолять, друже... протягнуть під кілем і зроблять із нього дуппі, еге.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3099193843] = {
        ["english"] = { [1] = "Oh, ye like me eyepatch now do ya?  Well, just make sure that ya don't have ta be wearing one yerself now $g boyo : girly;." },
        ["text"] = "О, тобі подобається моя пов’язка на оці?  Тоді дивись, щоб самому не довелося таку носити, $g хлопче : дівчино;.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1598234945] = {
        ["english"] = { [1] = "Please, keep your voice down, $r. Hamat is old and needs her rest." },
        ["text"] = "Будь ласка, говори тихіше, $r. Гамат стара й потребує відпочинку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1353379464] = {
        ["english"] = { [1] = "Ja mon, I be collectin' up the fishy-fishy for the Horde. They gettin' ready for big war in the desert at Ahn'Qiraj, and askin' me to get them $2103w of the spotted yellowtail. But right now we only be havin' $2102w. You here to help?" },
        ["text"] = "Еге, друже, я тут збираю рибку-рибку для Орди. Вони готуються до великої війни в пустелі Ан’Кіражу й наказали мені назбирати $2103w плямистого жовтохвоста. А поки що маємо лише $2102w. Допоможеш?",
        ["npcs"] = { [1] = 15534 },
        ["roles"] = { ["greeting"] = true },
    },
}
for key, row in pairs(rows) do addonTable.gossip_hashed.rows[key] = row end
